insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('433b0c11-b879-5619-9e2c-76a2e79c24f7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 30 year old woman has had vulval itching and soreness with a thick white ''cottage cheese'' discharge for 4 days. Vaginal pH is 4.2. She is not pregnant. What is the SINGLE most appropriate treatment?', 'Vulvovaginal candidiasis causes itch, soreness and a thick white discharge with a normal pH (under 4.5). Treatment is a single dose of oral fluconazole or a clotrimazole pessary with cream. In pregnancy, only topical azoles are used (oral fluconazole should be avoided). Recurrent candidiasis (4 or more episodes a year) needs confirmation and an induction-maintenance regimen, and diabetes should be considered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('173ba4e5-ce49-5418-8a29-1a4bc70c1679', '433b0c11-b879-5619-9e2c-76a2e79c24f7', 'A', 'Oral metronidazole', false, 0),
  ('9bc94597-dbb7-5f5a-a020-cb638da1e9c8', '433b0c11-b879-5619-9e2c-76a2e79c24f7', 'B', 'Oral fluconazole 150 mg single dose (or clotrimazole pessary)', true, 1),
  ('9a6b259a-74f0-56fb-8ba6-8836e53a2aec', '433b0c11-b879-5619-9e2c-76a2e79c24f7', 'C', 'IM ceftriaxone', false, 2),
  ('014bdd68-5a16-5f10-a4d5-2014026b0125', '433b0c11-b879-5619-9e2c-76a2e79c24f7', 'D', 'Topical steroid cream', false, 3),
  ('ca8a014f-49e6-516b-a990-db21ac85d07f', '433b0c11-b879-5619-9e2c-76a2e79c24f7', 'E', 'Doxycycline', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9d5979a0-6596-5114-9248-45ba714bd05a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 40 year old woman would like a long-acting reversible contraceptive that does not affect her periods or contain hormones. She has no contraindications. What is the SINGLE most appropriate option?', 'The copper IUD is hormone-free, effective immediately and lasts 5-10 years. It may make periods heavier and more painful. If inserted at age 40 or over, it can stay in place until menopause. Hormonal methods may change bleeding patterns, and the LNG-IUS often reduces bleeding or stops periods altogether.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
