  ('85193981-189a-518a-af6d-3e1abdcd0bb9', '9d5979a0-6596-5114-9248-45ba714bd05a', 'A', 'Etonogestrel implant', false, 0),
  ('9956451c-6d32-54ba-8b88-d69e5eff4b46', '9d5979a0-6596-5114-9248-45ba714bd05a', 'B', 'Combined vaginal ring', false, 1),
  ('bbe5eb5a-bcf5-53fc-915b-26e3bc181516', '9d5979a0-6596-5114-9248-45ba714bd05a', 'C', 'Copper intrauterine device', true, 2),
  ('a3839c70-6631-5c72-87ff-b6063541e49a', '9d5979a0-6596-5114-9248-45ba714bd05a', 'D', 'Depot medroxyprogesterone acetate', false, 3),
  ('d654dbb8-7395-597d-8551-5c67b7b62616', '9d5979a0-6596-5114-9248-45ba714bd05a', 'E', 'Levonorgestrel intrauterine system', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2021855c-7837-5f93-96f8-62b515657a98', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 36 year old woman takes the combined oral contraceptive pill. She smokes 20 cigarettes a day and wants to continue her current contraception. According to UKMEC, what is the SINGLE most appropriate advice?', 'UKMEC classifies smoking 15 or more cigarettes a day at age 35 or over as category 4 (unacceptable risk) for combined hormonal contraception, because of cardiovascular and stroke risk. Progestogen-only methods or copper or hormonal IUDs are safe alternatives. Other UKMEC 4 conditions include migraine with aura, a history of VTE, BP of 160/100 mmHg or above, and breast cancer.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('717a1200-b738-56ff-add6-a6ae69b9919c', '2021855c-7837-5f93-96f8-62b515657a98', 'A', 'Stop the COCP because smoking at age 35 or over is UKMEC 4 (unacceptable risk) with 15 or more cigarettes a day', true, 0),
  ('79bf4097-eb23-5861-9d48-b63e9fabbee6', '2021855c-7837-5f93-96f8-62b515657a98', 'B', 'Continue the COCP', false, 1),
  ('d580019a-5773-5dd2-9e92-e10170f51206', '2021855c-7837-5f93-96f8-62b515657a98', 'C', 'Stop smoking for 1 week then continue', false, 2),
  ('edfdde8e-bc5b-537a-8285-c4efe45771ef', '2021855c-7837-5f93-96f8-62b515657a98', 'D', 'Switch to a higher-oestrogen pill', false, 3),
  ('ecec8376-3ff3-5c72-bc9d-9c73b6d2b44b', '2021855c-7837-5f93-96f8-62b515657a98', 'E', 'Double the dose of the COCP', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ca8df2fb-8227-57b9-a559-3440d48527a3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 23 year old woman taking the COCP (21-day pill) missed two pills in the first week of her packet. She had unprotected sex 2 days ago. What is the SINGLE most appropriate advice?', 'FSRH guidance: if 2 or more pills are missed (more than 48 hours late), take the most recent missed pill now, continue the pack and use extra precautions for 7 days. If the pills were missed in week 1 and she has had unprotected sex in the pill-free interval or week 1, emergency contraception should be considered. If missed in week 3, she should omit the pill-free interval.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1d3cceec-4e7e-5f7d-81a3-77ac0b2657c5', 'ca8df2fb-8227-57b9-a559-3440d48527a3', 'A', 'Stop the pill and restart next month', false, 0),
  ('da3d7a3a-32de-51da-8be5-f935e4b086a7', 'ca8df2fb-8227-57b9-a559-3440d48527a3', 'B', 'No action needed', false, 1),
  ('63576bef-50b7-5d23-8e86-5a92e9947fba', 'ca8df2fb-8227-57b9-a559-3440d48527a3', 'C', 'Take a 7-day break now', false, 2),
  ('c9da157e-e27a-54cc-ae7c-e6d2c9961cea', 'ca8df2fb-8227-57b9-a559-3440d48527a3', 'D', 'Take the most recent missed pill now, use condoms for 7 days and consider emergency contraception', true, 3),
  ('5456286b-c5f9-52b7-9e9c-2cf5e7e83437', 'ca8df2fb-8227-57b9-a559-3440d48527a3', 'E', 'Take all missed pills at once and no other action', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('79501a46-f82c-5dc2-a86c-b545ceab8b8b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 25 year old woman has been on the progestogen-only injection (Depo-Provera) for 2 years and wants to have a baby. What is the SINGLE most appropriate advice?', 'Return of fertility after depot medroxyprogesterone acetate can be delayed by up to a year. It is also linked to weight gain and a small reduction in bone density, which reverses after stopping. Other methods (implant, IUS, COCP, POP) allow a rapid return of fertility after stopping.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('87830fa7-d54a-5c11-8e0e-d675687a4d91', '79501a46-f82c-5dc2-a86c-b545ceab8b8b', 'A', 'The injection causes permanent infertility', false, 0),
  ('afe30666-1a04-5dae-8b8b-e545a7359227', '79501a46-f82c-5dc2-a86c-b545ceab8b8b', 'B', 'She must use condoms for 5 years', false, 1),
  ('0b47fd52-ce15-5814-9b07-4bbb80bcd235', '79501a46-f82c-5dc2-a86c-b545ceab8b8b', 'C', 'Switch to the implant before trying', false, 2),
  ('ce690459-3604-594c-acd2-ed56f12afed7', '79501a46-f82c-5dc2-a86c-b545ceab8b8b', 'D', 'Fertility may take up to 1 year to return after stopping the injection', true, 3),
  ('fb87b97a-7dad-5168-9a81-309d008ae394', '79501a46-f82c-5dc2-a86c-b545ceab8b8b', 'E', 'Fertility returns immediately', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('82993755-20f1-5280-9eae-4cbcdb146806', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 45 year old woman has had irregular heavy periods for 6 months. She is obese with a BMI of 38 kg/m2. She is concerned about endometrial cancer. Which test is the SINGLE most appropriate to investigate her bleeding?', 'Persistent intermenstrual or heavy irregular bleeding in women over 45, or with risk factors for endometrial hyperplasia or cancer (obesity, PCOS, tamoxifen, unopposed oestrogen), needs investigation. This is a transvaginal ultrasound and endometrial biopsy, with outpatient hysteroscopy if indicated. Endometrial hyperplasia without atypia is usually treated with the LNG-IUS.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
