  ('453d0f38-1a46-5d71-848e-c14524ad1ab6', '82993755-20f1-5280-9eae-4cbcdb146806', 'A', 'Transvaginal ultrasound and endometrial biopsy (hysteroscopy if indicated)', true, 0),
  ('5f6d23d4-d199-5255-ab4d-2e9b14a832ba', '82993755-20f1-5280-9eae-4cbcdb146806', 'B', 'Abdominal X-ray', false, 1),
  ('39b2a551-6ec5-5c55-aa27-e5c95cc50d42', '82993755-20f1-5280-9eae-4cbcdb146806', 'C', 'Pelvic MRI first-line', false, 2),
  ('41f9a0a0-a129-5640-893b-6cf68633edc1', '82993755-20f1-5280-9eae-4cbcdb146806', 'D', 'CA-125 alone', false, 3),
  ('c61a2447-2954-5a95-b0f0-97d9c6cdbeba', '82993755-20f1-5280-9eae-4cbcdb146806', 'E', 'Cervical screening', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3eab38d6-b1c1-5b77-a5a6-d9bddb2a3fcb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 25 year old woman has a smooth, painless, 2 cm swelling at the posterior aspect of the left labia majora. It has become red, hot, very tender and fluctuant over 3 days. What is the SINGLE most appropriate management?', 'A Bartholin''s gland cyst can become infected, forming an abscess at the 4 or 8 o''clock position of the vaginal opening. Management of an abscess is drainage, by Word catheter insertion or marsupialisation, with antibiotics if there is cellulitis. In women over 40, a biopsy may be needed to exclude carcinoma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cfaa15d2-a0c7-5e0f-9c23-dfadbb2df0d9', '3eab38d6-b1c1-5b77-a5a6-d9bddb2a3fcb', 'A', 'Reassurance only', false, 0),
  ('926b3add-4352-52a0-a800-ff83b7898dad', '3eab38d6-b1c1-5b77-a5a6-d9bddb2a3fcb', 'B', 'Excision of the vulva', false, 1),
  ('57b3af70-006e-561d-965d-fe2fbc5985ec', '3eab38d6-b1c1-5b77-a5a6-d9bddb2a3fcb', 'C', 'Incision and drainage with marsupialisation or a Word catheter', true, 2),
  ('3e0f7ff8-8437-5e0f-83a5-805e8a930bf8', '3eab38d6-b1c1-5b77-a5a6-d9bddb2a3fcb', 'D', 'Oral antibiotics alone', false, 3),
  ('db2bfc10-b1e8-5d7d-9652-b21534cd17c7', '3eab38d6-b1c1-5b77-a5a6-d9bddb2a3fcb', 'E', 'Cryotherapy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0574706a-ddb9-5774-840e-a742e1ed706d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 72 year old woman has had vulval itching for a year. Examination shows white, atrophic, crinkled patches around her vulva and anus in a ''figure of eight'' pattern, with some fusion of the labia. What is the SINGLE most appropriate treatment?', 'Lichen sclerosus is a chronic inflammatory skin condition causing white, atrophic, itchy plaques around the vulva and anus, leading to scarring and labial fusion. First-line treatment is the very potent topical steroid clobetasol propionate, with emollients. There is a small risk of vulval squamous cell carcinoma, so long-term follow-up is needed, with biopsy of persistent ulcers or lumps.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('300f0ec5-1f1c-591b-93be-90240efc97d1', '0574706a-ddb9-5774-840e-a742e1ed706d', 'A', 'Potent topical corticosteroid (clobetasol propionate)', true, 0),
  ('9b89d5d0-9b55-500f-a04b-e9a911a0971e', '0574706a-ddb9-5774-840e-a742e1ed706d', 'B', 'Vaginal oestrogen only', false, 1),
  ('d422b125-4f03-5fba-a9b0-4362f9baaef0', '0574706a-ddb9-5774-840e-a742e1ed706d', 'C', 'Vulvectomy', false, 2),
  ('9dca5156-0f46-5c3e-b170-826594f47527', '0574706a-ddb9-5774-840e-a742e1ed706d', 'D', 'Topical antifungal', false, 3),
  ('cef21a88-d57d-5b17-9b36-58e553568a80', '0574706a-ddb9-5774-840e-a742e1ed706d', 'E', 'Oral antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b7ba6bde-1a0d-50b1-abbf-7e676ef187bd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 42 year old woman has a smear showing high-grade dyskaryosis. At colposcopy, a biopsy shows CIN 3. What is the SINGLE most appropriate management?', 'CIN 2-3 is treated by excising the transformation zone, usually by LLETZ under local anaesthetic. Test of cure is an HPV test 6 months later. LLETZ slightly increases the risk of preterm birth in future pregnancies. Invasive cervical cancer is staged by FIGO, with treatment ranging from cone biopsy to radical hysterectomy or chemoradiotherapy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f144962e-6e35-5923-bee1-2be92a44095b', 'b7ba6bde-1a0d-50b1-abbf-7e676ef187bd', 'A', 'Chemoradiotherapy', false, 0),
  ('3576d1a7-2825-5de0-90e1-5f97120bb724', 'b7ba6bde-1a0d-50b1-abbf-7e676ef187bd', 'B', 'Large loop excision of the transformation zone (LLETZ)', true, 1),
  ('c6b8398b-d007-5c0d-8464-08fb1333662c', 'b7ba6bde-1a0d-50b1-abbf-7e676ef187bd', 'C', 'Repeat smear in 3 years', false, 2),
  ('fca58ad8-2372-5699-99a7-123b3673a981', 'b7ba6bde-1a0d-50b1-abbf-7e676ef187bd', 'D', 'Radical hysterectomy', false, 3),
  ('962b537e-7e46-5824-9a5a-05924e9443b5', 'b7ba6bde-1a0d-50b1-abbf-7e676ef187bd', 'E', 'No treatment', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cb9ede2f-9ac9-5be9-a37b-7cbde17311a8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 12 year old girl is due her HPV vaccine at school. Her mother asks what it protects against. What is the SINGLE most accurate answer?', 'The UK programme uses Gardasil 9 for boys and girls aged 12-13 (now a single dose). It protects against high-risk HPV 16 and 18 (about 70% of cervical cancers), other oncogenic types and types 6 and 11, which cause genital warts. Vaccinated women still need cervical screening. It does not treat existing infection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1fa5d153-45d7-5ce6-b0a4-0bc59e2c1678', 'cb9ede2f-9ac9-5be9-a37b-7cbde17311a8', 'A', 'It is only for girls', false, 0),
  ('e58d61b7-1f24-55f4-908e-f036fff7fff1', 'cb9ede2f-9ac9-5be9-a37b-7cbde17311a8', 'B', 'It protects against high-risk HPV types that cause most cervical, anal and oropharyngeal cancers, and against genital warts', true, 1),
  ('6c4a0ec3-e37a-5cbb-9587-a3b6388284d3', 'cb9ede2f-9ac9-5be9-a37b-7cbde17311a8', 'C', 'It protects against all sexually transmitted infections', false, 2),
  ('9b65aa52-0142-5799-80b7-e683b8aa3e0d', 'cb9ede2f-9ac9-5be9-a37b-7cbde17311a8', 'D', 'It removes the need for cervical screening', false, 3),
  ('803cb0bb-e637-5110-9126-37f8593063c1', 'cb9ede2f-9ac9-5be9-a37b-7cbde17311a8', 'E', 'It treats existing HPV infection', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('51236757-b944-5e40-9969-db98bd2870e6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 30 year old woman who is 28 weeks pregnant had chickenpox contact with her nephew 2 days ago. She is not sure if she had chickenpox as a child. What is the SINGLE most appropriate next step?', 'A pregnant woman with significant VZV exposure and uncertain immunity should have urgent VZV IgG testing. If she is non-immune, post-exposure prophylaxis with an oral antiviral (aciclovir or valaciclovir from day 7 to 14 after exposure) is recommended. VZIG is used in specific cases. The live varicella vaccine is contraindicated in pregnancy. Maternal varicella risks pneumonia, fetal varicella syndrome and neonatal varicella.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('16ccd858-dfec-53e2-a675-cd2078417cfe', '51236757-b944-5e40-9969-db98bd2870e6', 'A', 'Give aciclovir immediately without testing', false, 0),
  ('83a7e804-8f9e-5f47-94e2-7d0843a136c1', '51236757-b944-5e40-9969-db98bd2870e6', 'B', 'Reassure as there is no risk in the third trimester', false, 1),
  ('3b1aa186-7728-57ce-9f9f-428ac8f6cf49', '51236757-b944-5e40-9969-db98bd2870e6', 'C', 'Give the varicella vaccine', false, 2),
  ('9cada83b-17ee-5e4d-93fa-6ef69778d38b', '51236757-b944-5e40-9969-db98bd2870e6', 'D', 'Check her varicella-zoster IgG urgently', true, 3),
  ('074c7979-2736-5ec4-b4aa-d7f401993220', '51236757-b944-5e40-9969-db98bd2870e6', 'E', 'Admit for IV aciclovir', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('101013dc-7842-54d1-b180-08b7a92a2a95', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 34 year old woman who is 37 weeks pregnant has a known genital herpes recurrence, with lesions now visible. This is not her first episode. She asks about mode of delivery. What is the SINGLE most appropriate advice?', 'For recurrent genital herpes at delivery, the risk of neonatal herpes is low, so vaginal delivery is usually offered (caesarean section may be discussed). Suppressive aciclovir from 36 weeks reduces recurrences. A primary episode in the third trimester (especially within 6 weeks of delivery) carries a high risk, so caesarean section is recommended.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7f7f6013-7433-5506-b9dc-a4e7ce9fe56c', '101013dc-7842-54d1-b180-08b7a92a2a95', 'A', 'Avoid all antivirals', false, 0),
  ('e3142e87-0eab-5627-8349-648b4f20a402', '101013dc-7842-54d1-b180-08b7a92a2a95', 'B', 'Induce labour at 37 weeks', false, 1),
  ('337af361-1a16-53fb-aa3b-ccba3c9dc53f', '101013dc-7842-54d1-b180-08b7a92a2a95', 'C', 'Vaginal delivery is reasonable; the neonatal risk from a recurrent episode is low', true, 2),
  ('a569a701-0da0-5b4d-915a-794beea0d5a2', '101013dc-7842-54d1-b180-08b7a92a2a95', 'D', 'Postpone delivery until 42 weeks', false, 3),
  ('e40456d9-53c7-5517-9432-fc5efb9691a7', '101013dc-7842-54d1-b180-08b7a92a2a95', 'E', 'Elective caesarean section is mandatory', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a59f1f6a-77a0-5b7c-8205-3079523485e0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 27 year old woman is HIV positive and 32 weeks pregnant. She is taking antiretroviral therapy and her viral load is under 50 copies/mL at 36 weeks. What is the SINGLE most appropriate advice about delivery and feeding?', 'With a viral load under 50 copies/mL at 36 weeks, vaginal delivery is recommended. A higher viral load needs caesarean section (with IV zidovudine if over 1,000). Neonates receive post-exposure prophylaxis. BHIVA advises formula feeding, though women on effective ART with a suppressed viral load who choose to breastfeed can be supported with close monitoring.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c398bd5b-8449-5618-b534-41224bfb0f33', 'a59f1f6a-77a0-5b7c-8205-3079523485e0', 'A', 'Breastfeeding is recommended without restrictions', false, 0),
  ('0aa8d275-8533-564e-b58e-fb2cc1051762', 'a59f1f6a-77a0-5b7c-8205-3079523485e0', 'B', 'Caesarean section is mandatory', false, 1),
  ('114df688-5582-5bdf-8da8-589f24471156', 'a59f1f6a-77a0-5b7c-8205-3079523485e0', 'C', 'Planned vaginal delivery is appropriate; breastfeeding is generally not recommended in the UK (unless specific criteria are met with specialist support)', true, 2),
  ('ff8a61d5-22cc-5735-b74e-617482ab13aa', 'a59f1f6a-77a0-5b7c-8205-3079523485e0', 'D', 'Deliver at 34 weeks', false, 3),
  ('f10cc0ee-d1cd-5069-9c3b-b77197cf3f9d', 'a59f1f6a-77a0-5b7c-8205-3079523485e0', 'E', 'Stop antiretrovirals before delivery', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('28855b88-08c1-51aa-9730-d4f66de4eaa0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 22 year old woman requires long-term contraception and is reluctant to take regular tablets. She has two children. She is a shift worker. Her BP is 138/81 mmHg and BMI 26 kg/m². Investigations: Transvaginal ultrasound: Enlarged uterus with multiple fibroids and uterine cavity distortion Which is the most appropriate contraception?', 'She wants long-acting contraception without daily tablets. Fibroids that distort the uterine cavity are a contraindication to intrauterine devices (UKMEC 3), so the Mirena and copper IUD are unsuitable. The etonogestrel implant is the most effective option here, lasting 3 years. Her borderline BP also makes oestrogen-containing methods less suitable.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d2ad7a6c-211e-5670-89b3-38dd42fa828f', '28855b88-08c1-51aa-9730-d4f66de4eaa0', 'A', 'Combined oral contraceptive pill', false, 0),
  ('4c9f46b4-cb40-510e-9f5e-27554bc1ac0e', '28855b88-08c1-51aa-9730-d4f66de4eaa0', 'B', 'Diaphragm', false, 1),
  ('698bec2f-eb24-5141-bd18-1d8645893784', '28855b88-08c1-51aa-9730-d4f66de4eaa0', 'C', 'Etonogestrel implant (Implanon)', true, 2),
  ('eb6b5de4-fc2b-55a5-8806-9dd6e4ec8091', '28855b88-08c1-51aa-9730-d4f66de4eaa0', 'D', 'Levonorgestrel-releasing intrauterine system (Mirena coil)', false, 3),
  ('0c0dee9a-fdee-5784-923c-b57cbfcd0757', '28855b88-08c1-51aa-9730-d4f66de4eaa0', 'E', 'Tubal ligation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('574ceb1f-22cf-525b-a330-4eab231e29f2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 26 year old woman has severe abdominal pain and heavy vaginal bleeding and is seen on the labour ward. She is 40 weeks pregnant in her first pregnancy. Her uterus is tender and hard. The fetal heart rate is 180 bpm. Which is the most likely diagnosis?', 'Severe abdominal pain, bleeding, a tender ''woody'' hard uterus and fetal tachycardia (distress) are classic for placental abruption. It needs urgent resuscitation, coagulation monitoring (DIC risk) and delivery. Placenta praevia causes painless bleeding with a soft uterus.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
