  ('efd88350-2d27-5523-bdff-2813e166a5cc', '574ceb1f-22cf-525b-a330-4eab231e29f2', 'A', 'Cervical ectropion', false, 0),
  ('feb743ac-7922-51ab-b318-6075a3ab1624', '574ceb1f-22cf-525b-a330-4eab231e29f2', 'B', 'Disseminated intravascular coagulation', false, 1),
  ('62483915-1860-5f3e-a16a-46b469a845cf', '574ceb1f-22cf-525b-a330-4eab231e29f2', 'C', 'Placenta praevia', false, 2),
  ('937b8e75-3acc-5fd0-9b27-f0eb12d79a23', '574ceb1f-22cf-525b-a330-4eab231e29f2', 'D', 'Placental abruption', true, 3),
  ('0f4a72e6-bea8-58fc-9575-f99eaabcd91e', '574ceb1f-22cf-525b-a330-4eab231e29f2', 'E', 'Vasa praevia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c7c33070-2672-5e74-a1dd-d4f83d1c2438', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 28 year old woman has a generalised seizure and is admitted to the antenatal ward. She is 38 weeks pregnant. Her BP is 190/120 mmHg Investigations: Urinalysis: protein 3+ Which is the most appropriate initial intravenous management?', 'A seizure in a pregnant woman with severe hypertension and proteinuria is eclampsia. IV magnesium sulfate (a 4 g loading dose, then an infusion) is the anticonvulsant of choice, alongside antihypertensives (labetalol or hydralazine) and planning delivery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
