  ('babc272f-1548-52c8-ad58-38b862c756f7', 'c7c33070-2672-5e74-a1dd-d4f83d1c2438', 'B', 'Hydralazine', false, 1),
  ('182a1730-5c6f-5cee-a37f-bd7f5b2ea119', 'c7c33070-2672-5e74-a1dd-d4f83d1c2438', 'C', 'Levetiracetam', false, 2),
  ('a8e84d37-2d68-50b1-9d8d-7d945da4aed3', 'c7c33070-2672-5e74-a1dd-d4f83d1c2438', 'D', 'Magnesium sulfate', true, 3),
  ('7a342768-ff1e-5f47-8ad7-715cb4a17101', 'c7c33070-2672-5e74-a1dd-d4f83d1c2438', 'E', 'Phenytoin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('df1a91dd-0a91-562b-a6fa-b503ede0c68d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 42 year old woman tests positive for high-risk human papillomavirus (HPV) on a routine cervical smear and is seen in the GP surgery. Investigations: Cervical Cytology: moderate dyskaryosis. Which is the most appropriate management?', 'High-risk HPV positive with abnormal cytology (any dyskaryosis) needs referral for colposcopy. High-grade (moderate or severe) dyskaryosis should be seen within 2 weeks. HPV positive with normal cytology is retested in 12 months.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
