  ('d6755439-9025-5f10-9b16-23b9876d93f2', 'df1a91dd-0a91-562b-a6fa-b503ede0c68d', 'A', 'No action required', false, 0),
  ('05152960-ff3b-52d1-b4af-1fe0c2223d97', 'df1a91dd-0a91-562b-a6fa-b503ede0c68d', 'B', 'Refer for colposcopy', true, 1),
  ('a5217f08-8940-5012-af97-17752c412ee3', 'df1a91dd-0a91-562b-a6fa-b503ede0c68d', 'C', 'Repeat smear in 3 months', false, 2),
  ('cdb25b6d-bf98-581b-9d36-af35c88d1717', 'df1a91dd-0a91-562b-a6fa-b503ede0c68d', 'D', 'Repeat smear in 1 year', false, 3),
  ('22797d1e-62af-5416-8a57-db9512fa4f09', 'df1a91dd-0a91-562b-a6fa-b503ede0c68d', 'E', 'Repeat smear in 3 years', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fbad5f59-9579-543f-86c7-5bc87c2a72c9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 28 year old woman attends her GP as she has been trying to conceive for 12 months without success. She has a regular 32 day menstrual cycle. She is worried she is not ovulating and blood test for serum progesterone level is arranged. Which day of her menstrual cycle should be used to take this sample?', 'Mid-luteal progesterone is measured 7 days before the expected next period to confirm ovulation. With a 32-day cycle, this is day 32 - 7 = day 25. The traditional ''day 21'' only applies to 28-day cycles.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
