  ('dca368ac-2917-5802-89f8-004b08ebcc1c', 'fbad5f59-9579-543f-86c7-5bc87c2a72c9', 'A', '7', false, 0),
  ('59e45b99-b10f-51fd-a8ba-569d34b31f10', 'fbad5f59-9579-543f-86c7-5bc87c2a72c9', 'B', '14', false, 1),
  ('5c04e427-300f-5934-948f-c9cb7786a255', 'fbad5f59-9579-543f-86c7-5bc87c2a72c9', 'C', '21', false, 2),
