insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5a8357ca-cbd8-5f26-b44e-a4d108a5e751', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 32 year old woman who is 24 weeks pregnant has chest pain and is seen on the Maternity Unit. Her pulse rate is 100 bpm, BP 110/70 mmHg, respiratory rate 28 breaths per minute and oxygen saturation 96% breathing air. Investigations: CT Pulmonary angiography: segmental filling defects in right middle and lower lobe branches of the pulmonary arterial tree. Which is the most appropriate management?', 'Pulmonary embolism in pregnancy in a stable patient is treated with therapeutic low molecular weight heparin for the rest of the pregnancy and at least 6 weeks postpartum (3 months in total minimum). Warfarin is teratogenic and DOACs are not recommended in pregnancy. Thrombolysis is reserved for massive PE with haemodynamic compromise.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('08706f2c-5eda-5246-ad04-26735ebe0caa', '5a8357ca-cbd8-5f26-b44e-a4d108a5e751', 'A', 'Intravenous thrombolysis', false, 0),
  ('86961725-5522-518e-bb6a-3ac9bc7f6eab', '5a8357ca-cbd8-5f26-b44e-a4d108a5e751', 'B', 'Intravenous thrombolysis followed by low molecular weight heparin', false, 1),
  ('d972892f-220b-501c-a78f-00dd5476543c', '5a8357ca-cbd8-5f26-b44e-a4d108a5e751', 'C', 'Low molecular weight heparin', true, 2),
  ('ef7dc4c5-1890-5283-867b-8126889f95b3', '5a8357ca-cbd8-5f26-b44e-a4d108a5e751', 'D', 'Surgical embolectomy followed by direct oral anticoagulant', false, 3),
  ('9ddb1d3a-60bc-5625-8453-e688e27c5cc1', '5a8357ca-cbd8-5f26-b44e-a4d108a5e751', 'E', 'Warfarin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ca55649e-33f2-5e52-b87c-9430762a14f5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 25 year old woman has irregular periods and is seen at her GP surgery. She has a menstrual period every 4 to 9 weeks. She also has an acne rash on her face. She has no other medical conditions or family history. Her BP is 127/83 mmHg and BMI 24.3 kg/m2. Investigations: Glycated haemoglobin (HbA1c) 33 mmol/mol (20–42) Testosterone 4.2 nmol/L (0.2–2.9) Sex hormone binding globulin 38 nmol/L (40–120) Thyroid stimulating hormone 2.3 mU/L (0.3–4.2) Prolactin 143 U/L (100–500) Which treatment is most appropriate to manage her symptoms?', 'Irregular periods and acne with raised testosterone suggest PCOS. In a woman who does not want to conceive, the COCP regulates periods, protects the endometrium and improves acne and hirsutism. Metformin is not first-line here because her HbA1c and BMI are normal.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('eb05c8b5-8859-5210-877b-502301597c84', 'ca55649e-33f2-5e52-b87c-9430762a14f5', 'A', 'Combined oral contraceptive pill', true, 0),
  ('4d3c63b7-1eee-5c5b-9eea-b1bbf539be0a', 'ca55649e-33f2-5e52-b87c-9430762a14f5', 'B', 'Metformin', false, 1),
  ('674d64fe-4790-5d4e-98c8-d1e7d9c000d5', 'ca55649e-33f2-5e52-b87c-9430762a14f5', 'C', 'Minoxidil', false, 2),
  ('86e60a4c-b8c2-54db-a416-4aeb099a8b41', 'ca55649e-33f2-5e52-b87c-9430762a14f5', 'D', 'Progestogen-only pill', false, 3),
  ('99f63cf5-6b0f-5b76-8927-ab8e4217d2f1', 'ca55649e-33f2-5e52-b87c-9430762a14f5', 'E', 'Tranexamic acid', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e5bc5c71-dc2a-5638-a205-d7482e6698cc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 68 year old woman presents to the Emergency Department with a severely painful red left eye, blurred vision and headache that started this evening while she was watching television in dim light. She has vomited twice and sees coloured haloes around lights. The left pupil is fixed and mid-dilated, and the eye feels hard to touch. What is the SINGLE most likely diagnosis?', 'Acute angle-closure glaucoma happens when the iris blocks drainage of aqueous humour, often triggered by pupil dilation in dim light. It causes a sudden rise in intraocular pressure: a painful red eye, haloes, a fixed mid-dilated pupil, corneal oedema, a hard eye and systemic upset. Refer to ophthalmology immediately. Treatment includes pilocarpine, a topical beta-blocker and IV acetazolamide, followed by laser iridotomy. Anterior uveitis causes a small, irregular pupil.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d9165833-24e0-5b58-a75d-1c713f5b7a09', 'e5bc5c71-dc2a-5638-a205-d7482e6698cc', 'A', 'Bacterial conjunctivitis', false, 0),
  ('0d7878da-7a37-5366-880c-7ee84a6a1bb4', 'e5bc5c71-dc2a-5638-a205-d7482e6698cc', 'B', 'Acute angle-closure glaucoma', true, 1),
  ('eb7db7f5-2957-5f07-9409-15528d1b9868', 'e5bc5c71-dc2a-5638-a205-d7482e6698cc', 'C', 'Anterior uveitis', false, 2),
  ('f67cb0fa-5dce-5d65-b44c-c562d8040d12', 'e5bc5c71-dc2a-5638-a205-d7482e6698cc', 'D', 'Scleritis', false, 3),
  ('a5d6eb92-c168-5b59-bf24-dc255a9a6648', 'e5bc5c71-dc2a-5638-a205-d7482e6698cc', 'E', 'Migraine with aura', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c3445624-76af-54b0-8414-bad1a6055d9b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 72 year old man with atrial fibrillation presents with sudden, painless, complete loss of vision in his right eye 1 hour ago. He has a right relative afferent pupillary defect. Fundoscopy shows a pale retina with a cherry-red spot at the macula. What is the SINGLE most likely diagnosis?', 'Sudden painless monocular vision loss with a pale retina and a cherry-red spot (the choroid seen through the thin fovea) is central retinal artery occlusion, an ''eye stroke'', often embolic. It needs immediate ophthalmology and stroke assessment. Giant cell arteritis must be excluded in older patients with an urgent ESR and CRP. Central retinal vein occlusion causes a ''stormy sunset'' fundus with widespread haemorrhages.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7c6d8ceb-d3bb-566a-8ae2-b29e1c48a97a', 'c3445624-76af-54b0-8414-bad1a6055d9b', 'A', 'Central retinal artery occlusion', true, 0),
  ('152f5f65-0937-5a78-aad8-8aea31ad906c', 'c3445624-76af-54b0-8414-bad1a6055d9b', 'B', 'Vitreous haemorrhage', false, 1),
  ('6b7d5e2b-6655-5875-ac80-1a9f67bdd4b0', 'c3445624-76af-54b0-8414-bad1a6055d9b', 'C', 'Central retinal vein occlusion', false, 2),
  ('b73c3230-4d65-5267-9edc-2f85ae278c71', 'c3445624-76af-54b0-8414-bad1a6055d9b', 'D', 'Retinal detachment', false, 3),
  ('22f77c59-2621-5f75-8f4f-cebe056a3bf3', 'c3445624-76af-54b0-8414-bad1a6055d9b', 'E', 'Acute angle-closure glaucoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('24bfcb8a-da53-5f5f-b260-37d0f73013eb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 56 year old man who is very short-sighted has 2 days of new floaters and flashing lights in his left eye. Today he noticed a dark shadow spreading from the edge of his vision towards the centre. His eye is not painful or red. What is the SINGLE most appropriate management?', 'Flashes and floaters followed by a curtain-like shadow suggest rhegmatogenous retinal detachment. Myopia is a major risk factor. It needs same-day ophthalmology assessment for surgical repair. Outcome is better if the macula is still attached. New flashes and floaters alone (posterior vitreous detachment) also need same-day assessment to exclude a retinal tear.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4eda71e0-326d-56fa-8bb8-186cadc7b3a0', '24bfcb8a-da53-5f5f-b260-37d0f73013eb', 'A', 'Routine optician review in 2 weeks', false, 0),
  ('9c4e982d-6ba7-58ae-97d1-a45121f49a66', '24bfcb8a-da53-5f5f-b260-37d0f73013eb', 'B', 'Prescribe a topical steroid', false, 1),
  ('53b07651-c033-56fa-a3c0-3781a30d0852', '24bfcb8a-da53-5f5f-b260-37d0f73013eb', 'C', 'Topical chloramphenicol', false, 2),
  ('52aa8cfd-ae27-5b0c-bdc9-560c95f87857', '24bfcb8a-da53-5f5f-b260-37d0f73013eb', 'D', 'Same-day referral to ophthalmology', true, 3),
  ('743fa893-3165-5dfc-a604-dfffee04f2d1', '24bfcb8a-da53-5f5f-b260-37d0f73013eb', 'E', 'Reassure as floaters are common with age', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('20628e75-fb0e-5dd7-84cf-1c6ccb17c53f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 74 year old woman has 2 days of a painful, blistering rash over her left forehead and upper eyelid that stops at the midline. There are vesicles on the tip of her nose and her left eye is red. What is the SINGLE most appropriate management?', 'This is herpes zoster ophthalmicus (shingles in the ophthalmic division of the trigeminal nerve). Vesicles on the tip of the nose (Hutchinson''s sign, nasociliary nerve) suggest a higher risk of eye involvement. Start an oral antiviral within 72 hours (aciclovir, valaciclovir or famciclovir), and refer the same day because of the risk of keratitis, uveitis and vision loss. Steroid drops must not be started without ophthalmology advice.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d7ca0945-b931-560b-b4a5-b23dd3ef4895', '20628e75-fb0e-5dd7-84cf-1c6ccb17c53f', 'A', 'Topical steroid drops only', false, 0),
  ('ac107fc2-3c18-58d5-b3c7-e0598b818ee6', '20628e75-fb0e-5dd7-84cf-1c6ccb17c53f', 'B', 'Topical antibiotic only', false, 1),
  ('84fe30e7-cd23-583c-8852-ef424b9587d3', '20628e75-fb0e-5dd7-84cf-1c6ccb17c53f', 'C', 'Oral flucloxacillin', false, 2),
  ('46af5348-f03e-5018-a661-84b2201e33b7', '20628e75-fb0e-5dd7-84cf-1c6ccb17c53f', 'D', 'Oral antiviral (such as aciclovir) and same-day ophthalmology referral', true, 3),
  ('91fb3bc8-084c-53fc-9b55-fe1fdc92a78b', '20628e75-fb0e-5dd7-84cf-1c6ccb17c53f', 'E', 'Reassure; it will settle', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fe55c944-6d8a-52f6-9302-8c914d48984f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 34 year old contact lens wearer has had a painful red right eye for 1 day with photophobia and blurred vision. Fluorescein staining shows a corneal ulcer. What is the SINGLE most appropriate management?', 'Microbial keratitis (corneal ulcer) in contact lens wearers is an emergency because Pseudomonas and Acanthamoeba can rapidly threaten vision. The patient needs same-day ophthalmology assessment for corneal scrapes and intensive topical antibiotics. Contact lenses should be removed. Steroids must not be used without specialist advice.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4f7f85f2-b32f-517b-bf0e-1bc2efa944a0', 'fe55c944-6d8a-52f6-9302-8c914d48984f', 'A', 'Artificial tears', false, 0),
  ('400e3215-678d-5bb3-af1f-2eb10cfed3fa', 'fe55c944-6d8a-52f6-9302-8c914d48984f', 'B', 'Topical chloramphenicol and discharge without follow-up', false, 1),
  ('a6a05207-a6fa-5b22-b734-c12df8a6fbbf', 'fe55c944-6d8a-52f6-9302-8c914d48984f', 'C', 'Topical steroid drops', false, 2),
  ('3d265273-4bb5-5517-a2ea-7af06c48c3ad', 'fe55c944-6d8a-52f6-9302-8c914d48984f', 'D', 'Oral antibiotics and review in 1 week', false, 3),
  ('2fe8fa5e-d0d8-545c-8fa6-dfb33be6ce40', 'fe55c944-6d8a-52f6-9302-8c914d48984f', 'E', 'Same-day ophthalmology referral; stop contact lens use', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3d191b01-144d-5014-8faa-d55c56c227a2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 35 year old man with ankylosing spondylitis has had a painful red eye with photophobia and blurred vision for 2 days. The pupil is small and irregular and there is redness around the cornea (ciliary flush). What is the SINGLE most likely diagnosis?', 'Anterior uveitis (iritis) causes pain, photophobia, blurred vision, ciliary flush, a small or irregular pupil (from posterior synechiae) and hypopyon. It is associated with HLA-B27 conditions (ankylosing spondylitis, reactive arthritis, IBD, psoriasis), sarcoidosis and Behçet''s. It needs same-day ophthalmology referral for steroid and cycloplegic drops.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1ba4a102-3b90-5df8-a746-92af92d1ecf1', '3d191b01-144d-5014-8faa-d55c56c227a2', 'A', 'Acute angle-closure glaucoma', false, 0),
  ('33181e6e-5d65-57f6-b632-530078704a86', '3d191b01-144d-5014-8faa-d55c56c227a2', 'B', 'Episcleritis', false, 1),
  ('e677da19-81a1-5774-bf78-8698b6281551', '3d191b01-144d-5014-8faa-d55c56c227a2', 'C', 'Subconjunctival haemorrhage', false, 2),
  ('857c2062-b981-5ab4-add1-1371e0da6d1c', '3d191b01-144d-5014-8faa-d55c56c227a2', 'D', 'Anterior uveitis', true, 3),
  ('19e97494-8ace-5c86-8cf5-c0023dcebb9b', '3d191b01-144d-5014-8faa-d55c56c227a2', 'E', 'Conjunctivitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('163e4ff4-7f6b-525b-a76d-582619966a4e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 40 year old woman has a red, mildly uncomfortable left eye for 3 days. The redness is in one sector of the eye, and the vessels move when gently pushed with a cotton bud. Vision and pupils are normal. What is the SINGLE most likely diagnosis?', 'Episcleritis causes mild discomfort and sectoral redness with mobile vessels, and vision is preserved. It is often self-limiting, managed with artificial tears and sometimes oral NSAIDs. Scleritis causes severe, boring pain, tenderness and deep immobile vessels, and is associated with rheumatoid arthritis and vasculitis. It needs urgent referral because it can threaten sight.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f53f54ca-216b-586f-8cfc-e447ae999325', '163e4ff4-7f6b-525b-a76d-582619966a4e', 'A', 'Acute glaucoma', false, 0),
  ('d76bf18a-04b6-56c9-ac18-a68a1ae6f5b5', '163e4ff4-7f6b-525b-a76d-582619966a4e', 'B', 'Anterior uveitis', false, 1),
  ('20fea1df-7795-5011-b68d-9e33d264c639', '163e4ff4-7f6b-525b-a76d-582619966a4e', 'C', 'Scleritis', false, 2),
  ('69f43ab8-bf96-50a8-ae07-e057ccfa3db2', '163e4ff4-7f6b-525b-a76d-582619966a4e', 'D', 'Keratitis', false, 3),
  ('4c2161c0-eae6-5157-9ea9-b95e3ed4bf89', '163e4ff4-7f6b-525b-a76d-582619966a4e', 'E', 'Episcleritis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a74407ca-cd91-574e-b0a5-ef8428d01a53', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 50 year old woman has a bright red patch on the white of her eye that she noticed this morning. She has no pain, discharge or visual change. Her BP is 136/84 mmHg. She is not on anticoagulants. What is the SINGLE most appropriate management?', 'Subconjunctival haemorrhage is a painless, well-defined red patch from a ruptured conjunctival vessel, often after coughing, straining or minor trauma. It resolves in 2-3 weeks. BP should be checked, and the INR in patients on warfarin. Recurrent episodes, or those after significant trauma (consider globe injury), need further assessment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9b716946-5d8c-59ad-96e8-6dc401dc888b', 'a74407ca-cd91-574e-b0a5-ef8428d01a53', 'A', 'Reassure; subconjunctival haemorrhage resolves within 2-3 weeks (check BP)', true, 0),
  ('226baac6-32a6-5f96-a327-2c30df78c67d', 'a74407ca-cd91-574e-b0a5-ef8428d01a53', 'B', 'Topical steroids', false, 1),
  ('673b3dec-146a-5b17-8e91-dc97be2b7336', 'a74407ca-cd91-574e-b0a5-ef8428d01a53', 'C', 'Urgent ophthalmology referral', false, 2),
  ('f8d14b3a-39b8-5f7c-9787-3aaa00048aaa', 'a74407ca-cd91-574e-b0a5-ef8428d01a53', 'D', 'Topical antibiotics', false, 3),
  ('ba7b46d7-fa2b-52f0-bf8d-edf3f8d527bb', 'a74407ca-cd91-574e-b0a5-ef8428d01a53', 'E', 'Stop aspirin permanently', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('254608ad-ba29-50f6-ac87-fe94dca561f9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 62 year old man has type 2 diabetes. Retinal screening shows cotton wool spots, multiple blot haemorrhages and venous beading, without new vessels. Visual acuity is normal. What is the SINGLE most appropriate classification and action?', 'Diabetic retinopathy grades: background (microaneurysms, dot-blot haemorrhages, hard exudates), pre-proliferative (cotton wool spots, venous beading, IRMA, multiple haemorrhages) and proliferative (new vessels, treated with panretinal photocoagulation or anti-VEGF). Maculopathy (exudates or oedema near the macula) threatens central vision and is treated with intravitreal anti-VEGF. Glycaemic and BP control reduce progression.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a5df0e82-cbf3-56ed-a6cc-01f55b24c8da', '254608ad-ba29-50f6-ac87-fe94dca561f9', 'A', 'Background retinopathy; annual screening only', false, 0),
  ('a791c2b3-985c-538d-9a84-0cc176764deb', '254608ad-ba29-50f6-ac87-fe94dca561f9', 'B', 'Proliferative retinopathy; immediate laser', false, 1),
  ('9fd6715a-b822-5ba0-8156-d732fb4b8dd8', '254608ad-ba29-50f6-ac87-fe94dca561f9', 'C', 'Diabetic maculopathy; intravitreal injection', false, 2),
  ('b48a3f3b-681c-54a4-8c47-68c139dcf726', '254608ad-ba29-50f6-ac87-fe94dca561f9', 'D', 'Normal retina', false, 3),
  ('bd96dbd5-aa54-5ce7-93af-09754f3adc18', '254608ad-ba29-50f6-ac87-fe94dca561f9', 'E', 'Pre-proliferative (severe non-proliferative) diabetic retinopathy; refer to ophthalmology', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0dac060e-9875-5c4b-8ce2-2c511db28270', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 78 year old woman has noticed central visual distortion (straight lines appear wavy) and a blurred patch in the centre of her vision over 2 weeks. Amsler grid testing shows distortion. What is the SINGLE most appropriate management?', 'Wet (neovascular) AMD causes rapid central visual loss and distortion (metamorphopsia) from choroidal neovascularisation. It needs urgent referral, because treatment with intravitreal anti-VEGF injections preserves vision. Dry AMD (drusen, geographic atrophy) progresses slowly with no specific treatment, though antioxidant supplements may slow progression. Smoking is a major risk factor.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('97d6051d-2770-5405-a902-64b32868830a', '0dac060e-9875-5c4b-8ce2-2c511db28270', 'A', 'Reassure; normal ageing', false, 0),
  ('ac9caaaf-82a5-5b02-a369-cf11b19dd204', '0dac060e-9875-5c4b-8ce2-2c511db28270', 'B', 'Topical steroid', false, 1),
  ('c1c06878-9ecc-5de8-a768-5be81f09b379', '0dac060e-9875-5c4b-8ce2-2c511db28270', 'C', 'Glasses only', false, 2),
  ('ff6484bb-5a18-5495-8a66-38b7c39d841b', '0dac060e-9875-5c4b-8ce2-2c511db28270', 'D', 'Urgent ophthalmology referral (within 1 week) for possible wet age-related macular degeneration', true, 3),
  ('8b0ba0f8-c70c-5726-b64f-cc799f9b6003', '0dac060e-9875-5c4b-8ce2-2c511db28270', 'E', 'Routine optician review in 6 months', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5a36f938-6c73-5294-995a-1133ed44a125', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 65 year old man of African-Caribbean origin has raised intraocular pressure (26 mmHg) at a routine optician''s check, with cupped optic discs and peripheral visual field loss. He has no symptoms. What is the SINGLE most appropriate first-line treatment?', 'Primary open-angle glaucoma is a chronic optic neuropathy, often with raised intraocular pressure. It is asymptomatic until late peripheral field loss. Risk factors include age, family history, African-Caribbean origin and myopia. NICE recommends a prostaglandin analogue (latanoprost) first-line, which can darken the iris and lengthen eyelashes. Selective laser trabeculoplasty is now often first-line. First-degree relatives qualify for free NHS eye tests.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('af5b49cc-be14-50b8-b24e-2dc367f46d5b', '5a36f938-6c73-5294-995a-1133ed44a125', 'A', 'Prostaglandin analogue eye drops (e.g. latanoprost)', true, 0),
  ('396f1957-e6da-5d4d-a439-4526ac42cbe8', '5a36f938-6c73-5294-995a-1133ed44a125', 'B', 'Pilocarpine first-line', false, 1),
  ('0a1b777d-65fa-5ec5-b358-d9fa2877755f', '5a36f938-6c73-5294-995a-1133ed44a125', 'C', 'Topical steroid', false, 2),
  ('631a6eb0-a9b4-537f-a2c2-38d708996c88', '5a36f938-6c73-5294-995a-1133ed44a125', 'D', 'No treatment', false, 3),
  ('e2bc02b7-b9be-52c9-bdc6-0c158bfc806c', '5a36f938-6c73-5294-995a-1133ed44a125', 'E', 'Oral acetazolamide long-term', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3387e2db-d34d-5b43-aee8-841fb4b06b64', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 68 year old man with hypertension has sudden painless blurring of vision in his left eye. Fundoscopy shows widespread flame haemorrhages, dilated tortuous veins and cotton wool spots in all quadrants (''stormy sunset''). What is the SINGLE most likely diagnosis?', 'CRVO causes sudden painless visual loss with widespread haemorrhages (''blood and thunder''). Risk factors include hypertension, diabetes, glaucoma, hyperviscosity and age. Management is referral to ophthalmology and control of risk factors. Macular oedema is treated with anti-VEGF, and neovascularisation with laser, because neovascular glaucoma is a complication.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e88c0aed-043c-59f7-85fe-3bcb0855c6f3', '3387e2db-d34d-5b43-aee8-841fb4b06b64', 'A', 'Retinal detachment', false, 0),
  ('5d76b53c-8180-5455-a4ee-83e6b48a60d3', '3387e2db-d34d-5b43-aee8-841fb4b06b64', 'B', 'Vitreous haemorrhage', false, 1),
  ('d70b3e04-6cd8-5e17-9163-0b187c0b1554', '3387e2db-d34d-5b43-aee8-841fb4b06b64', 'C', 'Central retinal artery occlusion', false, 2),
  ('16fc158c-9793-505b-84a1-8c4a987a6a7b', '3387e2db-d34d-5b43-aee8-841fb4b06b64', 'D', 'Diabetic retinopathy', false, 3),
  ('1277e289-0f5e-5b1d-bc83-1e697b36d63a', '3387e2db-d34d-5b43-aee8-841fb4b06b64', 'E', 'Central retinal vein occlusion', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e9e688e4-3e1f-5aa0-82c3-1e2da88aab23', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 45 year old man was hammering metal without eye protection and felt something hit his eye. His eye is red and painful and he has reduced vision. What is the SINGLE most appropriate imaging if an intraocular foreign body is suspected?', 'High-velocity injuries (hammering metal on metal) risk penetrating injury with an intraocular foreign body. CT is the imaging of choice. MRI is contraindicated if a metallic foreign body is suspected. A shield should protect the eye, and pressure on the globe must be avoided. Urgent ophthalmology referral is needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1cb0aa56-760f-5615-beff-c16d1888a6a7', 'e9e688e4-3e1f-5aa0-82c3-1e2da88aab23', 'A', 'Ultrasound with pressure on the globe', false, 0),
  ('81b33a0e-434e-5e62-8c7a-c13595d78a57', 'e9e688e4-3e1f-5aa0-82c3-1e2da88aab23', 'B', 'Plain X-ray is never useful', false, 1),
  ('fd2ccccf-1ab9-5df8-8834-1c5cb09efb6d', 'e9e688e4-3e1f-5aa0-82c3-1e2da88aab23', 'C', 'CT of the orbits', true, 2),
  ('fa54a828-f5e8-5a07-8f71-c26fe22bb12a', 'e9e688e4-3e1f-5aa0-82c3-1e2da88aab23', 'D', 'No imaging', false, 3),
  ('c79dd074-8343-58a3-a587-820897504bc0', 'e9e688e4-3e1f-5aa0-82c3-1e2da88aab23', 'E', 'MRI of the orbits', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('93aa3e64-1df4-597f-b192-54edf891e0af', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 30 year old man had a chemical splash (alkali) in his eye at work 5 minutes ago. His eye is painful. What is the SINGLE most appropriate immediate action?', 'Chemical injuries are an emergency. Alkalis cause more damage than acids because they penetrate deeper. Immediate copious irrigation (at least 1-2 L, using topical anaesthetic) continues until the pH is neutral (7-7.5). Particles under the eyelids should be removed. Urgent ophthalmology review is then needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bbf1b153-8c47-5486-9ae3-4799a4c31d63', '93aa3e64-1df4-597f-b192-54edf891e0af', 'A', 'Topical antibiotics only', false, 0),
  ('3d98c695-0cc4-5a4a-b5fe-a672d7abb1b5', '93aa3e64-1df4-597f-b192-54edf891e0af', 'B', 'Immediate copious irrigation with saline or water (check pH) before anything else', true, 1),
  ('63239f3e-0823-583b-a002-7321dd3e28db', '93aa3e64-1df4-597f-b192-54edf891e0af', 'C', 'Wait for ophthalmology review before irrigation', false, 2),
  ('2053a5b4-eb1b-5493-a343-7a204ee9ae47', '93aa3e64-1df4-597f-b192-54edf891e0af', 'D', 'Apply an eye patch', false, 3),
  ('27c883bb-42a7-5440-b319-5a33660c02f3', '93aa3e64-1df4-597f-b192-54edf891e0af', 'E', 'Neutralise with acid', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b0f4f660-a6bb-52fb-a560-197be6081b83', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 38 year old man has had a red eye with mild discomfort, watering and photophobia for 4 days. He had a cold sore last week. Fluorescein staining shows a branching dendritic ulcer on the cornea. What is the SINGLE most appropriate treatment?', 'A dendritic ulcer on fluorescein staining is herpes simplex keratitis. It needs same-day ophthalmology referral and topical antiviral treatment (aciclovir ointment or ganciclovir gel). Topical steroids can make it much worse, causing geographic ulceration and perforation. Recurrent episodes can cause corneal scarring.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('62ea887f-ac61-56b0-a0a8-3794775ed63c', 'b0f4f660-a6bb-52fb-a560-197be6081b83', 'A', 'Topical chloramphenicol only', false, 0),
  ('ba8f6b2f-052b-5ce3-ae4b-3645c4f5d4fd', 'b0f4f660-a6bb-52fb-a560-197be6081b83', 'B', 'Topical steroid drops', false, 1),
  ('815f6409-6727-5ee1-8a08-912108e70c40', 'b0f4f660-a6bb-52fb-a560-197be6081b83', 'C', 'Lubricant drops only', false, 2),
  ('daa8a3e1-8d2a-5bec-a95d-f5db78d91483', 'b0f4f660-a6bb-52fb-a560-197be6081b83', 'D', 'Topical aciclovir (or ganciclovir) and same-day ophthalmology referral', true, 3),
  ('c17b64ef-c1df-575a-912b-e72f8696db55', 'b0f4f660-a6bb-52fb-a560-197be6081b83', 'E', 'Oral antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0e7d5ecd-ff45-53e9-a051-e0b3c846831c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 4 year old child has had a red, swollen, tender eyelid for 2 days with fever. She has painful eye movements and reduced visual acuity, and her eye is pushed forward (proptosis). What is the SINGLE most likely diagnosis?', 'Orbital cellulitis (behind the orbital septum, often from sinusitis) causes proptosis, painful or restricted eye movements, reduced visual acuity and RAPD, and is an emergency. It needs admission, IV antibiotics, CT of the orbits and sinuses, and ENT and ophthalmology input, because of the risk of vision loss, cavernous sinus thrombosis and meningitis. Preseptal cellulitis has normal eye movements and vision.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('604e1eb2-0c24-5f39-a71c-a3039c1db485', '0e7d5ecd-ff45-53e9-a051-e0b3c846831c', 'A', 'Preseptal cellulitis', false, 0),
  ('23193d8e-948b-571f-82f9-e8e8f8108d46', '0e7d5ecd-ff45-53e9-a051-e0b3c846831c', 'B', 'Chalazion', false, 1),
  ('c57b35a8-7d7d-531c-903c-403bcc8a31b0', '0e7d5ecd-ff45-53e9-a051-e0b3c846831c', 'C', 'Stye (hordeolum)', false, 2),
  ('a090345b-6fe3-5212-b01d-1b08f7d0c048', '0e7d5ecd-ff45-53e9-a051-e0b3c846831c', 'D', 'Orbital (post-septal) cellulitis', true, 3),
  ('acae3325-321b-555f-bbde-5a149fb09163', '0e7d5ecd-ff45-53e9-a051-e0b3c846831c', 'E', 'Allergic conjunctivitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ec50c333-11fa-5dcc-b4f4-9576fac0e592', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 45 year old woman has had a painless, firm lump in her upper eyelid for 3 weeks, which has slowly enlarged. It is not tender or red. What is the SINGLE most likely diagnosis?', 'A chalazion is a painless granulomatous swelling of a blocked meibomian gland, which often resolves with warm compresses and massage. Persistent lesions may be incised and curetted. A stye (hordeolum) is an acute painful infection of an eyelash follicle or gland. Recurrent chalazia in older patients may need biopsy to exclude sebaceous gland carcinoma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('eddccd6d-307a-5531-900b-4547098483c1', 'ec50c333-11fa-5dcc-b4f4-9576fac0e592', 'A', 'Stye (hordeolum)', false, 0),
  ('3fc09890-0b66-5cb3-9e04-c639bbc4cf47', 'ec50c333-11fa-5dcc-b4f4-9576fac0e592', 'B', 'Chalazion (meibomian cyst)', true, 1),
  ('ef134841-b9d7-5159-90d8-dcbc36b88eed', 'ec50c333-11fa-5dcc-b4f4-9576fac0e592', 'C', 'Basal cell carcinoma', false, 2),
  ('b0913dbe-83d6-5c59-a9df-5405e03bcff1', 'ec50c333-11fa-5dcc-b4f4-9576fac0e592', 'D', 'Orbital cellulitis', false, 3),
  ('d99fc879-b6d2-554f-96ff-1b65411dd1e0', 'ec50c333-11fa-5dcc-b4f4-9576fac0e592', 'E', 'Dacryocystitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c1779f38-ce43-598d-b4df-7eef98490cb7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 70 year old woman has had dry, gritty, burning eyes for months, worse in the evening. Her eyelid margins are red and crusted with debris around the lashes. What is the SINGLE most appropriate first-line management?', 'Blepharitis is chronic inflammation of the eyelid margins, associated with seborrhoeic dermatitis and rosacea. Management is daily lid hygiene with warm compresses, massage and cleaning, plus artificial tears for associated dry eye. Topical antibiotics (chloramphenicol) or oral tetracyclines are used for persistent or posterior blepharitis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6b812b40-4e7b-5e69-b138-897e56b16db2', 'c1779f38-ce43-598d-b4df-7eef98490cb7', 'A', 'Urgent ophthalmology referral', false, 0),
  ('b9da2d6c-5e33-5965-92ba-7aab744c16dd', 'c1779f38-ce43-598d-b4df-7eef98490cb7', 'B', 'Topical steroid long-term', false, 1),
  ('6144f053-5ff5-59a5-a8f6-ff1939d471cc', 'c1779f38-ce43-598d-b4df-7eef98490cb7', 'C', 'Lid hygiene (warm compresses and lid cleaning) and artificial tears', true, 2),
  ('92939c4c-01fe-5bb2-b34e-60fc10f76cb4', 'c1779f38-ce43-598d-b4df-7eef98490cb7', 'D', 'Oral doxycycline first-line', false, 3),
  ('88efcc23-32e9-5b24-966b-75188c00d97f', 'c1779f38-ce43-598d-b4df-7eef98490cb7', 'E', 'Topical aciclovir', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fa22b0fb-40e6-57a2-ad68-fbb3e8b656af', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 55 year old man has had double vision for 2 days. On examination his right eye is turned ''down and out'' with ptosis and a dilated, unreactive pupil. He has a severe headache. What is the SINGLE most urgent concern?', 'A third nerve palsy with pupil involvement (dilated pupil) suggests compression, classically from a posterior communicating artery aneurysm, because the pupillary fibres run on the outside of the nerve. It needs urgent CT or MR angiography. A ''medical'' third nerve palsy (diabetes, hypertension) usually spares the pupil.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fad8d5d8-14cd-5b80-8adb-d998c3cb210e', 'fa22b0fb-40e6-57a2-ad68-fbb3e8b656af', 'A', 'Thyroid eye disease', false, 0),
  ('f487830d-2ea6-5414-a895-3ab8d39bf47e', 'fa22b0fb-40e6-57a2-ad68-fbb3e8b656af', 'B', 'Myasthenia gravis', false, 1),
  ('d704a9ab-9c48-5da3-865d-22a0bceae819', 'fa22b0fb-40e6-57a2-ad68-fbb3e8b656af', 'C', 'Sixth nerve palsy', false, 2),
  ('4af1ca22-f4b8-522d-983a-f6fef5244bf6', 'fa22b0fb-40e6-57a2-ad68-fbb3e8b656af', 'D', 'Posterior communicating artery aneurysm compressing the third nerve', true, 3),
  ('f592421b-b1f9-55e1-b5db-1708ab3341f1', 'fa22b0fb-40e6-57a2-ad68-fbb3e8b656af', 'E', 'Diabetic third nerve palsy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('17a1b720-34d9-5392-ab30-e1e1e2ebc396', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 25 year old woman has had pain behind her right eye on movement, blurred central vision and reduced red colour vision for 3 days. Fundoscopy is normal and there is a right RAPD. What is the SINGLE most likely diagnosis?', 'Optic neuritis causes subacute visual loss, pain on eye movement, reduced colour vision (red desaturation) and an RAPD. The disc is often normal (retrobulbar) or swollen. It is strongly associated with MS. An MRI brain helps assess the risk of MS. High-dose steroids may speed recovery but do not improve the final outcome. Most patients recover vision.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3cdf3c37-70d4-5cf2-9c9b-5961a13d0bd7', '17a1b720-34d9-5392-ab30-e1e1e2ebc396', 'A', 'Optic neuritis', true, 0),
  ('46eaf265-b75e-5317-9445-2145619bbf3c', '17a1b720-34d9-5392-ab30-e1e1e2ebc396', 'B', 'Migraine', false, 1),
  ('6174f3fa-6913-5f16-84ca-805fbb7235ba', '17a1b720-34d9-5392-ab30-e1e1e2ebc396', 'C', 'Central retinal vein occlusion', false, 2),
  ('74d473a8-8169-5d84-b593-a004176a51c4', '17a1b720-34d9-5392-ab30-e1e1e2ebc396', 'D', 'Retinal detachment', false, 3),
  ('3deabac0-1449-5d46-b25e-73363ac72232', '17a1b720-34d9-5392-ab30-e1e1e2ebc396', 'E', 'Acute glaucoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8e380585-1f87-5674-871f-43d6e78d7296', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 38 year old woman has red sore eyes with crusting in the morning for 9 days. She works in a laboratory and is having difficulty using her microscope. There is no history of trauma. Her conjunctivae are red. Pupils and visual acuity are normal. Which is the most appropriate topical treatment?', 'A red, sore eye with crusting and normal vision and pupils suggests bacterial conjunctivitis. It is usually self-limiting, but a topical antibacterial (chloramphenicol) is appropriate when symptoms persist or affect work, as here. Steroids should never be started without specialist advice.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0382c37e-44c5-5c10-a3a3-4ea33b9962cc', '8e380585-1f87-5674-871f-43d6e78d7296', 'A', 'Anaesthetic', false, 0),
  ('d1c20b50-2679-5228-8c06-c94d6ed86086', '8e380585-1f87-5674-871f-43d6e78d7296', 'B', 'Antibacterial', true, 1),
  ('59710613-411d-530e-addb-7fb4f5d7e94c', '8e380585-1f87-5674-871f-43d6e78d7296', 'C', 'Antiviral', false, 2),
  ('a02e77a5-f1b8-5486-a5ae-d1c249d79c77', '8e380585-1f87-5674-871f-43d6e78d7296', 'D', 'Mydriatic', false, 3),
  ('cb3357a7-3b07-53be-96e7-037c0998d5c6', '8e380585-1f87-5674-871f-43d6e78d7296', 'E', 'Steroid', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e8ec3bca-6414-5b26-860a-119ae529b7de', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'An 82 year old woman has a gradual deterioration of vision for 2 years. Her symptoms are more noticeable when she is driving at night. She smokes 10 cigarettes a day. She does not take any medication. Visual acuities are 6/36 in the right eye and 6/18 in the left; these do not improve with her prescription spectacles. The corneas and pupils appear normal. The fundus in each eye is partly obscured. Which is the most likely diagnosis?', 'Gradual painless loss of vision, worse with glare when driving at night, not corrected by glasses, with a partly obscured fundus view in an older smoker, suggests cataract. Treatment is phacoemulsification with lens implant when symptoms affect daily life. The DVLA visual acuity standard should be considered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e5127912-4ce5-5cbe-b6f9-e4480b40e0ea', 'e8ec3bca-6414-5b26-860a-119ae529b7de', 'A', 'Cataract', true, 0),
  ('0325c536-6ae7-5394-a806-9da96380b23d', 'e8ec3bca-6414-5b26-860a-119ae529b7de', 'B', 'Diabetic retinopathy', false, 1),
  ('f5b1a86f-e7da-512d-a37b-48d44c368787', 'e8ec3bca-6414-5b26-860a-119ae529b7de', 'C', 'Giant cell arteritis', false, 2),
  ('2010ed70-7546-5dee-86dd-e20244ab22b4', 'e8ec3bca-6414-5b26-860a-119ae529b7de', 'D', 'Glaucoma', false, 3),
  ('e1fe1487-3e2d-51e4-a652-21598826e780', 'e8ec3bca-6414-5b26-860a-119ae529b7de', 'E', 'Refractive error', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8687fa05-7305-50ee-9b6e-652a1c232974', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 44 year old woman has dry, itchy eyes for 6 months and is seen in the outpatient clinic. She also describes a dry mouth and has had intermittent arthralgia for 1 year. Investigations: Extractable nuclear antigen: positive Schirmer''s test: 7 mm wetting after 5 min (>15) Which is the most appropriate treatment for her dry eyes?', 'Dry eyes and dry mouth with arthralgia, positive ENA (anti-Ro/La) and a reduced Schirmer''s test suggest Sjögren''s syndrome. First-line treatment for dry eyes is artificial tears such as hypromellose. Patients also have an increased risk of lymphoma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7c96c834-8eb9-5286-b1e0-c3c0d7fc2802', '8687fa05-7305-50ee-9b6e-652a1c232974', 'A', 'Cyclopentolate', false, 0),
  ('6450eda4-398e-5193-9766-ab0fd86ba77e', '8687fa05-7305-50ee-9b6e-652a1c232974', 'B', 'Hypromellose', true, 1),
  ('77771ce0-85bc-52b4-a98d-1484d4a2d804', '8687fa05-7305-50ee-9b6e-652a1c232974', 'C', 'Prednisolone', false, 2),
  ('a62c6fa6-a0f8-5b04-914e-2b7d37afac85', '8687fa05-7305-50ee-9b6e-652a1c232974', 'D', 'Sodium cromoglicate', false, 3),
  ('00fef839-01de-58b3-9469-cc7fb39a6b01', '8687fa05-7305-50ee-9b6e-652a1c232974', 'E', 'Timolol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a1823ae8-fda1-5439-8523-29af9cc391ce', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'An 82 year old man with end-stage COPD is in the last days of life on a hospice ward. He is unconscious, and his family are distressed by noisy, rattly breathing caused by respiratory secretions. He has been repositioned and does not appear distressed. What is the SINGLE most appropriate medication?', 'Noisy respiratory secretions (''death rattle'') at the end of life are managed by repositioning and, if needed, an antimuscarinic such as SC hyoscine butylbromide (or glycopyrronium), which reduces secretion production. Families should be reassured that the patient is usually not distressed by it. Midazolam is for agitation or anxiety, haloperidol for nausea or delirium, and morphine for pain or breathlessness.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('315aba1f-fc11-5d85-8ff3-c64abb6d71b7', 'a1823ae8-fda1-5439-8523-29af9cc391ce', 'A', 'Subcutaneous haloperidol', false, 0),
  ('6131914c-b7b0-5034-9907-236bc0411ed3', 'a1823ae8-fda1-5439-8523-29af9cc391ce', 'B', 'Subcutaneous morphine', false, 1),
  ('b6567d56-41fa-509e-8efd-693b78e02f6c', 'a1823ae8-fda1-5439-8523-29af9cc391ce', 'C', 'Subcutaneous midazolam', false, 2),
  ('35fdc243-655b-5b99-a240-9286d347490b', 'a1823ae8-fda1-5439-8523-29af9cc391ce', 'D', 'Subcutaneous hyoscine butylbromide', true, 3),
  ('2a32a07e-ee1a-5f63-9836-9bf528d1bba5', 'a1823ae8-fda1-5439-8523-29af9cc391ce', 'E', 'IV furosemide', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('12a1709d-2a67-585b-80c9-d6177cd5d17d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 74 year old woman with metastatic ovarian cancer has malignant bowel obstruction and is not for surgery. She is nauseated with colicky abdominal pain. She is in the last weeks of life and her goal is comfort. Which antiemetic should be AVOIDED in this situation?', 'Metoclopramide is a prokinetic and is contraindicated in complete mechanical bowel obstruction because it increases colic and the risk of perforation. Suitable options include cyclizine and haloperidol, levomepromazine as a broad-spectrum option, and hyoscine butylbromide to reduce colic and secretions. Octreotide can reduce GI secretions and vomiting. Drugs are usually given subcutaneously by syringe driver.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e8ad82f7-da7c-5217-8214-7b953f89d235', '12a1709d-2a67-585b-80c9-d6177cd5d17d', 'A', 'Metoclopramide', true, 0),
  ('49b9e324-f43d-5fc2-a732-7d784779380f', '12a1709d-2a67-585b-80c9-d6177cd5d17d', 'B', 'Hyoscine butylbromide (for colic and secretions)', false, 1),
  ('841a205f-73e0-5027-a66f-7759a6deb258', '12a1709d-2a67-585b-80c9-d6177cd5d17d', 'C', 'Haloperidol', false, 2),
  ('49e5d0c7-26f8-5065-bc0f-d23331a24244', '12a1709d-2a67-585b-80c9-d6177cd5d17d', 'D', 'Cyclizine', false, 3),
  ('c4eee8a9-8bf0-5302-a100-871086aa5fc8', '12a1709d-2a67-585b-80c9-d6177cd5d17d', 'E', 'Levomepromazine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('805ed361-9c50-5a02-bd47-78081a9c5c82', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 66 year old man with lung cancer takes modified-release morphine 60 mg twice daily. He has episodes of breakthrough pain a few times a day. What is the SINGLE most appropriate dose of oral immediate-release morphine for breakthrough pain?', 'Breakthrough doses are usually one-tenth to one-sixth of the total 24-hour opioid dose. His total daily dose is 120 mg, so breakthrough is 12-20 mg of immediate-release morphine, and 20 mg (one-sixth) is the closest correct option. If he needs breakthrough doses regularly, the background dose should be increased. All patients on opioids should be prescribed a laxative and have an antiemetic available.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ea8d118c-bc0f-5309-b931-8fc9979dadd3', '805ed361-9c50-5a02-bd47-78081a9c5c82', 'A', '5 mg as required', false, 0),
  ('3b971e3e-73d0-5034-81a0-88f227562414', '805ed361-9c50-5a02-bd47-78081a9c5c82', 'B', '10 mg as required', false, 1),
  ('f1967d68-93ed-5000-828e-d633995730b0', '805ed361-9c50-5a02-bd47-78081a9c5c82', 'C', '20 mg as required', true, 2),
  ('47d86571-ea7c-5b8f-8a9d-9550accb61d0', '805ed361-9c50-5a02-bd47-78081a9c5c82', 'D', '60 mg as required', false, 3),
  ('d01891b9-d0d8-5d7e-89d1-b2df2c466783', '805ed361-9c50-5a02-bd47-78081a9c5c82', 'E', '120 mg as required', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('561f0d76-40ae-5737-9fe4-fc6c37797ef3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 70 year old man with metastatic prostate cancer has severe bone pain despite regular paracetamol and NSAIDs. According to the WHO analgesic ladder, what is the SINGLE most appropriate next step?', 'The WHO ladder moves from non-opioids to weak opioids (codeine) to strong opioids (morphine), with adjuvants. For moderate-severe cancer pain, NICE recommends starting oral morphine (immediate-release or MR, 20-30 mg/day in divided doses for most patients), with a laxative and an antiemetic available. Bone metastases may also respond to radiotherapy and bisphosphonates.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('57b43528-394e-5999-99a2-168b5e757b7b', '561f0d76-40ae-5737-9fe4-fc6c37797ef3', 'A', 'No change', false, 0),
  ('257aaa8d-0ca7-5916-9f26-a2799bf48a6c', '561f0d76-40ae-5737-9fe4-fc6c37797ef3', 'B', 'Oral prednisolone alone', false, 1),
  ('a4aaddb0-68b1-5383-89f1-ff13d50cb156', '561f0d76-40ae-5737-9fe4-fc6c37797ef3', 'C', 'Increase NSAID dose to maximum indefinitely', false, 2),
  ('61bf3c01-64d0-5ae9-a5d6-e731d8517e78', '561f0d76-40ae-5737-9fe4-fc6c37797ef3', 'D', 'Start a weak opioid and stop paracetamol', false, 3),
  ('473e6a4b-a82e-544e-afa1-4c6a43e4f7c7', '561f0d76-40ae-5737-9fe4-fc6c37797ef3', 'E', 'Start a strong opioid (e.g. oral morphine) with laxatives and an antiemetic as required', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c54e28b8-f9d2-5b00-b108-b6f1031a2ead', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 60 year old woman with metastatic breast cancer and eGFR of 18 mL/min/1.73m2 needs strong opioid analgesia. Which opioid is MOST appropriate in severe renal impairment?', 'Morphine and its active metabolites accumulate in renal failure, causing toxicity (drowsiness, myoclonus, confusion). In moderate renal impairment, oxycodone is used cautiously at a reduced dose. In severe renal impairment, fentanyl, alfentanil or buprenorphine (mainly hepatic clearance) are preferred. Codeine and tramadol also accumulate.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6e4cd51c-863d-548f-aeea-2ab24dab7a50', 'c54e28b8-f9d2-5b00-b108-b6f1031a2ead', 'A', 'Tramadol at maximum dose', false, 0),
  ('a7566cdb-38be-5e3d-91ac-e1c9c58bb49c', 'c54e28b8-f9d2-5b00-b108-b6f1031a2ead', 'B', 'Codeine', false, 1),
  ('f4cc6af5-bdd8-59dc-9d86-af9147fa1103', 'c54e28b8-f9d2-5b00-b108-b6f1031a2ead', 'C', 'Morphine at full dose', false, 2),
  ('4fc7db5d-5a32-55d8-b34e-19cb5ec4fb51', 'c54e28b8-f9d2-5b00-b108-b6f1031a2ead', 'D', 'Pethidine', false, 3),
  ('6193d2b5-742c-5f01-bc05-30939675e187', 'c54e28b8-f9d2-5b00-b108-b6f1031a2ead', 'E', 'Oxycodone at low dose with caution, or fentanyl/alfentanil (avoiding morphine)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('69b99ea3-c801-5862-a08c-f679c5f8eca8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 72 year old man on morphine for cancer pain has become drowsy, with pinpoint pupils, myoclonic jerks and hallucinations. His respiratory rate is 14 breaths/minute. His kidney function has worsened. What is the SINGLE most appropriate management?', 'Opioid toxicity (drowsiness, pinpoint pupils, myoclonus, hallucinations) is often precipitated by worsening renal function. If breathing is not compromised, management is reducing or withholding the opioid, or switching to an alternative. Naloxone is used for significant respiratory depression, in small titrated doses, to avoid precipitating severe pain and withdrawal in long-term opioid users.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bdc5220e-5cb4-54cb-a929-bb4db92bc971', '69b99ea3-c801-5862-a08c-f679c5f8eca8', 'A', 'Give a large naloxone bolus immediately', false, 0),
  ('29eeffeb-3744-5521-a86a-a84485eae711', '69b99ea3-c801-5862-a08c-f679c5f8eca8', 'B', 'Add haloperidol and continue', false, 1),
  ('aa9ae822-f197-5fba-9579-a7c6ee5b2298', '69b99ea3-c801-5862-a08c-f679c5f8eca8', 'C', 'Increase the morphine dose', false, 2),
  ('1ece568d-e88f-5aa7-b255-2dbf513cf790', '69b99ea3-c801-5862-a08c-f679c5f8eca8', 'D', 'Reduce the morphine dose or switch to an alternative opioid; give naloxone only if respiratory depression is severe', true, 3),
  ('51414170-70cf-57dc-ad78-48d4f505061c', '69b99ea3-c801-5862-a08c-f679c5f8eca8', 'E', 'Stop all analgesia permanently', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5f13887c-374c-5452-bd37-42c99d90f995', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 58 year old man with advanced lung cancer has severe nausea. He also has a hypercalcaemia of 2.9 mmol/L being treated. Which antiemetic is MOST appropriate for nausea due to chemical or metabolic causes?', 'Antiemetics are chosen by cause. Chemical or metabolic causes (opioids, hypercalcaemia, renal failure) are treated with haloperidol or levomepromazine. Gastric stasis is treated with metoclopramide (prokinetic). Raised intracranial pressure and vestibular causes respond to cyclizine (with dexamethasone for raised ICP). Chemotherapy-induced nausea responds to ondansetron and dexamethasone.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a5c7046f-5c01-5e3f-8dc7-f697fb698c2d', '5f13887c-374c-5452-bd37-42c99d90f995', 'A', 'Domperidone', false, 0),
  ('74a9bbb3-21f5-559f-87e5-8e66fba46ed8', '5f13887c-374c-5452-bd37-42c99d90f995', 'B', 'Hyoscine butylbromide', false, 1),
  ('941c6d5f-025c-5f56-9d33-ede61fe81c61', '5f13887c-374c-5452-bd37-42c99d90f995', 'C', 'Metoclopramide', false, 2),
  ('8d49d04c-d32b-5f4f-84e3-d2a51490058a', '5f13887c-374c-5452-bd37-42c99d90f995', 'D', 'Haloperidol', true, 3),
  ('b5b07312-9afb-5145-adb5-853465cadc4f', '5f13887c-374c-5452-bd37-42c99d90f995', 'E', 'Cyclizine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bf25f49c-d0e6-5120-a0f7-e6839cdeed49', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 75 year old woman is in the last days of life with advanced heart failure. She is agitated, restless and distressed. Reversible causes such as urinary retention and pain have been excluded. What is the SINGLE most appropriate medication?', 'Terminal agitation that persists after reversible causes (pain, urinary retention, constipation, hypoxia, medication) are excluded is usually treated with SC midazolam, given as needed or by syringe driver. Levomepromazine or haloperidol are used if there is delirium with hallucinations. Anticipatory medications are prescribed for pain, breathlessness, nausea, agitation and secretions.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('55eacb5c-90cb-5fbc-8374-ce31fb495646', 'bf25f49c-d0e6-5120-a0f7-e6839cdeed49', 'A', 'IM chlorpromazine', false, 0),
  ('0b94c9c5-b48b-5efb-8d15-9f2f5983889e', 'bf25f49c-d0e6-5120-a0f7-e6839cdeed49', 'B', 'Subcutaneous midazolam', true, 1),
  ('7b396684-7c27-5721-ba8f-a4c17ccebd1c', 'bf25f49c-d0e6-5120-a0f7-e6839cdeed49', 'C', 'IV diazepam', false, 2),
  ('abc72a7c-fa03-5229-b895-3d361f06ad6c', 'bf25f49c-d0e6-5120-a0f7-e6839cdeed49', 'D', 'Oral lorazepam', false, 3),
  ('71e32fe2-1236-514d-8cbf-07d512392fd7', 'bf25f49c-d0e6-5120-a0f7-e6839cdeed49', 'E', 'Oral haloperidol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cea6692a-aa34-5cfc-afc0-b9da385a4b54', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 70 year old man with end-stage COPD is breathless at rest, despite optimal inhaler treatment and oxygen. He is in the palliative phase. What is the SINGLE most appropriate pharmacological treatment for his breathlessness?', 'Low-dose opioids (such as oral morphine 2.5-5 mg as needed, or MR 10 mg/day) reduce the sensation of breathlessness in advanced disease. Non-drug measures (a fan, breathing techniques, positioning) also help. Benzodiazepines are used for associated anxiety. Oxygen is given only for hypoxia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f2ee2da9-2ad6-555e-83ba-1e7a4cf0e7c7', 'cea6692a-aa34-5cfc-afc0-b9da385a4b54', 'A', 'High-dose benzodiazepine', false, 0),
  ('8cadda45-9a53-538a-a43b-88f62730b3bd', 'cea6692a-aa34-5cfc-afc0-b9da385a4b54', 'B', 'Oral prednisolone long-term', false, 1),
  ('7c4130ae-906e-5c9e-a63c-d3f4e00ed384', 'cea6692a-aa34-5cfc-afc0-b9da385a4b54', 'C', 'Increase oxygen to 15 L/minute', false, 2),
  ('bd1c6a80-ccdb-5d76-96f4-5295a6e90706', 'cea6692a-aa34-5cfc-afc0-b9da385a4b54', 'D', 'IV furosemide', false, 3),
  ('5c1c0968-d5f3-584d-b4a4-e75c4c998795', 'cea6692a-aa34-5cfc-afc0-b9da385a4b54', 'E', 'Low-dose oral morphine (immediate-release)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('117a75fc-cc22-5c58-b58a-d7b2c252e890', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 66 year old woman with metastatic breast cancer has headache and vomiting, worse in the morning. MRI shows multiple brain metastases with surrounding oedema. What is the SINGLE most appropriate initial treatment?', 'Dexamethasone reduces vasogenic oedema around brain metastases, relieving headache and vomiting from raised intracranial pressure, and is given with gastroprotection. Steroids cause hyperglycaemia, insomnia and myopathy, so they are given in the morning and the dose is reduced to the lowest effective dose. Seizures are treated with antiepileptics. Definitive management may include radiotherapy or surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('958c5426-b8f1-596c-ad5b-5b26701d6799', '117a75fc-cc22-5c58-b58a-d7b2c252e890', 'A', 'Dexamethasone (with PPI cover)', true, 0),
  ('2d50a51b-5c43-5699-bb08-b9a91e7b1da0', '117a75fc-cc22-5c58-b58a-d7b2c252e890', 'B', 'Mannitol long-term', false, 1),
  ('09a9a7d9-59ba-5c5a-b0a9-659779cb2ef5', '117a75fc-cc22-5c58-b58a-d7b2c252e890', 'C', 'Furosemide', false, 2),
  ('307bf71f-3fc8-5945-b2fd-d9e8899476b3', '117a75fc-cc22-5c58-b58a-d7b2c252e890', 'D', 'Morphine only', false, 3),
  ('0746bc30-1876-545e-9ca5-7b39832e22fc', '117a75fc-cc22-5c58-b58a-d7b2c252e890', 'E', 'Lumbar puncture', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1bdd17ef-f1d9-5df4-8cad-87ef614adc47', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 52 year old man with lung cancer and bone metastases has had a 2-hour history of severe shortness of breath and a respiratory rate of 30. He is in his last days of life. He has a syringe driver with morphine 10 mg/24 h. What is the SINGLE most appropriate breakthrough dose of SC morphine?', 'The breakthrough dose is usually one-sixth (sometimes one-tenth) of the total 24-hour dose given by the same route. 10/6 is about 1.5-2 mg SC. If frequent breakthrough doses are needed, the background dose in the syringe driver should be increased by the total breakthrough amount used.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4b1189e5-fdcb-57cf-8302-976c30f0dcea', '1bdd17ef-f1d9-5df4-8cad-87ef614adc47', 'A', 'Diamorphine 30 mg SC', false, 0),
  ('07a6b984-1135-575e-a95f-4ef90cbcbede', '1bdd17ef-f1d9-5df4-8cad-87ef614adc47', 'B', 'Morphine 2 mg (one-sixth of the 24-hour dose) SC as needed', true, 1),
  ('05110995-49bf-5f67-acc9-bf29046c58f3', '1bdd17ef-f1d9-5df4-8cad-87ef614adc47', 'C', 'Morphine 20 mg SC', false, 2),
  ('67495c16-202b-5542-bda0-c35581e5334a', '1bdd17ef-f1d9-5df4-8cad-87ef614adc47', 'D', 'Morphine 10 mg SC', false, 3),
  ('0e710fe5-7a3e-53d0-a65d-2750fa6b48fb', '1bdd17ef-f1d9-5df4-8cad-87ef614adc47', 'E', 'Morphine 0.5 mg SC', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('91a484fa-8bfb-5752-bcaf-dd365918ee92', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 72 year old woman with advanced cancer has developed constipation from opioids despite maximal laxatives. She has no bowel obstruction. What is the SINGLE most appropriate next treatment?', 'For opioid-induced constipation that does not respond to laxatives, peripherally acting mu-opioid receptor antagonists (methylnaltrexone SC, naloxegol or naldemedine orally) block opioid effects in the gut without reversing analgesia. They are contraindicated in mechanical bowel obstruction.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6e0a165d-8fcc-5923-b987-d1c23c7c40d8', '91a484fa-8bfb-5752-bcaf-dd365918ee92', 'A', 'Surgical review', false, 0),
  ('81ff8e07-065f-523b-a163-52308d5a6505', '91a484fa-8bfb-5752-bcaf-dd365918ee92', 'B', 'Stop opioids completely', false, 1),
  ('a01e51a8-f5da-566f-8ffe-956c085c2484', '91a484fa-8bfb-5752-bcaf-dd365918ee92', 'C', 'Oral loperamide', false, 2),
  ('08251d35-b6cc-519f-9dab-a4399a6fae47', '91a484fa-8bfb-5752-bcaf-dd365918ee92', 'D', 'Bulk-forming laxative', false, 3),
  ('0710f4dc-45fc-525a-ba90-142a8833980b', '91a484fa-8bfb-5752-bcaf-dd365918ee92', 'E', 'Subcutaneous methylnaltrexone', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bae3c5de-7217-53c7-a88a-37c0263de9b2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'An 80 year old woman is dying with bowel obstruction from ovarian cancer. She is vomiting faeculent material. She is not for surgery or NG tube. What is the SINGLE most appropriate medication to reduce vomiting volume?', 'In inoperable malignant bowel obstruction, octreotide (a somatostatin analogue) and hyoscine butylbromide (an antimuscarinic) reduce GI secretions and vomiting. Haloperidol or cyclizine control nausea, and dexamethasone may help resolve the obstruction. Metoclopramide is contraindicated in complete obstruction. Small sips and mouth care maintain comfort.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d910f8c2-41c3-5119-a840-a9dba6144b3d', 'bae3c5de-7217-53c7-a88a-37c0263de9b2', 'A', 'Oral senna', false, 0),
  ('6d9dc4c9-aad3-52a6-a7b1-657deedccf47', 'bae3c5de-7217-53c7-a88a-37c0263de9b2', 'B', 'Metoclopramide', false, 1),
  ('a1bc03cc-c8b5-5f27-b615-5dcabb8b886b', 'bae3c5de-7217-53c7-a88a-37c0263de9b2', 'C', 'IV fluids at high volume', false, 2),
  ('09e88582-6a6f-5297-acfa-6e5d7cbedb4a', 'bae3c5de-7217-53c7-a88a-37c0263de9b2', 'D', 'Octreotide (subcutaneous), with hyoscine butylbromide', true, 3),
  ('4a97f13c-3aaa-5025-9514-2a4486af7a7a', 'bae3c5de-7217-53c7-a88a-37c0263de9b2', 'E', 'Loperamide', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e315aff8-5a69-5c7e-844f-7cd46eac5ed3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 68 year old man with lung cancer has had progressive back pain and now has leg weakness and a sensory level at T8 for 6 hours. What is the SINGLE most appropriate immediate drug treatment?', 'Metastatic spinal cord compression is an oncological emergency. NICE recommends dexamethasone 16 mg immediately (with a PPI), keeping the patient flat with spinal precautions if there is mechanical instability, an urgent MRI of the whole spine within 24 hours, and a decision on definitive treatment (surgery or radiotherapy) within 24 hours. Function at diagnosis is the best predictor of outcome.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('547e765c-d37e-5c4b-81d4-f61540391c52', 'e315aff8-5a69-5c7e-844f-7cd46eac5ed3', 'A', 'IV antibiotics', false, 0),
  ('638020d9-395b-55d0-afb4-19deb739785c', 'e315aff8-5a69-5c7e-844f-7cd46eac5ed3', 'B', 'IV furosemide', false, 1),
  ('743aeeda-a03d-5044-9bfd-7b87da531efd', 'e315aff8-5a69-5c7e-844f-7cd46eac5ed3', 'C', 'Oral morphine only', false, 2),
  ('19504fbb-8310-5ba1-b593-0b001c81fcb6', 'e315aff8-5a69-5c7e-844f-7cd46eac5ed3', 'D', 'Oral naproxen', false, 3),
  ('4606d8c3-e072-55c5-9550-e771da3a92b4', 'e315aff8-5a69-5c7e-844f-7cd46eac5ed3', 'E', 'Dexamethasone 16 mg daily (with PPI) and urgent whole-spine MRI', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('392e6e36-d05d-51a5-be03-619616000658', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 77 year old man is dying. His family ask why he is not being given IV fluids, since he is no longer drinking. What is the SINGLE most appropriate explanation?', 'NICE (NG31) recommends assessing hydration needs individually in the last days of life. Clinically assisted hydration may be considered if the patient is distressed by thirst, but it may not relieve symptoms and can worsen oedema, secretions or breathlessness. Regular mouth care is important. The decision should be discussed with the patient (if possible) and family, and reviewed daily.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f511d6c1-9f47-58ac-aaf8-34df20cbcf44', '392e6e36-d05d-51a5-be03-619616000658', 'A', 'IV fluids are illegal at the end of life', false, 0),
  ('4795bb7d-fce6-580d-913f-7a242bdc60d8', '392e6e36-d05d-51a5-be03-619616000658', 'B', 'Fluids are only stopped at family request', false, 1),
  ('1af2aa18-bd2d-52d7-999c-6444f0de133c', '392e6e36-d05d-51a5-be03-619616000658', 'C', 'IV fluids are always given until death', false, 2),
  ('ebfa6761-458f-5a54-a5fb-132daf1381d4', '392e6e36-d05d-51a5-be03-619616000658', 'D', 'Clinically assisted hydration should be discussed individually; it may not improve comfort and can cause fluid overload, while mouth care relieves thirst', true, 3),
  ('bcc34885-4f57-5876-b8b1-bc16a6f3080f', '392e6e36-d05d-51a5-be03-619616000658', 'E', 'Fluids are given to prolong life in every case', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d442e24a-992d-59f9-9b65-e7ee67b902ae', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 53 year old woman with primary adrenal insufficiency (Addison''s disease) is taken to theatre for an emergency laparotomy for small bowel obstruction. Her usual regimen is hydrocortisone 10 mg in the morning, 5 mg in the afternoon and fludrocortisone 100 micrograms daily. She cannot take anything by mouth. What is the SINGLE most appropriate perioperative steroid management?', 'Patients with adrenal insufficiency cannot mount a stress cortisol response, so major surgery can trigger an adrenal crisis. Guidance (AAGBI/Society for Endocrinology 2020) advises hydrocortisone 100 mg IV/IM at induction, then 200 mg over 24 hours by continuous infusion (or 50 mg every 6 hours) while she is nil by mouth. Return to double her usual oral dose once she is eating, then wean back over a few days. Fludrocortisone is not needed while hydrocortisone is above 50 mg/day, because high doses have enough mineralocorticoid effect.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('42c7533c-7b35-552b-b46e-8a4d845f3b4c', 'd442e24a-992d-59f9-9b65-e7ee67b902ae', 'A', 'IV dexamethasone 1 mg at induction only', false, 0),
  ('fb1f2156-b5f4-5556-ae49-a513fa77bdfb', 'd442e24a-992d-59f9-9b65-e7ee67b902ae', 'B', 'Omit all steroids on the day of surgery', false, 1),
  ('5d6cc9f3-6967-5d58-baba-30daa4723038', 'd442e24a-992d-59f9-9b65-e7ee67b902ae', 'C', 'IV hydrocortisone 100 mg at induction, then 200 mg over 24 hours', true, 2),
  ('b13874bc-7f19-5f72-8df1-2e04a3464986', 'd442e24a-992d-59f9-9b65-e7ee67b902ae', 'D', 'Continue her usual oral hydrocortisone dose only', false, 3),
  ('4f6d50dd-cdbb-55e6-a6bf-4c3261a346a4', 'd442e24a-992d-59f9-9b65-e7ee67b902ae', 'E', 'Double the dose of fludrocortisone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f0f0ad1e-c5f7-5b13-bbce-34c1a25f6a15', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 71 year old man is listed for an elective total hip replacement next week. He takes apixaban 5 mg twice daily for atrial fibrillation. His creatinine clearance is 78 mL/min. The surgery carries a high risk of bleeding and is planned under general anaesthesia. When should his last dose of apixaban be taken?', 'With normal kidney function, apixaban should be stopped at least 24 hours before low-bleeding-risk procedures and at least 48 hours before high-bleeding-risk procedures (longer if renal function is reduced or neuraxial anaesthesia is planned). DOACs have a short, predictable half-life, so heparin bridging is not needed and increases the risk of bleeding. Warfarin, by contrast, is usually stopped 5 days before surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('98b38083-1819-51a6-bb74-8c41ab4383af', 'f0f0ad1e-c5f7-5b13-bbce-34c1a25f6a15', 'A', '12 hours before surgery', false, 0),
  ('9809cc5c-3116-5079-ba86-6e643a2967d7', 'f0f0ad1e-c5f7-5b13-bbce-34c1a25f6a15', 'B', 'On the morning of surgery', false, 1),
  ('36c3894e-a418-5fac-bc65-0f591072f16e', 'f0f0ad1e-c5f7-5b13-bbce-34c1a25f6a15', 'C', 'Stop apixaban and bridge with treatment-dose low molecular weight heparin', false, 2),
  ('781e5922-d63d-509e-9e82-afa506914728', 'f0f0ad1e-c5f7-5b13-bbce-34c1a25f6a15', 'D', '7 days before surgery', false, 3),
  ('c98bf95c-5737-5f89-a83f-af8e67b11db8', 'f0f0ad1e-c5f7-5b13-bbce-34c1a25f6a15', 'E', '48 hours before surgery', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7df1cf71-dd34-5d74-a52f-653e9da524e4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 65 year old man with type 2 diabetes on metformin and gliclazide is first on the morning list for an elective inguinal hernia repair, so his fast will be short. His HbA1c is 56 mmol/mol and his eGFR is 70. What is the SINGLE most appropriate advice about his diabetes medication on the day of surgery?', 'Per the Centre for Perioperative Care (CPOC) diabetes guidance, sulfonylureas such as gliclazide are omitted on the day of surgery because of the risk of hypoglycaemia while fasting. Metformin can be continued when only one meal is missed and kidney function is normal. A variable-rate IV insulin infusion is for patients expected to miss more than one meal or with poor control. Capillary glucose should be monitored throughout.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6b47ff95-44d2-5bd2-a996-b06d6cbadd1f', '7df1cf71-dd34-5d74-a52f-653e9da524e4', 'A', 'Omit metformin and take gliclazide as normal', false, 0),
  ('d7139561-8616-5121-833b-715d7892571b', '7df1cf71-dd34-5d74-a52f-653e9da524e4', 'B', 'Start a variable-rate insulin infusion for all patients', false, 1),
  ('500646a7-9bde-5672-b279-d610f7320257', '7df1cf71-dd34-5d74-a52f-653e9da524e4', 'C', 'Stop both 1 week before surgery', false, 2),
  ('145cc30a-12f0-5799-ae68-416be6efd758', '7df1cf71-dd34-5d74-a52f-653e9da524e4', 'D', 'Take both as normal', false, 3),
  ('ecf053f9-74f5-5d5c-9ece-e7f5a89438af', '7df1cf71-dd34-5d74-a52f-653e9da524e4', 'E', 'Take metformin as normal and omit gliclazide on the morning of surgery', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7e7289f3-0b7e-58f2-81d8-d05c34d353e4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 72 year old woman is 2 days after an anterior resection. She is drowsy and her urine output has been 15 mL/hour for 4 hours. Her heart rate is 112 beats/minute, blood pressure 94/56 mmHg and capillary refill 4 seconds. Her catheter is not blocked. What is the SINGLE most appropriate immediate management?', 'Oliguria (below 0.5 mL/kg/hour) with tachycardia, hypotension and prolonged capillary refill after surgery suggests hypovolaemia. Bleeding and an anastomotic leak should also be considered. NICE recommends a 500 mL crystalloid bolus over less than 15 minutes with reassessment (ABCDE), repeated as needed up to 2 L before senior review. Furosemide would make hypovolaemia worse. Glucose 5% is not a resuscitation fluid.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('61391fb9-7322-5208-a88b-2129df58bdbc', '7e7289f3-0b7e-58f2-81d8-d05c34d353e4', 'A', 'IV 5% glucose 1 L bolus', false, 0),
  ('a6402f0b-c2d2-54ba-83e3-3baa1942d2b1', '7e7289f3-0b7e-58f2-81d8-d05c34d353e4', 'B', 'IV fluid bolus of 500 mL crystalloid over less than 15 minutes, then reassess', true, 1),
  ('6542dec0-3293-514e-9639-7bc22e499e43', '7e7289f3-0b7e-58f2-81d8-d05c34d353e4', 'C', 'Start maintenance fluids at 1 L over 12 hours only', false, 2),
  ('8858355b-34db-5149-8e52-50440a7c3b8c', '7e7289f3-0b7e-58f2-81d8-d05c34d353e4', 'D', 'Wait for the morning bloods', false, 3),
  ('417e47d6-0c0d-5ea0-b206-74368052339a', '7e7289f3-0b7e-58f2-81d8-d05c34d353e4', 'E', 'IV furosemide', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f2b856f3-5f77-548b-82a9-3326ecd6fa68', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 72 year old woman is having a hip replacement. Which risk assessment tool is MOST commonly used to estimate perioperative risk based on her overall physical status?', 'ASA grades: I healthy, II mild systemic disease, III severe systemic disease, IV severe systemic disease that is a constant threat to life, V moribund, VI brain-dead organ donor. Higher grades predict perioperative morbidity and mortality. Other tools include the Revised Cardiac Risk Index, NSQIP and the Clinical Frailty Scale.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c0d1f0a1-a4ed-59ac-ab51-7d7c62af8449', 'f2b856f3-5f77-548b-82a9-3326ecd6fa68', 'A', 'Glasgow-Blatchford score', false, 0),
  ('35d65b84-2812-5f0a-86fe-5078d550f572', 'f2b856f3-5f77-548b-82a9-3326ecd6fa68', 'B', 'Wells score', false, 1),
  ('8e1d3a11-4d4e-5d1d-8c0e-bbd687ef0643', 'f2b856f3-5f77-548b-82a9-3326ecd6fa68', 'C', 'CHA2DS2-VASc', false, 2),
  ('dbf2e97a-133a-542a-b7cc-60daf22f3069', 'f2b856f3-5f77-548b-82a9-3326ecd6fa68', 'D', 'Child-Pugh score', false, 3),
  ('70105b3e-63d8-52c2-ac41-65e8671f5a13', 'f2b856f3-5f77-548b-82a9-3326ecd6fa68', 'E', 'ASA (American Society of Anesthesiologists) physical status classification', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5d3228d8-1468-5c8b-aa56-badf12b1135a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 45 year old woman is due for elective surgery under general anaesthesia tomorrow. What are the standard fasting instructions before her operation?', 'Standard fasting guidance is no solid food (including milk) for 6 hours and clear fluids until 2 hours before anaesthesia (newer guidance allows sips of clear fluids up to 1 hour). Breast milk is allowed until 4 hours before in infants. Prolonged fasting causes dehydration, hypoglycaemia and discomfort. Patients at high aspiration risk may need rapid sequence induction.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8b96fada-24a9-544d-8cff-cc784cf2eee5', '5d3228d8-1468-5c8b-aa56-badf12b1135a', 'A', 'No fasting needed', false, 0),
  ('a3d28ddc-480f-591e-874f-bfe796fef05b', '5d3228d8-1468-5c8b-aa56-badf12b1135a', 'B', 'No clear fluids for 12 hours', false, 1),
  ('5aac41a4-c9dc-5e06-9a86-aad98d558ad1', '5d3228d8-1468-5c8b-aa56-badf12b1135a', 'C', 'No food for 2 hours', false, 2),
  ('c0c5528b-8325-5c0c-9db0-414c12d69b21', '5d3228d8-1468-5c8b-aa56-badf12b1135a', 'D', 'Nil by mouth from midnight for both food and water', false, 3),
  ('6dc140b7-a438-59df-b4cd-0644144fbd7c', '5d3228d8-1468-5c8b-aa56-badf12b1135a', 'E', 'No food for 6 hours and clear fluids allowed until 2 hours before anaesthesia', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3ffa84a2-8b1e-5d35-a4ef-3008ea34d2f8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 60 year old man is undergoing elective major abdominal surgery. He has no history of VTE or bleeding risk. Which VTE prophylaxis is MOST appropriate?', 'NICE NG89 recommends VTE risk assessment on admission. Major abdominal surgery needs pharmacological prophylaxis with LMWH (or fondaparinux) for at least 7 days, extended to 28 days after major abdominal or pelvic cancer surgery, plus mechanical prophylaxis (anti-embolism stockings or intermittent pneumatic compression) unless contraindicated. Early mobilisation helps.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cff8a92d-9b3f-5a22-bf56-0aa372abfd92', '3ffa84a2-8b1e-5d35-a4ef-3008ea34d2f8', 'A', 'Aspirin only', false, 0),
  ('5579a0c6-cb86-5644-962a-3cbfa3c38d1c', '3ffa84a2-8b1e-5d35-a4ef-3008ea34d2f8', 'B', 'No prophylaxis', false, 1),
  ('0d2d573d-b846-58b2-9922-0637e41399c0', '3ffa84a2-8b1e-5d35-a4ef-3008ea34d2f8', 'C', 'LMWH (e.g. enoxaparin) for at least 7 days (extended to 28 days after major cancer surgery), with mechanical prophylaxis', true, 2),
  ('6fa74afe-219c-5eae-95b8-c697ca249a79', '3ffa84a2-8b1e-5d35-a4ef-3008ea34d2f8', 'D', 'IVC filter', false, 3),
  ('ffcbf305-4a32-54b0-96b4-12fb6aead015', '3ffa84a2-8b1e-5d35-a4ef-3008ea34d2f8', 'E', 'Warfarin for 1 year', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('02bf8a94-e79f-5f27-8c0f-c95239230e9a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 25 year old man is having surgery. After induction with suxamethonium and volatile anaesthetic, he develops a rapidly rising temperature (40.5°C), muscle rigidity, tachycardia and a rising end-tidal CO2. What is the SINGLE most appropriate treatment?', 'Malignant hyperthermia is an autosomal dominant pharmacogenetic disorder (RYR1 mutation) triggered by volatile anaesthetics and suxamethonium. It causes hypermetabolism: hyperthermia, rigidity, hypercarbia, tachycardia, hyperkalaemia and rhabdomyolysis. Treatment is stopping triggers, giving IV dantrolene, cooling and supportive care. Patients and family members need referral for testing.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('876e58b9-194d-5849-882c-9dc65df19e1c', '02bf8a94-e79f-5f27-8c0f-c95239230e9a', 'A', 'IV haloperidol', false, 0),
  ('e53dbb5e-69ac-5259-bcae-a69dc809473f', '02bf8a94-e79f-5f27-8c0f-c95239230e9a', 'B', 'IV dantrolene, stop volatile agents and active cooling', true, 1),
  ('f10b4df8-7a5d-5e89-91fc-7dbc2cd5e241', '02bf8a94-e79f-5f27-8c0f-c95239230e9a', 'C', 'Increase the volatile anaesthetic', false, 2),
  ('2fc3605a-3c82-5de6-bf0b-0d6eddabbee1', '02bf8a94-e79f-5f27-8c0f-c95239230e9a', 'D', 'IV paracetamol', false, 3),
  ('8673a908-5de7-5609-880b-92508150a9e7', '02bf8a94-e79f-5f27-8c0f-c95239230e9a', 'E', 'IV antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7e3d9265-76ac-5f61-8b0b-323f0c37a05a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 34 year old woman had a laparoscopic cholecystectomy under general anaesthesia using suxamethonium. She remains paralysed and unable to breathe on her own for 2 hours after surgery, although she is awake. What is the SINGLE most likely cause?', 'Suxamethonium is broken down by plasma cholinesterase. Inherited deficiency causes prolonged neuromuscular blockade (suxamethonium apnoea), so the patient stays paralysed but awake. Management is continued sedation and ventilation until it wears off, then testing and an alert card for the patient and family. Suxamethonium also causes hyperkalaemia and fasciculations.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f0f60c18-86a5-5766-bc8c-9b22be727dae', '7e3d9265-76ac-5f61-8b0b-323f0c37a05a', 'A', 'Malignant hyperthermia', false, 0),
  ('12580abb-18e0-5db4-8ff6-83fe7ce26973', '7e3d9265-76ac-5f61-8b0b-323f0c37a05a', 'B', 'Hypoglycaemia', false, 1),
  ('a3c7248c-bfa0-5600-9089-fd9dd13730a2', '7e3d9265-76ac-5f61-8b0b-323f0c37a05a', 'C', 'Stroke', false, 2),
  ('1fd767b3-29f2-5a14-a06e-ba7693a77fc7', '7e3d9265-76ac-5f61-8b0b-323f0c37a05a', 'D', 'Pseudocholinesterase (butyrylcholinesterase) deficiency', true, 3),
  ('ea1f7d6e-4856-5244-b384-58a6049a3057', '7e3d9265-76ac-5f61-8b0b-323f0c37a05a', 'E', 'Opioid overdose', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('38a4c37e-e08d-528f-a76e-86e222ba7bea', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 70 year old man is 1 day after a total knee replacement. His pain is controlled. He has nausea and vomiting after opioids. Which antiemetic would be MOST appropriate for postoperative nausea and vomiting?', 'PONV is common, with risk factors including female sex, non-smoking, previous PONV or motion sickness and postoperative opioids (Apfel score). Ondansetron (a 5-HT3 antagonist) is commonly used, but it prolongs the QT and causes constipation. Dexamethasone and cyclizine are alternatives. Dopamine antagonists should be avoided in Parkinson''s disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2b625363-e752-5c5d-a99e-332a91699567', '38a4c37e-e08d-528f-a76e-86e222ba7bea', 'A', 'Haloperidol at high dose', false, 0),
  ('b81bfeff-530e-5336-84db-a88ef79e49d5', '38a4c37e-e08d-528f-a76e-86e222ba7bea', 'B', 'No treatment', false, 1),
  ('9045ac04-0309-5982-a158-1b5d112dc656', '38a4c37e-e08d-528f-a76e-86e222ba7bea', 'C', 'Prochlorperazine in a frail older person with falls', false, 2),
  ('1cc264c8-63cc-5e8e-9576-a46d1658ae76', '38a4c37e-e08d-528f-a76e-86e222ba7bea', 'D', 'Ondansetron', true, 3),
  ('a171df91-42c6-513f-99e1-526c7210b9fe', '38a4c37e-e08d-528f-a76e-86e222ba7bea', 'E', 'Metoclopramide in a patient with Parkinson''s disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('17ac0516-831a-5f79-a82b-74388fbc32e6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 62 year old man is having a hernia repair under spinal anaesthesia. After the injection his BP falls to 78/40 mmHg and his heart rate is 48 beats/minute. What is the SINGLE most likely cause?', 'Spinal anaesthesia blocks sympathetic fibres, causing vasodilation and hypotension, and bradycardia if T1-T4 cardioaccelerator fibres are blocked (a high block). Treatment is IV fluids, vasopressors (phenylephrine, metaraminol, ephedrine) and atropine for bradycardia. Other complications include post-dural puncture headache, urinary retention and, rarely, spinal haematoma or infection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cbefbea3-38d4-5a6b-9de6-9d51648ce1d5', '17ac0516-831a-5f79-a82b-74388fbc32e6', 'A', 'Sympathetic blockade from the spinal anaesthetic', true, 0),
  ('9faa0817-1a32-5285-bb0a-65e00a0f7c98', '17ac0516-831a-5f79-a82b-74388fbc32e6', 'B', 'Haemorrhage', false, 1),
  ('b64c3f1c-ac5d-5ae3-b623-b6a7164d5cc5', '17ac0516-831a-5f79-a82b-74388fbc32e6', 'C', 'Myocardial infarction', false, 2),
  ('05171a8a-75cc-510e-b47d-61d92d8f52a3', '17ac0516-831a-5f79-a82b-74388fbc32e6', 'D', 'Pulmonary embolism', false, 3),
  ('c006ff3f-de8e-59e1-b008-38a107c6e253', '17ac0516-831a-5f79-a82b-74388fbc32e6', 'E', 'Anaphylaxis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7f6db7cb-3bcb-507e-ba0c-cb1c34aa9811', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 30 year old woman had a spinal anaesthetic for a caesarean section 2 days ago. She now has a severe headache that is much worse when sitting or standing and relieved by lying flat. Neurological examination is normal. What is the SINGLE most likely diagnosis?', 'Post-dural puncture headache is a postural headache (worse upright, better lying flat) after spinal or epidural anaesthesia, from CSF leak. Conservative treatment is analgesia, fluids and caffeine. An epidural blood patch is effective for persistent or severe cases. Red flags (fever, focal neurology, persistent non-postural headache) need investigation for other causes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0b577d45-2ad7-5d6b-849b-77e241f35a7a', '7f6db7cb-3bcb-507e-ba0c-cb1c34aa9811', 'A', 'Subarachnoid haemorrhage', false, 0),
  ('1c570a1f-a86b-5c54-aaa1-31f3c3c48f60', '7f6db7cb-3bcb-507e-ba0c-cb1c34aa9811', 'B', 'Post-dural puncture headache', true, 1),
  ('6c3ae9ea-bdbc-5d71-a815-8356951f7f0d', '7f6db7cb-3bcb-507e-ba0c-cb1c34aa9811', 'C', 'Migraine', false, 2),
  ('51f4818b-b94e-589b-b8fa-ef628d7eef3b', '7f6db7cb-3bcb-507e-ba0c-cb1c34aa9811', 'D', 'Cerebral venous sinus thrombosis', false, 3),
  ('00e11b61-d63c-5e82-b890-77e060986b2c', '7f6db7cb-3bcb-507e-ba0c-cb1c34aa9811', 'E', 'Meningitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('24cb1959-d45b-5873-987c-6f39bcea4a17', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 55 year old woman takes warfarin for a mechanical mitral valve and needs elective surgery with high bleeding risk. What is the SINGLE most appropriate perioperative anticoagulation plan?', 'Patients at high thrombotic risk (mechanical mitral valve, recent VTE within 3 months, AF with recent stroke) need bridging. Warfarin is stopped 5 days before, with therapeutic LMWH starting 2 days later and the last dose 24 hours before surgery, then restarted after surgery when haemostasis allows. The INR is checked the day before. DOACs are contraindicated with mechanical valves.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('06eedf23-46dc-51da-82d6-56ddb13f4570', '24cb1959-d45b-5873-987c-6f39bcea4a17', 'A', 'Stop all anticoagulation for 2 weeks', false, 0),
  ('f3d655e3-8c58-5378-9c9d-2acb2c6ff80a', '24cb1959-d45b-5873-987c-6f39bcea4a17', 'B', 'Switch to a DOAC', false, 1),
  ('7fb8739e-e0e0-5191-9662-6448d6e626e1', '24cb1959-d45b-5873-987c-6f39bcea4a17', 'C', 'Stop warfarin the day before', false, 2),
  ('5030f0fb-d51a-5648-8639-aceb0cefe425', '24cb1959-d45b-5873-987c-6f39bcea4a17', 'D', 'Continue warfarin without interruption', false, 3),
  ('ce3e2f4e-db7d-5427-9da2-0c59f9b9ffe7', '24cb1959-d45b-5873-987c-6f39bcea4a17', 'E', 'Stop warfarin 5 days before and bridge with therapeutic LMWH, then restart after surgery', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ce3232e4-c379-5500-90cb-e7e0a2b2ecf2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 70 year old man is having emergency surgery. He takes rivaroxaban and his last dose was 6 hours ago. Surgery cannot wait. What is the SINGLE most appropriate agent to reverse the anticoagulation?', 'Andexanet alfa reverses factor Xa inhibitors (apixaban, rivaroxaban), with prothrombin complex concentrate as an alternative per local policy. Idarucizumab reverses dabigatran. Warfarin is reversed with IV vitamin K plus PCC. Protamine reverses heparin (partially for LMWH). Haematology advice should be sought.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('43fd3be3-ae0e-552a-bd31-8bc25325b6dd', 'ce3232e4-c379-5500-90cb-e7e0a2b2ecf2', 'A', 'Protamine sulfate', false, 0),
  ('ac244f6b-9bf9-5847-a8b3-d5fd717b5078', 'ce3232e4-c379-5500-90cb-e7e0a2b2ecf2', 'B', 'Fresh frozen plasma alone', false, 1),
  ('e2e3c7a6-b440-52ea-bea8-1087a4cb77d8', 'ce3232e4-c379-5500-90cb-e7e0a2b2ecf2', 'C', 'Vitamin K', false, 2),
  ('c52d8413-a67f-5110-a38a-2bb03807520c', 'ce3232e4-c379-5500-90cb-e7e0a2b2ecf2', 'D', 'Idarucizumab', false, 3),
  ('3a205341-6625-5bc3-a6cf-4a835d253dc0', 'ce3232e4-c379-5500-90cb-e7e0a2b2ecf2', 'E', 'Andexanet alfa (or prothrombin complex concentrate if unavailable)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ff62c8e4-aba9-58e7-ad60-1aeeaafcdb6d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 68 year old woman is 3 days after a bowel resection. She has been receiving maintenance IV fluids only (0.18% saline with 4% glucose). She is now confused and her sodium is 124 mmol/L. What is the SINGLE most likely cause?', 'The stress response to surgery raises ADH, reducing free water excretion. Giving hypotonic fluids (such as 0.18% saline/4% glucose) can cause dangerous hyponatraemia. NICE CG174 maintenance needs are 25-30 mL/kg/day of water, about 1 mmol/kg/day each of sodium, potassium and chloride, and 50-100 g/day of glucose. Electrolytes should be checked daily.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b9c45331-8006-5702-9716-1ea5dfb3aedd', 'ff62c8e4-aba9-58e7-ad60-1aeeaafcdb6d', 'A', 'Hypothyroidism', false, 0),
  ('e882914f-6bf3-5221-acc9-fa7488553984', 'ff62c8e4-aba9-58e7-ad60-1aeeaafcdb6d', 'B', 'Hypotonic IV fluid administration with postoperative ADH release', true, 1),
  ('614a5d93-9fc2-5f0c-9951-3b8cdbed6f92', 'ff62c8e4-aba9-58e7-ad60-1aeeaafcdb6d', 'C', 'Diabetes insipidus', false, 2),
  ('b6f7cb34-89be-534d-a0f3-f93847f5b8d0', 'ff62c8e4-aba9-58e7-ad60-1aeeaafcdb6d', 'D', 'SIADH from lung cancer', false, 3),
  ('5a01c372-ef0e-506d-9fe9-6af8f351550c', 'ff62c8e4-aba9-58e7-ad60-1aeeaafcdb6d', 'E', 'Addison''s disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('44f7549f-08e4-54c8-b4f4-5332ba20fa6a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 60 year old man had a laparotomy 2 days ago. He has a fever of 38°C, reduced breath sounds and dullness at both lung bases, with mild breathlessness. What is the SINGLE most likely cause?', 'Atelectasis (alveolar collapse) is the commonest cause of low-grade fever and hypoxia in the first 48 hours after surgery, especially upper abdominal surgery, from shallow breathing and pain. Management is chest physiotherapy, deep breathing exercises, incentive spirometry, good analgesia and early mobilisation. It can progress to pneumonia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1d8ed881-4500-5671-8727-9427ad463d54', '44f7549f-08e4-54c8-b4f4-5332ba20fa6a', 'A', 'Pulmonary embolism', false, 0),
  ('4e48f985-2e51-5dc7-bdf7-331fcb3ce3c8', '44f7549f-08e4-54c8-b4f4-5332ba20fa6a', 'B', 'Anastomotic leak', false, 1),
  ('eaefaa9d-b6e9-59d0-9ad1-1b8024a1f917', '44f7549f-08e4-54c8-b4f4-5332ba20fa6a', 'C', 'Wound infection', false, 2),
  ('2a8456e0-d7f7-541a-98f4-9a37121a7daa', '44f7549f-08e4-54c8-b4f4-5332ba20fa6a', 'D', 'Urinary tract infection', false, 3),
  ('3f6f9846-3040-5bbe-b488-88e248ffe864', '44f7549f-08e4-54c8-b4f4-5332ba20fa6a', 'E', 'Atelectasis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('17ea9629-d036-51c9-89ce-25587bb6d2b1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 55 year old woman has melaena for 6 weeks and is referred by her GP to gastroenterology. She has dyspepsia for 4 months.. She has type 2 diabetes and takes gliclazide. A diagnostic gastroscopy is recommended. Which is the most appropriate management of her diabetes prior to endoscopy?', 'For a short procedure such as gastroscopy, where only one meal is missed, sulfonylureas such as gliclazide are omitted on the morning of the procedure to avoid hypoglycaemia (CPOC guidance). Glucose is monitored and the usual medication restarted when eating. A variable-rate insulin infusion is for longer fasts or poor control.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('719438c2-4661-5aa9-a15c-897b635fad6b', '17ea9629-d036-51c9-89ce-25587bb6d2b1', 'A', 'Change gliclazide to metformin', false, 0),
  ('aa8a1616-16b5-5789-98e2-c241dbe938d3', '17ea9629-d036-51c9-89ce-25587bb6d2b1', 'B', 'Change gliclazide to subcutaneous insulin', false, 1),
  ('ea5955cf-09d7-5b13-9347-0e6aaa1bfd79', '17ea9629-d036-51c9-89ce-25587bb6d2b1', 'C', 'Omit gliclazide for 24 hours prior to procedure', false, 2),
  ('0e4302b0-7b1c-5971-ad2a-dbdf33330935', '17ea9629-d036-51c9-89ce-25587bb6d2b1', 'D', 'Omit gliclazide on morning of procedure', true, 3),
  ('0bbf170b-d9e3-5bc8-b193-76e97b79ce8a', '17ea9629-d036-51c9-89ce-25587bb6d2b1', 'E', 'Start glucose-potassium-insulin infusion on day of procedure', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7cb84310-378b-50d2-99a6-87e78f2e3849', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 44 year old man has severe pain following surgical fixation of a comminuted ankle fracture and fasciotomies for compartment syndrome. He has had several doses of oral morphine sulphate and intravenous paracetamol on the trauma ward but remains in severe pain. Investigations: Sodium 149 mmol/L (135–146) Potassium 4.6 mmol/L (3.5–5.3) Urea 12.9 mmol/L (2.5–7.8) Creatinine 169 micromol/L (60–120) Creatine kinase 876 U/L (25–200) Which is the most appropriate additional analgesic to prescribe?', 'Severe postoperative pain not controlled by oral morphine and IV paracetamol needs escalation. Patient-controlled IV morphine (PCA) gives effective, titratable analgesia. NSAIDs such as diclofenac are avoided in AKI or dehydration (raised sodium and urea). Codeine is weaker. A fentanyl patch is not suitable for acute, uncontrolled pain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('82f82919-7e1d-5e64-b547-c83e781f7b00', '7cb84310-378b-50d2-99a6-87e78f2e3849', 'A', 'Intramuscular diclofenac', false, 0),
  ('f71b12fc-5ee2-50e8-b4d9-d8cb962aa687', '7cb84310-378b-50d2-99a6-87e78f2e3849', 'B', 'Oral codeine phosphate', false, 1),
  ('994d2b5a-ad7c-5ab5-9384-ddb78b4d837d', '7cb84310-378b-50d2-99a6-87e78f2e3849', 'C', 'Oral oxycodone', false, 2),
  ('a453e89e-d954-52c3-8ffa-14dd99bca7a4', '7cb84310-378b-50d2-99a6-87e78f2e3849', 'D', 'Patient-controlled intravenous morphine', true, 3),
  ('b408fce5-66cc-50f9-b0df-985424913d47', '7cb84310-378b-50d2-99a6-87e78f2e3849', 'E', 'Topical fentanyl patch', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('568baa98-ccd1-50bf-b444-ec8b41c54557', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 74 year old woman is admitted with 3 days of diarrhoea and vomiting. Her medications are ramipril, metformin, furosemide and atorvastatin. Her creatinine is 212 micromol/L (baseline 98 micromol/L), potassium 5.4 mmol/L, blood pressure 98/60 mmHg and urine output has fallen. What is the SINGLE most appropriate initial management?', 'This is a pre-renal AKI (creatinine more than double baseline, stage 2) caused by volume depletion. Management is fluid resuscitation and stopping medicines that worsen kidney perfusion or are dangerous in AKI: ACE inhibitors and diuretics (''sick day rules''), and metformin because of the risk of lactic acidosis. Ultrasound is needed within 24 hours if obstruction is suspected or the cause is unclear. Dialysis is for refractory hyperkalaemia, acidosis, fluid overload or uraemic complications.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('eed4a113-ff70-5a8f-8e46-9578ae5e3df2', '568baa98-ccd1-50bf-b444-ec8b41c54557', 'A', 'IV fluids and withhold ramipril, metformin and furosemide', true, 0),
  ('c699039f-0ebf-5387-a431-615a3e06b499', '568baa98-ccd1-50bf-b444-ec8b41c54557', 'B', 'Continue all medications and recheck bloods in a week', false, 1),
  ('ca664e54-cf21-554e-8886-b57f2f6a1a10', '568baa98-ccd1-50bf-b444-ec8b41c54557', 'C', 'Urgent renal ultrasound before any treatment', false, 2),
  ('3580035c-58fa-5fa4-8c7b-bb0512d8cc1b', '568baa98-ccd1-50bf-b444-ec8b41c54557', 'D', 'Start haemodialysis', false, 3),
  ('5ce5c137-4d5b-5e9f-8513-afd129d4d224', '568baa98-ccd1-50bf-b444-ec8b41c54557', 'E', 'Increase the furosemide dose', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('51872eef-8600-5f7a-b60a-e375b5436a03', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 15 year old boy is brought to the Emergency Department with a 2-hour history of sudden severe left testicular pain and vomiting. On examination the left testis is high-riding, lying horizontally and extremely tender, and the cremasteric reflex is absent on the left. What is the SINGLE most appropriate management?', 'Sudden testicular pain in an adolescent with a high, horizontal testis and absent cremasteric reflex is testicular torsion until proven otherwise. Do not delay surgery for imaging. Urgent exploration with detorsion and bilateral orchidopexy is needed, ideally within 6 hours of onset, to save the testis. Manual detorsion may be tried as a temporary measure, but surgery is still required.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5dcce211-200b-5d26-922d-d877396b5637', '51872eef-8600-5f7a-b60a-e375b5436a03', 'A', 'Scrotal Doppler ultrasound and review in the morning', false, 0),
  ('c4b12925-5d6c-5bce-b010-53fff635d677', '51872eef-8600-5f7a-b60a-e375b5436a03', 'B', 'Analgesia and outpatient urology review', false, 1),
  ('40f699fa-c891-5061-a9f6-1599acccf030', '51872eef-8600-5f7a-b60a-e375b5436a03', 'C', 'Manual detorsion and discharge', false, 2),
  ('028b3100-1b18-5a5e-a7d1-8b30450480f4', '51872eef-8600-5f7a-b60a-e375b5436a03', 'D', 'Urgent surgical exploration of the scrotum', true, 3),
  ('e8aed523-c2f7-5493-9b8f-b0c712e87c5d', '51872eef-8600-5f7a-b60a-e375b5436a03', 'E', 'Oral antibiotics for epididymo-orchitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e7ffb89d-c73e-52e0-b9ea-28fa844ebac5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 41 year old man presents with sudden severe colicky pain from his left loin to his groin. He is writhing and cannot get comfortable. Urine dipstick shows blood. He is afebrile and his kidney function is normal. Analgesia has been given. What is the SINGLE most appropriate imaging?', 'This is renal colic. NICE recommends a non-contrast CT KUB within 24 hours in adults, which identifies over 99% of stones and their size and position. Ultrasound is first-line in pregnancy and children. First-line pain relief is an NSAID (such as IM diclofenac). Stones under 5 mm usually pass on their own. Fever with an obstructed kidney is an emergency that needs urgent decompression (nephrostomy or stent).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('02c43eb9-0f45-59f3-9352-7cbccd0ebab9', 'e7ffb89d-c73e-52e0-b9ea-28fa844ebac5', 'A', 'Non-contrast CT of the kidneys, ureters and bladder (CT KUB) within 24 hours', true, 0),
  ('9369acea-9fec-54f1-a18f-f3f476f9b0cc', 'e7ffb89d-c73e-52e0-b9ea-28fa844ebac5', 'B', 'Plain abdominal X-ray', false, 1),
  ('752869ea-df65-5c4d-a484-b9fa9dc4b757', 'e7ffb89d-c73e-52e0-b9ea-28fa844ebac5', 'C', 'Cystoscopy', false, 2),
  ('508bad41-9786-5c56-b935-860491557a0f', 'e7ffb89d-c73e-52e0-b9ea-28fa844ebac5', 'D', 'IV urogram', false, 3),
  ('145bdf96-08f6-5c5a-bfbf-cf41f724d0e0', 'e7ffb89d-c73e-52e0-b9ea-28fa844ebac5', 'E', 'MRI of the abdomen', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a23388c0-018d-5e0e-b49d-88090ca233c7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 68 year old man has 1 year of urinary hesitancy, poor stream, terminal dribbling and nocturia twice a night. Digital rectal examination shows a smooth, symmetrically enlarged, non-tender prostate with a palpable median sulcus. His PSA is within the age-specific range and his symptoms are bothersome. What is the SINGLE most appropriate initial drug treatment?', 'These are lower urinary tract symptoms from benign prostatic hyperplasia. NICE recommends an alpha-blocker such as tamsulosin for moderate-severe voiding symptoms; it relaxes prostatic smooth muscle and works within days. Warn about postural hypotension and retrograde ejaculation. A 5-alpha reductase inhibitor (finasteride) is added for a large prostate (over 30 g) or a high PSA, and takes months to work. Antimuscarinics treat overactive bladder (storage) symptoms.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9744b9fd-a11f-50c8-9b9f-3031f146b2e5', 'a23388c0-018d-5e0e-b49d-88090ca233c7', 'A', 'Desmopressin', false, 0),
  ('7278c96b-e272-57dd-80cf-20101d6e369e', 'a23388c0-018d-5e0e-b49d-88090ca233c7', 'B', 'Oxybutynin', false, 1),
  ('304ad8b3-6663-5c18-aab7-b3b768d061d9', 'a23388c0-018d-5e0e-b49d-88090ca233c7', 'C', 'Finasteride as first-line', false, 2),
  ('e076f5ad-64ce-5ed5-817a-071c07d93768', 'a23388c0-018d-5e0e-b49d-88090ca233c7', 'D', 'Bicalutamide', false, 3),
  ('aea6b226-9801-5272-957f-8be6ec6dbef8', 'a23388c0-018d-5e0e-b49d-88090ca233c7', 'E', 'Tamsulosin', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('47d9692b-dfde-5e91-ac9f-fe4323408f43', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 6 year old boy is brought in with puffiness around his eyes in the mornings and swollen ankles for 1 week. Urine dipstick shows 4+ protein and no blood. His serum albumin is 18 g/L and blood pressure is normal. His kidney function is normal. What is the SINGLE most likely underlying diagnosis?', 'Nephrotic syndrome is heavy proteinuria, hypoalbuminaemia and oedema, often with hyperlipidaemia. In children, about 90% of cases are minimal change disease, which responds to oral prednisolone, so a renal biopsy is not routinely needed. Patients are at risk of infection and thrombosis. In adults, membranous nephropathy and FSGS are more common. Post-streptococcal glomerulonephritis is nephritic: haematuria, hypertension and oliguria.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('22fd6d5b-75a2-5b41-a26a-cf35015df2b6', '47d9692b-dfde-5e91-ac9f-fe4323408f43', 'A', 'Minimal change disease', true, 0),
  ('38e62857-50cc-5764-bb52-44d6339fe0d7', '47d9692b-dfde-5e91-ac9f-fe4323408f43', 'B', 'Post-streptococcal glomerulonephritis', false, 1),
  ('d4b3e0a1-6df4-5968-ba98-2859170b9fd4', '47d9692b-dfde-5e91-ac9f-fe4323408f43', 'C', 'IgA nephropathy', false, 2),
  ('ebb46df0-0d32-5e15-a8d1-c67ced753552', '47d9692b-dfde-5e91-ac9f-fe4323408f43', 'D', 'Membranous nephropathy', false, 3),
  ('1c37d46d-14f1-5c37-ac87-c6fd92519e1c', '47d9692b-dfde-5e91-ac9f-fe4323408f43', 'E', 'Focal segmental glomerulosclerosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8e78caa8-2c46-5495-bd95-7965c9cd6a76', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 26 year old woman presents with 2 days of right loin pain, fever of 38.8°C, rigors, vomiting and dysuria. She is not pregnant. Her heart rate is 104 beats/minute and blood pressure 118/72 mmHg. The right renal angle is tender. Urine dipstick shows nitrites and leukocytes. She is unable to keep down oral fluids. What is the SINGLE most appropriate management?', 'This is acute pyelonephritis with systemic features and vomiting, so she needs admission and IV antibiotics according to local guidelines (for example cefuroxime or gentamicin), switching to oral treatment when she improves. A midstream urine culture must be sent first. Nitrofurantoin is not suitable for pyelonephritis because it does not reach therapeutic levels in the kidney. Recurrent pyelonephritis or failure to improve warrants imaging.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0890a1b2-dd0e-5c30-81be-fd3aafce69e6', '8e78caa8-2c46-5495-bd95-7965c9cd6a76', 'A', 'Urgent cystoscopy', false, 0),
  ('f346536f-8d32-5dd1-8f4b-59003e6810b8', '8e78caa8-2c46-5495-bd95-7965c9cd6a76', 'B', 'No antibiotics; encourage oral fluids', false, 1),
  ('102cdac9-4459-5d74-85e8-de2c8cb2747b', '8e78caa8-2c46-5495-bd95-7965c9cd6a76', 'C', 'Admit for IV antibiotics after sending a urine culture', true, 2),
  ('2b906983-a812-5030-ac3c-cface6647662', '8e78caa8-2c46-5495-bd95-7965c9cd6a76', 'D', 'Oral nitrofurantoin for 3 days at home', false, 3),
  ('a1526452-295c-59c2-b96e-ca419e004f1e', '8e78caa8-2c46-5495-bd95-7965c9cd6a76', 'E', 'Oral trimethoprim for 3 days', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fb32b371-e0c3-5247-a7a8-7631d1d1ee32', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 66 year old Black African man asks his GP about prostate cancer testing after a friend was diagnosed. He has no urinary symptoms. After counselling, his PSA is 8.2 ng/mL. Digital rectal examination shows a hard, irregular nodule in the left lobe of the prostate. What is the SINGLE most appropriate next step?', 'NICE recommends a suspected cancer pathway referral for a prostate that feels malignant on DRE, or a PSA above the age-specific threshold. Pathways now usually include multiparametric MRI before biopsy. Black men have a higher risk of prostate cancer. PSA can also be raised by BPH, UTI, recent ejaculation or vigorous exercise, so men should be counselled before testing.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ffda8bae-8a5f-50e3-810b-0ff6bfc5abd3', 'fb32b371-e0c3-5247-a7a8-7631d1d1ee32', 'A', 'Repeat PSA in 1 year', false, 0),
  ('e8290b14-d980-58b9-ae19-653d012a8d34', 'fb32b371-e0c3-5247-a7a8-7631d1d1ee32', 'B', 'Start bicalutamide in primary care', false, 1),
  ('56c02da2-26b8-58d8-90e8-bdd10f4d97b2', 'fb32b371-e0c3-5247-a7a8-7631d1d1ee32', 'C', 'Start tamsulosin', false, 2),
  ('f78a052a-7785-53d4-997c-c6361f40cfc9', 'fb32b371-e0c3-5247-a7a8-7631d1d1ee32', 'D', 'Reassure as PSA rises with age', false, 3),
  ('f839d107-1be9-578c-8965-12c1d4907887', 'fb32b371-e0c3-5247-a7a8-7631d1d1ee32', 'E', 'Suspected cancer pathway (two-week wait) referral to urology', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f7b7909e-7dc5-5e4c-9550-d5243a055746', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 64 year old man with type 2 diabetes has an eGFR of 48 mL/min/1.73m2 on two occasions 3 months apart, and an ACR of 40 mg/mmol. What stage of CKD does he have?', 'CKD is classified by eGFR (G1 90 or above, G2 60-89, G3a 45-59, G3b 30-44, G4 15-29, G5 under 15) and ACR (A1 under 3, A2 3-30, A3 over 30 mg/mmol), persisting over 3 months. He is G3a A3. Management is an ACE inhibitor or ARB plus an SGLT2 inhibitor, statin, BP control and monitoring. Nephrology referral is advised for ACR of 70 or above, or rapidly falling eGFR.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('06815146-8d96-51aa-894b-360e9a2547e1', 'f7b7909e-7dc5-5e4c-9550-d5243a055746', 'A', 'G4 A3', false, 0),
  ('e0ed3e5a-1cda-549c-8b8c-8884a50ec6f3', 'f7b7909e-7dc5-5e4c-9550-d5243a055746', 'B', 'G3a A3', true, 1),
  ('f93c77f8-0d10-5ec1-b102-514bbf98e92a', 'f7b7909e-7dc5-5e4c-9550-d5243a055746', 'C', 'G3a A1', false, 2),
  ('12d18a79-04cd-536e-90ff-46a2d17aeeb7', 'f7b7909e-7dc5-5e4c-9550-d5243a055746', 'D', 'G2 A2', false, 3),
  ('0010fcbd-93b9-535e-a067-bbf7272938cc', 'f7b7909e-7dc5-5e4c-9550-d5243a055746', 'E', 'G3b A2', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('92422093-616f-58f4-8dc0-e596282ff62f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 58 year old woman with CKD stage 4 has fatigue and breathlessness. Her Hb is 88 g/L, MCV normal, with ferritin 250 micrograms/L and transferrin saturation 25%. B12 and folate are normal. What is the SINGLE most appropriate treatment?', 'Anaemia of CKD is caused mainly by reduced erythropoietin. Iron status should be optimised first (ferritin over 100 and TSAT over 20%, often with IV iron). Then an ESA is started, aiming for Hb of 100-120 g/L. Overcorrection increases the risk of stroke and hypertension. HIF prolyl hydroxylase inhibitors are newer options.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c001b516-5123-59dd-aaa5-c07f71935307', '92422093-616f-58f4-8dc0-e596282ff62f', 'A', 'Blood transfusion monthly', false, 0),
  ('506baf59-dc29-53cd-8d6d-65a773645cd6', '92422093-616f-58f4-8dc0-e596282ff62f', 'B', 'Erythropoiesis-stimulating agent (e.g. epoetin or darbepoetin)', true, 1),
  ('c10be831-5b8a-5849-a110-f3984b517614', '92422093-616f-58f4-8dc0-e596282ff62f', 'C', 'Vitamin B12 injections', false, 2),
  ('2ac92b7f-b649-5479-908c-25b873eb24ff', '92422093-616f-58f4-8dc0-e596282ff62f', 'D', 'No treatment', false, 3),
  ('c096301b-423b-56b2-b4bd-f292a25bcec5', '92422093-616f-58f4-8dc0-e596282ff62f', 'E', 'Oral iron only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2811622a-0223-5634-89d7-8e8bbbe7213f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 72 year old man has CKD stage 5 and is starting haemodialysis. Which of the following is an indication for urgent dialysis?', 'Indications for urgent dialysis in AKI or CKD include refractory hyperkalaemia, severe metabolic acidosis (pH under 7.15), fluid overload unresponsive to diuretics, uraemic complications (pericarditis, encephalopathy) and certain poisonings (lithium, methanol, ethylene glycol, salicylates). Planned dialysis in CKD is guided by symptoms and eGFR (usually 5-10).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5ec630d4-3512-53a7-b4d1-a517dab55b3e', '2811622a-0223-5634-89d7-8e8bbbe7213f', 'A', 'Urea of 15 mmol/L', false, 0),
  ('51cb3b48-5632-58bd-b7ca-4ff0b8a4906b', '2811622a-0223-5634-89d7-8e8bbbe7213f', 'B', 'Hypertension controlled on two drugs', false, 1),
  ('d3bb9189-0f4f-5704-b9dc-5b87050c58f0', '2811622a-0223-5634-89d7-8e8bbbe7213f', 'C', 'eGFR of 25', false, 2),
  ('14e2b6c8-f229-5b1b-b605-cbf3681dd2be', '2811622a-0223-5634-89d7-8e8bbbe7213f', 'D', 'Refractory hyperkalaemia (K above 6.5 mmol/L) not responding to medical treatment', true, 3),
  ('b2a83f91-53a4-5375-b4f8-fdeb1dd6e6ac', '2811622a-0223-5634-89d7-8e8bbbe7213f', 'E', 'Mild fatigue', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ba3fa4f4-6ba0-5901-b750-2c3989e6e4a9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 35 year old man has had visible haematuria for 2 days, starting 1 day after a sore throat. He has had similar episodes before. His BP is normal and urine dipstick shows blood 3+ and protein 1+. What is the SINGLE most likely diagnosis?', 'IgA nephropathy is the commonest glomerulonephritis worldwide. It causes visible haematuria within 1-2 days of an upper respiratory infection (synpharyngitic), in young men. Post-streptococcal GN occurs 1-3 weeks after infection with low complement. Renal biopsy shows mesangial IgA deposits. Management is BP control with ACE inhibitors, with immunosuppression for progressive disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2237e648-b6a3-55fd-b612-519dcc601d3c', 'ba3fa4f4-6ba0-5901-b750-2c3989e6e4a9', 'A', 'IgA nephropathy', true, 0),
  ('f5cc1234-22a6-5950-ad43-6ab4e26c9273', 'ba3fa4f4-6ba0-5901-b750-2c3989e6e4a9', 'B', 'Kidney stones', false, 1),
  ('2ed5c7bc-fb07-58bc-bc3e-01d48c59536f', 'ba3fa4f4-6ba0-5901-b750-2c3989e6e4a9', 'C', 'Bladder cancer', false, 2),
  ('fdea2efc-269d-5d83-9661-01dd9b302915', 'ba3fa4f4-6ba0-5901-b750-2c3989e6e4a9', 'D', 'Post-streptococcal glomerulonephritis', false, 3),
  ('206eb544-f230-5f02-88d8-d3b88084037c', 'ba3fa4f4-6ba0-5901-b750-2c3989e6e4a9', 'E', 'Nephrotic syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ef421243-d66e-50e2-a435-22ef8530e67c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 32 year old man has had haemoptysis and acute kidney injury over a week. Urinalysis shows blood and protein with red cell casts. Anti-glomerular basement membrane antibodies are positive. What is the SINGLE most likely diagnosis?', 'Anti-GBM disease causes rapidly progressive glomerulonephritis and pulmonary haemorrhage, from antibodies against type IV collagen. It is more common in smokers. Biopsy shows linear IgG deposition. Treatment is urgent plasma exchange, steroids and cyclophosphamide. ANCA-associated vasculitis (GPA) also causes pulmonary-renal syndrome but has positive ANCA.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('529b6812-935b-5b84-b3f5-ee1c50c4463c', 'ef421243-d66e-50e2-a435-22ef8530e67c', 'A', 'SLE', false, 0),
  ('52320425-f622-52fc-87de-ba763aea3d1b', 'ef421243-d66e-50e2-a435-22ef8530e67c', 'B', 'IgA nephropathy', false, 1),
  ('a3ab816e-13d6-52d7-92bc-02232abce0f1', 'ef421243-d66e-50e2-a435-22ef8530e67c', 'C', 'Henoch-Schönlein purpura', false, 2),
  ('a8c03c9b-81cf-5dc5-ad43-f9ae1b6a9cae', 'ef421243-d66e-50e2-a435-22ef8530e67c', 'D', 'Granulomatosis with polyangiitis', false, 3),
  ('3fc8bf75-3154-5ea0-84de-b80224376185', 'ef421243-d66e-50e2-a435-22ef8530e67c', 'E', 'Goodpasture''s disease (anti-GBM disease)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a40de40f-55ba-5b91-a40c-12ea6c438d84', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 55 year old man has had nasal crusting, nosebleeds, haemoptysis and sinusitis for 3 months. He now has AKI with haematuria. c-ANCA (anti-PR3) is positive. What is the SINGLE most likely diagnosis?', 'GPA (formerly Wegener''s) is a small-vessel vasculitis affecting the upper airways (sinusitis, nasal crusting, saddle-nose deformity), lungs (nodules, haemorrhage) and kidneys (rapidly progressive GN), with c-ANCA (PR3). Treatment is induction with steroids plus rituximab or cyclophosphamide, then maintenance. Microscopic polyangiitis is p-ANCA (MPO) without ENT involvement.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4230b5df-cde2-553b-b2f2-7e5453a3bc0e', 'a40de40f-55ba-5b91-a40c-12ea6c438d84', 'A', 'Goodpasture''s disease', false, 0),
  ('e99d2d94-0c90-5c5a-8d42-ecb3947ac265', 'a40de40f-55ba-5b91-a40c-12ea6c438d84', 'B', 'Sarcoidosis', false, 1),
  ('b9034a62-0f30-5144-8620-c09ae9356d0f', 'a40de40f-55ba-5b91-a40c-12ea6c438d84', 'C', 'Microscopic polyangiitis', false, 2),
  ('8120db6f-ff16-5c75-9680-0b71c31937f0', 'a40de40f-55ba-5b91-a40c-12ea6c438d84', 'D', 'Granulomatosis with polyangiitis', true, 3),
  ('8698d56c-3e86-5723-bd59-d2624b606379', 'a40de40f-55ba-5b91-a40c-12ea6c438d84', 'E', 'Eosinophilic granulomatosis with polyangiitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('22d1e2e1-8f53-5893-a90f-4e1e51096ad5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 40 year old man has had hypertension and flank pain with haematuria. Both kidneys are palpable. Ultrasound shows bilaterally enlarged kidneys with multiple cysts. His father needed dialysis at 55. What is an important extra-renal association to ask about?', 'ADPKD (PKD1/PKD2) causes bilateral renal cysts, hypertension, haematuria, flank pain and progressive CKD. Extrarenal features include liver cysts, intracranial berry aneurysms (screening if there is a family history of SAH), mitral valve prolapse and diverticular disease. Tolvaptan can slow progression in selected patients.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
