  ('b510d19b-0514-5676-ad56-837817a511fb', '22d1e2e1-8f53-5893-a90f-4e1e51096ad5', 'A', 'Intracranial berry aneurysms (family history of subarachnoid haemorrhage)', true, 0),
  ('3009fee1-18d4-5bc8-a918-5ffeb8de6f51', '22d1e2e1-8f53-5893-a90f-4e1e51096ad5', 'B', 'Pancreatic cancer', false, 1),
  ('7eb91ef4-330c-5da1-a437-224185de6c11', '22d1e2e1-8f53-5893-a90f-4e1e51096ad5', 'C', 'Lung fibrosis', false, 2),
  ('238f8f44-0834-5566-b7da-50c9f8dc1a21', '22d1e2e1-8f53-5893-a90f-4e1e51096ad5', 'D', 'Hearing loss', false, 3),
  ('0d6b0da9-b20c-59a9-bfd7-8d8594740280', '22d1e2e1-8f53-5893-a90f-4e1e51096ad5', 'E', 'Colonic polyps', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9e2b3d38-9f73-58f9-b1f4-9cdf95f51a11', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 55 year old man has had painless visible haematuria for 1 week. He has smoked for 30 years and worked in the dye industry. Urine culture is negative. What is the SINGLE most likely diagnosis?', 'Bladder cancer is mostly urothelial carcinoma. Risk factors are smoking, occupational exposure to aromatic amines (dyes, rubber) and cyclophosphamide, while schistosomiasis causes squamous cell carcinoma. NICE recommends a suspected cancer referral for adults aged 45 and over with unexplained visible haematuria without UTI, or that persists after UTI treatment. Investigation is flexible cystoscopy and CT urogram.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
