  ('63cf797d-077c-581b-9d10-bc94e691906c', '9e2b3d38-9f73-58f9-b1f4-9cdf95f51a11', 'A', 'Kidney stone', false, 0),
  ('8c427c40-1385-5f61-9a7a-fce32ebbf197', '9e2b3d38-9f73-58f9-b1f4-9cdf95f51a11', 'B', 'Renal cell carcinoma', false, 1),
  ('b828afa5-0dbb-5d33-ba28-471df8ebe5fd', '9e2b3d38-9f73-58f9-b1f4-9cdf95f51a11', 'C', 'Glomerulonephritis', false, 2),
  ('a12dd173-c238-5103-89a5-8d5bcb2d5b91', '9e2b3d38-9f73-58f9-b1f4-9cdf95f51a11', 'D', 'Prostate cancer', false, 3),
  ('d1c16731-99a2-5407-a10f-7679866e2c17', '9e2b3d38-9f73-58f9-b1f4-9cdf95f51a11', 'E', 'Transitional cell (urothelial) carcinoma of the bladder', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('19a5b875-233c-5ece-962c-079517f0519d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 62 year old man has had painless haematuria, left flank pain and a palpable left flank mass. He has weight loss. Bloods show polycythaemia and hypercalcaemia. A left varicocele has recently appeared. What is the SINGLE most likely diagnosis?', 'Renal cell carcinoma (clear cell is the commonest type) classically presents with haematuria, loin pain and a flank mass, though it is often found by chance. Paraneoplastic features include polycythaemia (EPO), hypercalcaemia (PTHrP) and hypertension. A left varicocele can result from tumour in the left renal vein. It is associated with smoking, obesity and von Hippel-Lindau. Treatment is nephrectomy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
