  ('f57a67e7-8ee4-5547-b75c-15753c09b2a7', '19a5b875-233c-5ece-962c-079517f0519d', 'A', 'Renal cell carcinoma', true, 0),
  ('ca55df2b-8688-5f50-8def-813607b13d3c', '19a5b875-233c-5ece-962c-079517f0519d', 'B', 'Bladder cancer', false, 1),
  ('767eca65-1c57-5e77-b739-2d932939ef5d', '19a5b875-233c-5ece-962c-079517f0519d', 'C', 'Wilms tumour', false, 2),
  ('26f0557d-0657-5d61-bffa-899082ba11f6', '19a5b875-233c-5ece-962c-079517f0519d', 'D', 'Kidney stone', false, 3),
