insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1323c542-aeba-5398-a187-0c3764c4c29e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 78 year old man has been unable to pass urine for 12 hours with suprapubic pain. He has a palpable, tender bladder. He recently started a cold remedy containing pseudoephedrine. What is the SINGLE most appropriate immediate management?', 'Acute urinary retention (painful, palpable bladder) is relieved by urethral catheterisation, and the residual volume is recorded. Precipitants include BPH, constipation, anticholinergics, sympathomimetics, opioids, infection and anaesthesia. Tamsulosin is started before a trial without catheter. Chronic retention is usually painless with large volumes, and post-obstructive diuresis needs monitoring.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
