  ('f26c0f32-57d9-57a6-a4fc-770f0e7d8d26', '1323c542-aeba-5398-a187-0c3764c4c29e', 'A', 'Prescribe tamsulosin and send home', false, 0),
  ('db5ef123-b4b3-50bf-a6d5-f75c3650dd0e', '1323c542-aeba-5398-a187-0c3764c4c29e', 'B', 'Advise hot bath', false, 1),
  ('4ca36fd2-742c-5e41-a3bf-44d7bca7044c', '1323c542-aeba-5398-a187-0c3764c4c29e', 'C', 'Urethral catheterisation', true, 2),
  ('92b6a488-0889-59d3-8870-66542989d8a1', '1323c542-aeba-5398-a187-0c3764c4c29e', 'D', 'Suprapubic catheter as first-line', false, 3),
  ('7a478942-700a-5497-8755-a6f533e289b9', '1323c542-aeba-5398-a187-0c3764c4c29e', 'E', 'Abdominal CT first', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8cc09d01-1910-5c48-b029-a383da9a7823', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 25 year old man has had sudden severe right testicular pain and vomiting for 3 hours. On examination the testis is very tender and high-riding. His Doppler ultrasound is scheduled for tomorrow morning. What is the SINGLE most appropriate action?', 'Suspected testicular torsion needs immediate surgical exploration without waiting for imaging, ideally within 6 hours of onset. Salvage rates fall sharply after 6 hours. At surgery, the testis is untwisted and fixed (bilateral orchidopexy), or removed if non-viable.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
