  ('1c6d30a9-404d-59a8-ba12-b1f6b394a2e5', '8cc09d01-1910-5c48-b029-a383da9a7823', 'A', 'Immediate surgical exploration (do not wait for imaging)', true, 0),
  ('69c5102f-a7d8-5d0e-86b4-8e77e5ec19b3', '8cc09d01-1910-5c48-b029-a383da9a7823', 'B', 'Oral antibiotics', false, 1),
  ('a632d57a-eb38-580b-94c6-c34763499dfa', '8cc09d01-1910-5c48-b029-a383da9a7823', 'C', 'Analgesia and discharge', false, 2),
  ('5c3887e0-4072-5ee6-bb99-65af94429401', '8cc09d01-1910-5c48-b029-a383da9a7823', 'D', 'Manual detorsion and discharge without surgery', false, 3),
  ('bc570024-5823-5178-8cc3-9ae3a24b25eb', '8cc09d01-1910-5c48-b029-a383da9a7823', 'E', 'Wait for ultrasound tomorrow', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8fe318df-9215-5172-8625-bc18a1943164', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 32 year old man has noticed a painless lump in his right testis for 1 month. Examination shows a hard, irregular mass that cannot be separated from the testis and does not transilluminate. What is the SINGLE most appropriate next step?', 'A painless hard testicular mass is testicular cancer until proven otherwise, most commonly in men aged 15-45. Risk factors include undescended testis. Seminomas may raise beta-hCG, while non-seminomatous germ cell tumours raise AFP and/or beta-hCG. FNA and scrotal biopsy are avoided because they risk seeding. Treatment is radical inguinal orchidectomy, often curative.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('56c38587-8e65-555f-a4de-f0665a27fac4', '8fe318df-9215-5172-8625-bc18a1943164', 'A', 'Reassure; likely a cyst', false, 0),
  ('1c555dd7-ea34-5da9-8ca1-3c4ffa34f753', '8fe318df-9215-5172-8625-bc18a1943164', 'B', 'Urgent scrotal ultrasound and suspected cancer referral, with tumour markers (AFP, beta-hCG, LDH)', true, 1),
  ('26e04054-3d33-561d-ba32-326598cfd190', '8fe318df-9215-5172-8625-bc18a1943164', 'C', 'Review in 6 months', false, 2),
  ('32ad9c44-bf95-55d6-b00a-d4ef015dd4e2', '8fe318df-9215-5172-8625-bc18a1943164', 'D', 'Antibiotics for epididymitis', false, 3),
  ('691f627c-096f-5f60-a338-2c199b4eaf09', '8fe318df-9215-5172-8625-bc18a1943164', 'E', 'Fine needle aspiration of the testis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c5861d84-f361-5ed0-9f5f-eef63d52c7af', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 28 year old man has a painless swelling above his left testis. It is separate from the testis, transilluminates and is cystic. What is the SINGLE most likely diagnosis?', 'Epididymal cysts are separate from the testis (usually above and behind it), transilluminate and are often multiple. They are benign. A hydrocele surrounds the testis, so the testis may be hard to feel separately. A varicocele feels like a bag of worms. Ultrasound confirms the diagnosis if unclear. No treatment is needed unless symptomatic.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
