  ('784cbb78-a154-5930-ac17-8dcf35e9a02a', 'c5861d84-f361-5ed0-9f5f-eef63d52c7af', 'A', 'Epididymal cyst', true, 0),
  ('a21907a6-dea8-5baf-8af2-29b8a9ef7efd', 'c5861d84-f361-5ed0-9f5f-eef63d52c7af', 'B', 'Varicocele', false, 1),
  ('5ece3c1e-f805-5b13-aa4a-f00d1c5a40df', 'c5861d84-f361-5ed0-9f5f-eef63d52c7af', 'C', 'Inguinal hernia', false, 2),
  ('e2ab58d1-c9a7-5a66-b279-eca0f93f2747', 'c5861d84-f361-5ed0-9f5f-eef63d52c7af', 'D', 'Testicular tumour', false, 3),
  ('de12820f-9250-5d0f-868b-04137f50188a', 'c5861d84-f361-5ed0-9f5f-eef63d52c7af', 'E', 'Hydrocele', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2f0fa418-452e-52a3-9889-3f71a8049dda', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 68 year old man has erectile dysfunction for 1 year, with intact morning erections lost recently. He has hypertension, type 2 diabetes and smokes. What is the SINGLE most appropriate first-line treatment, after assessing cardiovascular risk?', 'ED is often vascular and can be an early marker of cardiovascular disease, so cardiovascular risk should be assessed (lipids, HbA1c, BP). PDE5 inhibitors are first-line. They are contraindicated with nitrates and nicorandil because of severe hypotension. Testosterone is only for proven hypogonadism. Lifestyle changes improve outcomes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('01da6bed-6405-5772-b87e-95b9c66289c6', '2f0fa418-452e-52a3-9889-3f71a8049dda', 'A', 'Penile prosthesis', false, 0),
  ('9ba80c6f-8c25-5954-9c0b-f05dca135f27', '2f0fa418-452e-52a3-9889-3f71a8049dda', 'B', 'Alprostadil injection as first-line', false, 1),
  ('83cf2a52-a604-5317-b952-7369849ad0fc', '2f0fa418-452e-52a3-9889-3f71a8049dda', 'C', 'Testosterone injections', false, 2),
  ('88b95f46-431e-58a9-bd86-a8d70c0249de', '2f0fa418-452e-52a3-9889-3f71a8049dda', 'D', 'A phosphodiesterase-5 inhibitor (e.g. sildenafil)', true, 3),
  ('edb7bc2c-e5c5-56d2-818a-e4ace42130c2', '2f0fa418-452e-52a3-9889-3f71a8049dda', 'E', 'Tamsulosin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d287675a-eb2c-5d7f-a386-2f17bcaddaae', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 42 year old woman has recurrent UTIs (three episodes in 6 months), each confirmed on culture. She is not pregnant and has no structural abnormality on ultrasound. Behavioural measures have not helped. What is the SINGLE most appropriate preventive option?', 'Recurrent UTI (2 or more in 6 months, or 3 or more in 12 months) is managed with behavioural advice, then options including methenamine hippurate, vaginal oestrogen in postmenopausal women, or antibiotic prophylaxis (single-dose post-coital or continuous low-dose). D-mannose may be considered. Prophylaxis should be reviewed every 6 months.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4d131060-e0a1-58c5-b43b-3c8e340f7e9f', 'd287675a-eb2c-5d7f-a386-2f17bcaddaae', 'A', 'Cystoscopy for all', false, 0),
  ('3384be88-8f0d-5245-8ab1-cd2e718b0312', 'd287675a-eb2c-5d7f-a386-2f17bcaddaae', 'B', 'IV antibiotics monthly', false, 1),
  ('e3c1f7dd-e343-55b9-8c51-d81969e10b59', 'd287675a-eb2c-5d7f-a386-2f17bcaddaae', 'C', 'Consider antibiotic prophylaxis (e.g. trimethoprim or nitrofurantoin at night) or post-coital prophylaxis if related to intercourse', true, 2),
  ('a2b4d0fc-afbb-545a-864f-5697e1196e9b', 'd287675a-eb2c-5d7f-a386-2f17bcaddaae', 'D', 'No treatment', false, 3),
  ('76d1c292-4c26-54ab-8819-cd15f7086743', 'd287675a-eb2c-5d7f-a386-2f17bcaddaae', 'E', 'Lifelong ciprofloxacin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7697565b-ef66-5e39-ae47-8c73c7fdfaec', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 60 year old man had a CT scan for abdominal pain that showed a 2.5 cm non-obstructing stone in the left renal pelvis. He has recurrent infections. What is the SINGLE most appropriate treatment?', 'NICE recommends PCNL for kidney stones over 20 mm. For stones of 10-20 mm, ESWL or ureteroscopy is used. Small asymptomatic stones under 5 mm may be monitored. Ureteric stones under 10 mm may be treated with ESWL, or alpha-blockers to help passage. Stones should be analysed and metabolic causes investigated in recurrent stone formers.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('11c590ef-942b-5e41-bd8c-280eefaa2e50', '7697565b-ef66-5e39-ae47-8c73c7fdfaec', 'A', 'Oral tamsulosin', false, 0),
  ('13804721-fd7d-5cdf-9dfd-c76ef3f3d8e9', '7697565b-ef66-5e39-ae47-8c73c7fdfaec', 'B', 'Extracorporeal shock wave lithotripsy', false, 1),
  ('ea5c6488-ebef-5a18-909a-fbca21969354', '7697565b-ef66-5e39-ae47-8c73c7fdfaec', 'C', 'Increased fluid intake alone', false, 2),
  ('5fae2607-0472-59db-a53e-806b1717b65f', '7697565b-ef66-5e39-ae47-8c73c7fdfaec', 'D', 'Percutaneous nephrolithotomy (PCNL)', true, 3),
  ('6bf6abbd-9138-5a6a-9f51-ceaafe848b23', '7697565b-ef66-5e39-ae47-8c73c7fdfaec', 'E', 'Watchful waiting', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bc787976-0ba9-5a83-8705-237a977bb43c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 70 year old man has a creatinine rise from 95 to 240 micromol/L over 3 days. Urine output is reduced. He is euvolaemic and his urinalysis is bland. He recently started trimethoprim and omeprazole. Renal ultrasound shows normal-sized kidneys with no hydronephrosis. Urine shows white cells and eosinophils. What is the SINGLE most likely cause?', 'Acute interstitial nephritis is usually drug-induced (PPIs, NSAIDs, penicillins, trimethoprim, rifampicin). It can cause fever, rash, eosinophilia and white cells or eosinophils in the urine. The culprit drug is stopped and steroids are considered. (Trimethoprim can also raise creatinine by blocking tubular secretion without a true fall in GFR.)', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b6529a4b-1396-5447-b683-f219421fc1ef', 'bc787976-0ba9-5a83-8705-237a977bb43c', 'A', 'Prerenal AKI', false, 0),
  ('04b9722f-3ec3-5045-903f-9349b71faca7', 'bc787976-0ba9-5a83-8705-237a977bb43c', 'B', 'Acute tubular necrosis from contrast', false, 1),
  ('a98c40f5-cdd6-5ba7-8059-5d754798bb7a', 'bc787976-0ba9-5a83-8705-237a977bb43c', 'C', 'Glomerulonephritis', false, 2),
  ('bc053b7d-bf33-541e-9612-bfa2730b787b', 'bc787976-0ba9-5a83-8705-237a977bb43c', 'D', 'Acute interstitial nephritis', true, 3),
  ('c6422f35-641e-55c4-8076-2e280212ae40', 'bc787976-0ba9-5a83-8705-237a977bb43c', 'E', 'Post-renal obstruction', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ebb224de-f0dc-5759-ad24-ddda64f8f610', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 48 year old man was crushed under a collapsed wall for 6 hours. His urine is dark brown and dipstick-positive for blood, but microscopy shows no red cells. CK is 85,000 U/L and potassium 6.4 mmol/L. What is the SINGLE most appropriate management?', 'Rhabdomyolysis releases myoglobin, which gives a positive dipstick for blood without red cells, and causes AKI, hyperkalaemia, hypocalcaemia and hyperphosphataemia. Management is aggressive IV crystalloid to maintain high urine output, treatment of hyperkalaemia, and monitoring for compartment syndrome. Dialysis is needed for refractory hyperkalaemia, acidosis or fluid overload.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9a57bf94-0eea-59ec-89a4-e9d8fb69e51b', 'ebb224de-f0dc-5759-ad24-ddda64f8f610', 'A', 'Wait for repeat CK', false, 0),
  ('74f1ea2f-4940-52ec-909b-189c4829dfcd', 'ebb224de-f0dc-5759-ad24-ddda64f8f610', 'B', 'Oral bicarbonate only', false, 1),
  ('b0f64f9f-937d-5d62-83f0-795636f214c3', 'ebb224de-f0dc-5759-ad24-ddda64f8f610', 'C', 'IV furosemide alone', false, 2),
  ('6b091242-6a3a-5a74-824f-1e28376a2d5b', 'ebb224de-f0dc-5759-ad24-ddda64f8f610', 'D', 'Fluid restriction', false, 3),
  ('dbedbde4-c4ac-5469-b4cd-85b48be75a09', 'ebb224de-f0dc-5759-ad24-ddda64f8f610', 'E', 'Aggressive IV fluids targeting high urine output, with treatment of hyperkalaemia', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2dffbc75-b2ce-5875-b676-9d3bd81fe049', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 65 year old woman with CKD stage 3b and type 2 diabetes is having a CT with IV contrast. What is the SINGLE most appropriate measure to reduce her risk of contrast-associated AKI?', 'Risk factors for contrast-associated AKI include an eGFR under 30 (or under 45 for intra-arterial contrast), diabetes, heart failure, dehydration and nephrotoxic drugs. Prevention is IV hydration (0.9% saline or bicarbonate) for at-risk patients, and temporarily pausing metformin, NSAIDs and ACE inhibitors where appropriate. Renal function is checked 48-72 hours afterwards.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9149941b-ab76-5050-a935-eed85d67f70f', '2dffbc75-b2ce-5875-b676-9d3bd81fe049', 'A', 'Ensure adequate hydration (IV fluids if high risk) and consider pausing metformin (and nephrotoxic drugs)', true, 0),
  ('3df6c023-70ba-5138-ae51-60c5dfb6d0bb', '2dffbc75-b2ce-5875-b676-9d3bd81fe049', 'B', 'No precautions needed', false, 1),
  ('863d81f6-c750-5a28-839a-cef1c00cd3ad', '2dffbc75-b2ce-5875-b676-9d3bd81fe049', 'C', 'Haemodialysis after contrast', false, 2),
  ('37977ad1-5e61-53cb-8abb-86caa673c65e', '2dffbc75-b2ce-5875-b676-9d3bd81fe049', 'D', 'Give IV furosemide before contrast', false, 3),
  ('b100f0d4-5a37-57bc-a8ad-c8f254dee522', '2dffbc75-b2ce-5875-b676-9d3bd81fe049', 'E', 'N-acetylcysteine is essential', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4daef493-e8d3-5b98-9c16-d67fa815efee', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 30 year old man with sickle cell disease presents with a painful erection lasting 5 hours. What is the SINGLE most appropriate management?', 'Priapism lasting more than 4 hours is an emergency. Ischaemic (low-flow) priapism, as in sickle cell disease and with intracavernosal drugs or antipsychotics, risks permanent erectile dysfunction. Management is corporal aspiration, then intracavernosal phenylephrine, then surgical shunts. Non-ischaemic (high-flow) priapism after trauma is painless and less urgent.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('47c6bd93-5297-526c-8b85-84332e650af8', '4daef493-e8d3-5b98-9c16-d67fa815efee', 'A', 'Cold shower only', false, 0),
  ('c9c99a19-f83b-533a-8de2-d43c0bbb4f40', '4daef493-e8d3-5b98-9c16-d67fa815efee', 'B', 'Oral sildenafil', false, 1),
  ('2338ae8d-0221-59ae-b14f-712d991f0c28', '4daef493-e8d3-5b98-9c16-d67fa815efee', 'C', 'Urgent urology referral for aspiration of the corpora cavernosa (and intracavernosal phenylephrine if needed)', true, 2),
  ('d003c1e4-e042-5430-a322-776e278789ab', '4daef493-e8d3-5b98-9c16-d67fa815efee', 'D', 'Oral antibiotics', false, 3),
  ('c38342db-a2a4-5b0b-9089-81fe311a121f', '4daef493-e8d3-5b98-9c16-d67fa815efee', 'E', 'Wait for it to settle over 24 hours', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4c6415ca-2faa-526d-8e42-9673b1c19f63', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 38 year old woman with heavy proteinuria (8 g/day), serum albumin 22 g/L and oedema has a renal biopsy showing thickened glomerular basement membranes with subepithelial ''spikes''. Anti-PLA2R antibodies are positive. What is the SINGLE most likely diagnosis?', 'Membranous nephropathy is the commonest cause of nephrotic syndrome in adults. Primary disease is linked to anti-PLA2R antibodies. Secondary causes include malignancy, SLE, hepatitis B and drugs. Nephrotic syndrome increases the risk of thrombosis (including renal vein thrombosis), infection and hyperlipidaemia. Management is ACE inhibitors, diuretics, statins, anticoagulation if high risk and immunosuppression (rituximab).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fd115385-46da-5dfe-9a30-109891494b75', '4c6415ca-2faa-526d-8e42-9673b1c19f63', 'A', 'FSGS', false, 0),
  ('2a974362-2b95-5d5b-91e3-21b9d602dd2f', '4c6415ca-2faa-526d-8e42-9673b1c19f63', 'B', 'Diabetic nephropathy', false, 1),
  ('2c50c507-7947-50ca-b454-e89814d82fe3', '4c6415ca-2faa-526d-8e42-9673b1c19f63', 'C', 'Minimal change disease', false, 2),
  ('24cb5473-25f9-5943-adda-1a8b94b88af9', '4c6415ca-2faa-526d-8e42-9673b1c19f63', 'D', 'IgA nephropathy', false, 3),
  ('29b6612a-3579-5225-aba3-90e82a66739e', '4c6415ca-2faa-526d-8e42-9673b1c19f63', 'E', 'Membranous nephropathy', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c6e94738-9f61-54b5-928c-ae0387fc720a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 24 year old man has mild discomfort in his left scrotum for 4 months. He has noticed his scrotum is lower on the left than on the right, especially in the evenings. He has palpable structures in his left scrotum that feel worm-like. There is no tenderness on palpation. Which is the most appropriate next investigation?', 'A ''bag of worms'' in the left scrotum that is more prominent on standing or later in the day is a varicocele. Scrotal ultrasound with Doppler confirms it. Varicoceles are more common on the left because the left testicular vein drains into the left renal vein at a right angle. A new right-sided or non-reducing varicocele needs imaging to exclude a renal tumour.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e065ca4a-0bd0-5d87-bbdc-e23ea472d06e', 'c6e94738-9f61-54b5-928c-ae0387fc720a', 'A', 'Gram stained urethral smear', false, 0),
  ('1240927d-ec78-5632-a1db-561095ccb95c', 'c6e94738-9f61-54b5-928c-ae0387fc720a', 'B', 'Midstream urine for culture and sensitivity', false, 1),
  ('175d1c8c-ac2b-5f18-bef5-7b8ddf80aac3', 'c6e94738-9f61-54b5-928c-ae0387fc720a', 'C', 'Scrotal exploration', false, 2),
  ('0ce174ac-cb8e-55df-9923-b8847249b634', 'c6e94738-9f61-54b5-928c-ae0387fc720a', 'D', 'Semen analysis', false, 3),
  ('7bb1a594-9d9a-588d-b25a-6ed1b0fde6a3', 'c6e94738-9f61-54b5-928c-ae0387fc720a', 'E', 'Ultrasound scan of scrotum', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1ad3d522-55f7-540b-be87-c687f97a9c83', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 60 year old man is anuric on the renal unit. 2 days ago ge had a left nephrectomy for renal cell carcinoma. His temperature is 39.0°C, pulse rate 98 bpm and BP 80/60 mmHg. Investigations: Ultrasound scan of abdomen: Gross dilatation of the upper right renal tract and a stone impacted at the pelvi-ureteric junction. Which is the most appropriate therapeutic intervention?', 'He has an obstructed, infected single remaining kidney (after left nephrectomy), with fever, hypotension and anuria. This is a urological emergency: the urgent priority is to decompress the kidney, ideally by percutaneous nephrostomy, with IV antibiotics. Lithotripsy is for elective stone management and is contraindicated with active infection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1053f33b-24df-576b-8211-c74e56744c3b', '1ad3d522-55f7-540b-be87-c687f97a9c83', 'A', 'Bladder catheterisation', false, 0),
  ('72cfe203-a603-598c-b6d1-b29392c79b1a', '1ad3d522-55f7-540b-be87-c687f97a9c83', 'B', 'Lithotripsy', false, 1),
  ('cfbe5249-0ad2-5137-8b9a-9da47e3e3034', '1ad3d522-55f7-540b-be87-c687f97a9c83', 'C', 'Percutaneous right nephrostomy', true, 2),
  ('9fea0d26-fbdd-5b6a-ab13-64b29ebc7e62', '1ad3d522-55f7-540b-be87-c687f97a9c83', 'D', 'Retrograde drainage of the right renal tract', false, 3),
  ('8336f917-713e-5f74-9ed6-7c5b1eebfbd0', '1ad3d522-55f7-540b-be87-c687f97a9c83', 'E', 'Suprapubic catheterisation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6cbeed7f-fdf4-5576-abe6-ad23c26a32b7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 10 year old girl has bloody diarrhoea for 5 days and is seen in the Emergency Department. 3 days ago she developed vomiting, and abdominal pain. She had been on a school trip to a local farm 1 week ago. She has previously been healthy and is not taking any medications. She is pale, drowsy and dehydrated with some swelling of her ankles. Her pulse rate is 120 bpm and BP 140/96 mmHg. Investigations: Haemoglobin 80 g/L (115–140) White cell count 3.2 x 10⁹/L (4.0–11.0) Platelets 76 x 10⁹/L (150–400) Sodium 130 mmol/L (135–146) Potassium 4.0 mmol/L (3.5–5.0) Urea 14 mmol/L (2.5–6.5) Creatinine 200 micromol/L (34–65) Blood film: fragmented red blood cells (schistocytes, helmet cells) Which is the most likely underlying diagnosis?', 'Bloody diarrhoea after a farm visit (E. coli O157) followed by microangiopathic haemolytic anaemia (schistocytes), thrombocytopenia and acute kidney injury is haemolytic uraemic syndrome. Management is supportive, with fluid balance and dialysis if needed. Antibiotics and antimotility drugs are avoided.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b93fa76b-edf0-5837-bb14-b11f48f7f644', '6cbeed7f-fdf4-5576-abe6-ad23c26a32b7', 'A', 'Bacillus cereus enteritis', false, 0),
  ('d191f5ca-ce6c-5076-a0d8-50ac3c3db6ff', '6cbeed7f-fdf4-5576-abe6-ad23c26a32b7', 'B', 'Diabetic ketoacidosis', false, 1),
  ('3f30db3e-fe48-5a19-971c-054c7ef4a1ae', '6cbeed7f-fdf4-5576-abe6-ad23c26a32b7', 'C', 'Haemolytic uraemic syndrome', true, 2),
  ('32576b5d-39cf-5b7c-84d4-6027ae076117', '6cbeed7f-fdf4-5576-abe6-ad23c26a32b7', 'D', 'Idiopathic thrombocytopenic purpura', false, 3),
  ('4719ec0a-9619-5d0e-b6c4-edcf19bff872', '6cbeed7f-fdf4-5576-abe6-ad23c26a32b7', 'E', 'Thrombotic thrombocytopenic purpura', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7243c10b-3b51-51c8-8c0e-2415d27098ae', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 58 year old woman has worsening urinary frequency and urgency for 18 months. She passes small volumes of urine. She has had no periods for 4 years and has been prescribed vaginal oestrogen for the last 9 months. Abdominal and pelvic examination are normal. Urinalysis is normal. Which is the most appropriate initial management?', 'Frequency and urgency with small volumes and normal urinalysis is overactive bladder. NICE recommends bladder training for at least 6 weeks as first-line before drug treatment (antimuscarinics or mirabegron). Lifestyle advice includes reducing caffeine and managing fluid intake.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a6362614-b02c-5be7-ae4f-a07c852aec98', '7243c10b-3b51-51c8-8c0e-2415d27098ae', 'A', 'Intermittent self-catheterisation', false, 0),
  ('cca4edc2-0489-5713-b10a-5999ab24d238', '7243c10b-3b51-51c8-8c0e-2415d27098ae', 'B', 'Nitrofurantoin', false, 1),
  ('d8295327-ea5c-5137-a35e-ece6ad78c334', '7243c10b-3b51-51c8-8c0e-2415d27098ae', 'C', 'Oxybutynin', false, 2),
  ('8a1bd74d-e328-53c3-84c3-b26a176e7ad9', '7243c10b-3b51-51c8-8c0e-2415d27098ae', 'D', 'Refer to urology', false, 3),
  ('310d19f1-bade-59cb-b748-f7718e3f87fa', '7243c10b-3b51-51c8-8c0e-2415d27098ae', 'E', 'Supervised bladder training', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('41074f20-04fd-5000-ade6-613d7c4cc713', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 72 year old man has 4 days of painless haematuria and is seen in the urology Department. He had a myocardial infarction 2 years ago. He takes warfarin since being diagnosed with atrial fibrillation. His temperature is 36.9°C, pulse rate 78 bpm and BP 134/78 mmHg. Investigations: Clotting screening: INR 4.0 (Target: 2.5) aPTT 72 seconds (22–41) Prothrombin time 35 seconds (10–12) Fibrinogen 4.0 g/dL (1.5–4.0) Urinalysis: Blood: 4+ Leucocytes: Negative Nitrites: Negative Glucose: Negative Which is the most appropriate initial investigation?', 'Painless visible haematuria in an older man needs investigation for urological malignancy even when the INR is high, because anticoagulation unmasks rather than causes bleeding. CT urography (CT KUB with contrast) images the upper tracts, and flexible cystoscopy is also needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('37225022-f84a-544f-b190-fa99d5ecf601', '41074f20-04fd-5000-ade6-613d7c4cc713', 'A', 'CT scan of kidneys, ureter and bladder', true, 0),
  ('47c926ae-d12f-59ea-bfe7-14e9df865fdb', '41074f20-04fd-5000-ade6-613d7c4cc713', 'B', 'Prostate specific antigen level', false, 1),
  ('d1c88d42-7cea-58c5-b65f-45781194bfe9', '41074f20-04fd-5000-ade6-613d7c4cc713', 'C', 'Ultrasound of abdomen', false, 2),
  ('fb25fdc7-072d-5db3-ac42-f13a03113f76', '41074f20-04fd-5000-ade6-613d7c4cc713', 'D', 'Urodynamic studies', false, 3),
  ('04c2daaa-bb87-57ab-a01d-9ee7b05c48ef', '41074f20-04fd-5000-ade6-613d7c4cc713', 'E', 'X-ray of kidneys, ureter and bladder', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c4e1749e-8791-5ff9-8e29-60a17e0d0792', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 52 year old lorry driver attends his GP because his wife complains about his loud snoring and that he sometimes stops breathing during sleep. He falls asleep while watching television and has nearly dozed off at traffic lights. His BMI is 38 kg/m2 and his neck circumference is 45 cm. His Epworth Sleepiness Score is 16. What is the SINGLE most appropriate investigation?', 'The picture is classic obstructive sleep apnoea (OSA): obesity, witnessed apnoeas, snoring and marked daytime sleepiness (Epworth over 10). The diagnosis is made with an overnight sleep study, usually home respiratory polygraphy or full polysomnography, which gives the apnoea-hypopnoea index. The multiple sleep latency test is used for narcolepsy. As a professional driver with excessive sleepiness, he must also be advised not to drive and to tell the DVLA.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('086ef028-f77e-534e-8555-fee34d6626cb', 'c4e1749e-8791-5ff9-8e29-60a17e0d0792', 'A', 'Overnight sleep study (polysomnography or respiratory polygraphy)', true, 0),
  ('a703f2a0-7230-5340-a4b9-4b11ce5e4ba8', 'c4e1749e-8791-5ff9-8e29-60a17e0d0792', 'B', 'Chest X-ray', false, 1),
  ('e36bd1f2-4642-5938-ab75-e978c8c1f6eb', 'c4e1749e-8791-5ff9-8e29-60a17e0d0792', 'C', 'Multiple sleep latency test', false, 2),
  ('f5607130-5556-5514-94b4-bb4c03408e3d', 'c4e1749e-8791-5ff9-8e29-60a17e0d0792', 'D', 'Spirometry', false, 3),
  ('f3c38707-5c89-5fbb-be65-ca6c67b7ea66', 'c4e1749e-8791-5ff9-8e29-60a17e0d0792', 'E', 'Arterial blood gas', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b1f318c5-005c-5334-8188-002534271bbb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 34 year old woman presents with sudden-onset right-sided pleuritic chest pain and breathlessness. She takes the combined oral contraceptive pill and returned from a long-haul flight 3 days ago. Her heart rate is 112 beats/minute, respiratory rate 24 breaths/minute and oxygen saturation 93% on air. Blood pressure is 124/78 mmHg. Her two-level Wells score is 6. What is the SINGLE most appropriate investigation?', 'With a Wells score above 4, pulmonary embolism is ''likely''. NICE advises arranging immediate CTPA (with interim anticoagulation if there will be a delay). A D-dimer is only used when the Wells score is 4 or less, to rule PE out. A V/Q scan is an alternative when CTPA is unsuitable, for example in contrast allergy or severe renal impairment. A chest X-ray may be done alongside but does not confirm PE.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('226a9b06-171e-52c5-998e-91eeb25126d5', 'b1f318c5-005c-5334-8188-002534271bbb', 'A', 'D-dimer', false, 0),
  ('12c1b71a-e909-54f8-875e-712dec896893', 'b1f318c5-005c-5334-8188-002534271bbb', 'B', 'Troponin', false, 1),
  ('89213ad6-6335-55fb-9fb6-d7b99bbd2bec', 'b1f318c5-005c-5334-8188-002534271bbb', 'C', 'Ventilation-perfusion (V/Q) scan', false, 2),
  ('483c38ef-d3c6-5336-a047-c6a82d02e97a', 'b1f318c5-005c-5334-8188-002534271bbb', 'D', 'CT pulmonary angiography (CTPA)', true, 3),
  ('1a71f0a3-b148-5dca-a4b9-ded29b0b5dd3', 'b1f318c5-005c-5334-8188-002534271bbb', 'E', 'Lower limb Doppler ultrasound', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('59811430-59d1-5b2b-a5f9-c6395d772441', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 22 year old man with asthma presents to the Emergency Department with worsening breathlessness over 2 days. He is unable to complete sentences. His respiratory rate is 28 breaths/minute, heart rate 118 beats/minute, oxygen saturation 95% on air and peak expiratory flow is 45% of his best. He has had one dose of nebulised salbutamol. What is the SINGLE most appropriate additional treatment now?', 'This is acute severe asthma: PEF 33-50%, unable to complete sentences, RR at least 25, HR at least 110. Every patient with an acute asthma attack should receive a systemic corticosteroid early, as oral prednisolone 40-50 mg daily for at least 5 days. Nebulised ipratropium is added for severe or life-threatening attacks. IV magnesium is considered when there is a poor response to initial bronchodilators, and aminophylline only after senior review. Antibiotics are not routinely indicated.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a73c1dfd-0772-5332-927f-1cd47a78aa0d', '59811430-59d1-5b2b-a5f9-c6395d772441', 'A', 'Oral prednisolone 40-50 mg', true, 0),
  ('d3c77817-2c6b-5328-8c9d-c8c856234cee', '59811430-59d1-5b2b-a5f9-c6395d772441', 'B', 'Oral amoxicillin', false, 1),
  ('f22acadd-3067-53a7-ab1a-b56253775c12', '59811430-59d1-5b2b-a5f9-c6395d772441', 'C', 'IV aminophylline', false, 2),
  ('33f4af42-8f9f-503c-b377-7d96d8dc1262', '59811430-59d1-5b2b-a5f9-c6395d772441', 'D', 'Oral montelukast', false, 3),
  ('35ddc69d-40df-54d7-b7b7-013abb0cedb2', '59811430-59d1-5b2b-a5f9-c6395d772441', 'E', 'IV magnesium sulfate', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('52c65205-583e-59c0-ac5a-90d256573746', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 70 year old man presents with 3 days of fever, productive cough and breathlessness. He is alert and orientated. His urea is 8.4 mmol/L, respiratory rate 32 breaths/minute and blood pressure 104/58 mmHg. A chest X-ray shows right lower lobe consolidation. What is his CURB-65 score?', 'CURB-65 scores 1 point each for Confusion, Urea above 7 mmol/L, Respiratory rate 30 or above, BP systolic below 90 or diastolic 60 or below, and age 65 or above. He scores for urea, respiratory rate, diastolic BP (58) and age, giving 4 (no confusion). A score of 3-5 is high severity: admit, consider critical care, and treat with IV antibiotics according to local guidance.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
