insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b0103d2a-8ae2-5f43-95a1-1afbe067f189', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 58 year old woman who has smoked 35 pack-years presents with gradually worsening breathlessness on exertion and a morning cough productive of white sputum for 2 years. She has no wheeze at rest. What is the SINGLE most appropriate investigation to confirm the most likely diagnosis?', 'Chronic exertional breathlessness and productive cough in a long-term smoker suggest COPD. Diagnosis is confirmed with post-bronchodilator spirometry showing an FEV1/FVC ratio below 0.7, which shows obstruction that is not fully reversible. A chest X-ray is done to exclude other causes such as lung cancer but does not confirm COPD. FeNO and peak flow variability are used in asthma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('acb01411-f0a1-5bd9-8586-e8f999df9bae', 'b0103d2a-8ae2-5f43-95a1-1afbe067f189', 'A', 'CT chest', false, 0),
  ('98f36889-c2ca-52cf-acbd-e9bec81e82ab', 'b0103d2a-8ae2-5f43-95a1-1afbe067f189', 'B', 'Post-bronchodilator spirometry', true, 1),
  ('8ea32925-2c18-5347-830e-33fe338dbaf8', 'b0103d2a-8ae2-5f43-95a1-1afbe067f189', 'C', 'Chest X-ray', false, 2),
  ('c52473e5-c3c9-5ebb-960a-67c1d0b9d78c', 'b0103d2a-8ae2-5f43-95a1-1afbe067f189', 'D', 'Fractional exhaled nitric oxide', false, 3),
  ('d62a8a1c-ddc6-5375-8c78-3d4e893e77bf', 'b0103d2a-8ae2-5f43-95a1-1afbe067f189', 'E', 'Peak flow diary', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ecd5c339-f71c-5755-a8dc-23356ab6405b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 22 year old tall, thin man presents with sudden-onset left-sided pleuritic chest pain and mild breathlessness. He smokes cannabis. His oxygen saturation is 97% on air and observations are otherwise normal. A chest X-ray shows a left pneumothorax with a 1.5 cm rim at the level of the hilum. He has no underlying lung disease. What is the SINGLE most appropriate management?', 'This is a small primary spontaneous pneumothorax (less than 2 cm) in a patient with minimal symptoms. The BTS 2023 guideline supports conservative management with outpatient review and clear safety-netting. Larger or symptomatic pneumothoraces may need ambulatory devices, needle aspiration or a drain. He should stop smoking, and must not fly until it has resolved or dive at all without definitive surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('39721f98-b445-57bc-bc0c-3afaf5613c36', 'ecd5c339-f71c-5755-a8dc-23356ab6405b', 'A', 'Admit for high-flow oxygen for 1 week', false, 0),
  ('5560dc46-6342-5506-be9a-abee7f76a94b', 'ecd5c339-f71c-5755-a8dc-23356ab6405b', 'B', 'Urgent video-assisted thoracoscopic surgery', false, 1),
  ('cd4b7881-3a68-5580-a320-6e0c581de4b5', 'ecd5c339-f71c-5755-a8dc-23356ab6405b', 'C', 'Conservative management with outpatient follow-up and safety-netting', true, 2),
  ('0d085876-65a8-50ab-96d7-97098e4532a3', 'ecd5c339-f71c-5755-a8dc-23356ab6405b', 'D', 'Immediate chest drain', false, 3),
  ('4dda3fa7-d7a9-59d4-9cef-6fdb4d8ab4ba', 'ecd5c339-f71c-5755-a8dc-23356ab6405b', 'E', 'Needle aspiration in all cases', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('52882632-1daf-595f-bff8-f1346db3ad33', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 31 year old Black woman presents with tender red nodules on her shins, ankle pain and a dry cough. Her chest X-ray shows bilateral hilar lymphadenopathy with clear lung fields. Her serum calcium is 2.74 mmol/L. What is the SINGLE most likely diagnosis?', 'Erythema nodosum, arthralgia and bilateral hilar lymphadenopathy is Löfgren''s syndrome, an acute form of sarcoidosis with a good prognosis. Sarcoidosis is a multisystem non-caseating granulomatous disease. Granulomas produce 1-alpha-hydroxylase, which can cause hypercalcaemia, and serum ACE may be raised. Many cases resolve on their own, and steroids are used for progressive or organ-threatening disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('54201ade-7977-5da5-8cf4-99e36707312b', '52882632-1daf-595f-bff8-f1346db3ad33', 'A', 'Lymphoma', false, 0),
  ('acb64fcc-f9c2-5185-a784-561adc405954', '52882632-1daf-595f-bff8-f1346db3ad33', 'B', 'Tuberculosis', false, 1),
  ('f083ca92-f2cc-5793-9a60-d5a2702bf84e', '52882632-1daf-595f-bff8-f1346db3ad33', 'C', 'Sarcoidosis', true, 2),
  ('71cd32c0-8099-5284-80e4-1ac70fe12502', '52882632-1daf-595f-bff8-f1346db3ad33', 'D', 'Hypersensitivity pneumonitis', false, 3),
  ('800f4199-1cb8-524e-ba59-856b1b6b0f48', '52882632-1daf-595f-bff8-f1346db3ad33', 'E', 'Lung adenocarcinoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5f683a37-583a-5047-a792-6369e23e919c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 34 year old man who moved from India 6 months ago has 2 months of cough, weight loss, night sweats and haemoptysis. His chest X-ray shows right upper lobe cavitation. Sputum smear shows acid-fast bacilli. He is HIV negative. What is the SINGLE most appropriate treatment regimen?', 'Active pulmonary TB is treated with the standard 6-month regimen: 2 months of four drugs (RIPE) as the initial phase, then 4 months of rifampicin and isoniazid. Pyridoxine is given with isoniazid to prevent peripheral neuropathy. TB is a notifiable disease, contacts need screening, and directly observed therapy may be used. Key side effects: rifampicin turns secretions orange and induces liver enzymes, and ethambutol can cause optic neuritis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1611c00b-1bef-569d-adb2-bada738c1e90', '5f683a37-583a-5047-a792-6369e23e919c', 'A', 'Isoniazid alone for 6 months', false, 0),
  ('ea10e747-918f-5490-9eaa-3ef8a8e55dba', '5f683a37-583a-5047-a792-6369e23e919c', 'B', 'Clarithromycin and amoxicillin for 2 weeks', false, 1),
  ('1c95cb2f-fecf-5041-8738-9b5fa6ad7b2b', '5f683a37-583a-5047-a792-6369e23e919c', 'C', 'Rifampicin, isoniazid, pyrazinamide and ethambutol for 2 weeks', false, 2),
  ('ac1ba972-a6ba-55bb-bcd6-68a430815d60', '5f683a37-583a-5047-a792-6369e23e919c', 'D', 'Rifampicin and isoniazid alone for 6 months', false, 3),
  ('7bb0d6af-bd92-521f-8c42-80851a36d283', '5f683a37-583a-5047-a792-6369e23e919c', 'E', 'Rifampicin, isoniazid, pyrazinamide and ethambutol for 2 months, then rifampicin and isoniazid for 4 months', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f294257e-9668-5baa-a1b9-88225bc813c2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 66 year old man who smokes presents with confusion and a cough. His serum sodium is 118 mmol/L, serum osmolality is low and urine osmolality is inappropriately high. He appears clinically euvolaemic and his thyroid and cortisol levels are normal. A chest X-ray shows a central hilar mass. Which type of lung cancer is MOST likely?', 'Hyponatraemia with low serum osmolality, inappropriately concentrated urine and euvolaemia, with normal thyroid and adrenal function, is SIADH. Small cell lung cancer is the classic cause of SIADH (ectopic ADH) and ectopic ACTH, and is usually centrally located. Squamous cell carcinoma is linked to hypercalcaemia from PTHrP. Adenocarcinoma is the most common type overall and in non-smokers, and is often peripheral.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1994ac8d-a94c-50bf-b340-d1bca227702d', 'f294257e-9668-5baa-a1b9-88225bc813c2', 'A', 'Adenocarcinoma', false, 0),
  ('7bf7f7da-10b0-5dbd-a902-bec21e4fbf6b', 'f294257e-9668-5baa-a1b9-88225bc813c2', 'B', 'Squamous cell carcinoma', false, 1),
  ('b39ef103-ce9f-5d4d-8a20-a4bdb114d77b', 'f294257e-9668-5baa-a1b9-88225bc813c2', 'C', 'Mesothelioma', false, 2),
  ('162daec0-2e7d-58c0-b37e-8bfa1af24c33', 'f294257e-9668-5baa-a1b9-88225bc813c2', 'D', 'Small cell lung cancer', true, 3),
  ('b490b182-a3d4-5cbc-b156-694feedf7703', 'f294257e-9668-5baa-a1b9-88225bc813c2', 'E', 'Carcinoid tumour', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c0ebe512-e31c-581b-82bd-1306b55a269e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 26 year old man with asthma uses salbutamol 4 times a week and wakes once a week with wheeze. He takes no other inhalers. His inhaler technique is good. According to BTS/NICE/SIGN 2024 guidance, what is the SINGLE most appropriate change?', 'The 2024 joint BTS/NICE/SIGN guideline recommends anti-inflammatory reliever (AIR) therapy: low-dose budesonide/formoterol as needed, for newly diagnosed or uncontrolled asthma in people aged 12 and over. Salbutamol alone is no longer recommended. Escalation is to MART (maintenance and reliever therapy). An LABA must never be used without an ICS.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c8137535-c54f-5735-8d87-c3df9dfdce4a', 'c0ebe512-e31c-581b-82bd-1306b55a269e', 'A', 'Continue salbutamol only', false, 0),
  ('2c2409a7-a765-5d71-b7f6-1f16c33f21f1', 'c0ebe512-e31c-581b-82bd-1306b55a269e', 'B', 'Add oral montelukast alone', false, 1),
  ('d941f6b9-1797-56c3-9006-095659ca0944', 'c0ebe512-e31c-581b-82bd-1306b55a269e', 'C', 'Start a long-acting beta-agonist alone', false, 2),
  ('781bd4aa-091d-5c3c-8ec1-c6837db261b4', 'c0ebe512-e31c-581b-82bd-1306b55a269e', 'D', 'Start a low-dose ICS/formoterol combination inhaler used as needed (AIR therapy)', true, 3),
  ('51b8c8f5-f7f9-5200-959c-7be98eab9092', 'c0ebe512-e31c-581b-82bd-1306b55a269e', 'E', 'Start oral prednisolone 40 mg for 5 days', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d06a01ff-2b83-5cd4-ace3-4b21b47beb82', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 27 year old woman has a 6-month history of an intermittent cough and wheeze, worse at night and with exercise. Examination is normal between episodes. According to NICE 2024 guidance, which test is recommended FIRST to support a diagnosis of asthma in adults?', 'The 2024 BTS/NICE/SIGN guidance recommends measuring blood eosinophils or FeNO first to look for type 2 inflammation. Bronchodilator reversibility on spirometry or peak flow variability are then used if needed, with a bronchial challenge test reserved for uncertain cases. Diagnosis needs objective testing.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('92a0f605-c235-5096-ab28-beb7b6fde2e3', 'd06a01ff-2b83-5cd4-ace3-4b21b47beb82', 'A', 'Sputum culture', false, 0),
  ('1b8b8aad-5b20-5e40-9023-1ceef295eb48', 'd06a01ff-2b83-5cd4-ace3-4b21b47beb82', 'B', 'Chest X-ray', false, 1),
  ('f0125146-95c9-5809-9772-82c4aca5db46', 'd06a01ff-2b83-5cd4-ace3-4b21b47beb82', 'C', 'Methacholine challenge test only', false, 2),
  ('e24db9c7-f0dd-5b76-8a44-ebeab23057ac', 'd06a01ff-2b83-5cd4-ace3-4b21b47beb82', 'D', 'Blood eosinophil count or fractional exhaled nitric oxide (FeNO)', true, 3),
  ('15c06426-629e-544b-be57-9025ff89d734', 'd06a01ff-2b83-5cd4-ace3-4b21b47beb82', 'E', 'CT chest', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e99cec57-ee38-58c8-8636-9a2346ec2121', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 68 year old man with COPD has had more breathlessness, increased sputum volume and green sputum for 3 days. He is alert, with oxygen saturation 90% on air and respiratory rate 22 breaths/minute. What is the SINGLE most appropriate treatment for his exacerbation?', 'A COPD exacerbation with increased purulent sputum is treated with more frequent short-acting bronchodilators, oral prednisolone 30 mg daily for 5 days and an oral antibiotic (amoxicillin, doxycycline or clarithromycin). Controlled oxygen targets saturations of 88-92% in people at risk of hypercapnia. Patients should be reviewed for hospital admission if severe.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c65dd8f3-25c6-50eb-b3ae-e85462730ed3', 'e99cec57-ee38-58c8-8636-9a2346ec2121', 'A', 'Nebulised hypertonic saline', false, 0),
  ('a5d45d55-e88a-5dc6-9af7-cc84374434b4', 'e99cec57-ee38-58c8-8636-9a2346ec2121', 'B', 'Oral prednisolone 30 mg for 5 days, increased bronchodilators and oral antibiotics', true, 1),
  ('05eec32f-f5a3-59df-b042-43a6b17e1d71', 'e99cec57-ee38-58c8-8636-9a2346ec2121', 'C', 'Oral prednisolone for 6 weeks', false, 2),
  ('45c7d2a3-e335-5ade-adaf-ddc04597ee8f', 'e99cec57-ee38-58c8-8636-9a2346ec2121', 'D', 'High-flow oxygen at 15 L/minute', false, 3),
  ('a44f2d0f-5e5f-5adc-a747-770b8e168bc2', 'e99cec57-ee38-58c8-8636-9a2346ec2121', 'E', 'IV aminophylline', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9263c50d-a810-50e9-bb2f-d05b7d3b25ca', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 66 year old woman with COPD (FEV1 45% predicted) is still breathless and has had two exacerbations this year despite a LAMA/LABA inhaler. Her blood eosinophil count is 0.4 x 10^9/L. What is the SINGLE most appropriate next step?', 'NICE recommends adding an ICS (triple therapy) for COPD patients with ongoing exacerbations or symptoms on LAMA/LABA, especially with asthmatic or steroid-responsive features such as a raised eosinophil count. Long-term oral steroids are not recommended. Pulmonary rehabilitation, smoking cessation and vaccinations are essential throughout.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('705b4ec2-92d0-5db1-a261-a61ce1ddd584', '9263c50d-a810-50e9-bb2f-d05b7d3b25ca', 'A', 'Add an inhaled corticosteroid (triple therapy LAMA/LABA/ICS)', true, 0),
  ('f8946ef0-4e8d-5f88-a78f-263446296087', '9263c50d-a810-50e9-bb2f-d05b7d3b25ca', 'B', 'Stop the LAMA', false, 1),
  ('2aaec07c-9b0d-5b51-8d93-a0951ae0e108', '9263c50d-a810-50e9-bb2f-d05b7d3b25ca', 'C', 'Start roflumilast first', false, 2),
  ('45b8d37e-5309-5568-abcf-e8a720ae2c74', '9263c50d-a810-50e9-bb2f-d05b7d3b25ca', 'D', 'Long-term oral prednisolone', false, 3),
  ('f603c274-ae22-56a9-8237-aa81856e2f5e', '9263c50d-a810-50e9-bb2f-d05b7d3b25ca', 'E', 'Long-term oral theophylline alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a21b272b-2acb-5198-8e72-1d98e19fa242', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 70 year old man with severe COPD has resting oxygen saturations of 87% on air when stable. ABG on air on two occasions 3 weeks apart shows PaO2 6.9 kPa. He stopped smoking 2 years ago. What is the SINGLE most appropriate management?', 'Long-term oxygen therapy is indicated in stable COPD with a PaO2 below 7.3 kPa, or below 8 kPa with polycythaemia, peripheral oedema, pulmonary hypertension or nocturnal hypoxaemia. It is used for at least 15 hours a day and improves survival. Smokers are not offered LTOT because of fire risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('91db6ace-0bd3-5108-a4b5-d547b0cc37c4', 'a21b272b-2acb-5198-8e72-1d98e19fa242', 'A', 'Long-term oxygen therapy for at least 15 hours a day', true, 0),
  ('85777166-3a70-5c1a-a369-d54a3aeee24a', 'a21b272b-2acb-5198-8e72-1d98e19fa242', 'B', 'Ambulatory oxygen only during exercise', false, 1),
  ('ec948436-df0b-5a8a-adb7-bdf7a72939ab', 'a21b272b-2acb-5198-8e72-1d98e19fa242', 'C', 'No oxygen therapy is indicated', false, 2),
  ('5bad9464-bb62-55fd-b33c-89d4c4722bab', 'a21b272b-2acb-5198-8e72-1d98e19fa242', 'D', 'Nocturnal oxygen only', false, 3),
  ('31507080-42fc-5fa7-9f88-8c2f95048efa', 'a21b272b-2acb-5198-8e72-1d98e19fa242', 'E', 'Short-burst oxygen when breathless', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('32ccbef4-ae1e-5839-ac65-538a58df3c1f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 28 year old man has had a cough productive of large volumes of purulent sputum for years, with recurrent chest infections. He has finger clubbing and coarse crackles in both lower zones. What is the SINGLE most appropriate investigation to confirm the diagnosis?', 'Chronic productive cough, recurrent infections, clubbing and coarse crackles suggest bronchiectasis. High-resolution CT is diagnostic (dilated airways larger than the adjacent artery, the ''signet ring'' sign). Causes include post-infection, cystic fibrosis, primary ciliary dyskinesia and immunodeficiency. Management is airway clearance physiotherapy and antibiotics for exacerbations.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b203f754-f201-5e67-aed2-730d345687f0', '32ccbef4-ae1e-5839-ac65-538a58df3c1f', 'A', 'Chest X-ray only', false, 0),
  ('e9732677-3908-5b7e-be22-d37c1557c4dd', '32ccbef4-ae1e-5839-ac65-538a58df3c1f', 'B', 'Spirometry', false, 1),
  ('c0aa346a-bdef-5c4b-839c-64c2d24c6866', '32ccbef4-ae1e-5839-ac65-538a58df3c1f', 'C', 'Sputum cytology', false, 2),
  ('b88f4360-57c3-55b5-a784-34787ee696b8', '32ccbef4-ae1e-5839-ac65-538a58df3c1f', 'D', 'Bronchoscopy', false, 3),
  ('15113fbb-dc3e-5815-b8e0-5809f0863dcf', '32ccbef4-ae1e-5839-ac65-538a58df3c1f', 'E', 'High-resolution CT of the chest', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('34c68774-3748-5ce6-a5ce-5b0fc0b4dba0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 4 year old boy has had recurrent chest infections and loose, pale, greasy stools with failure to thrive. He had meconium ileus at birth. What is the SINGLE most appropriate diagnostic investigation?', 'Cystic fibrosis is autosomal recessive (CFTR gene). It presents with recurrent chest infections, pancreatic insufficiency (steatorrhoea, failure to thrive) and meconium ileus. A sweat chloride above 60 mmol/L is diagnostic. Newborn screening uses immunoreactive trypsinogen on the heel prick. Management is multidisciplinary, including CFTR modulators.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e3261013-99b4-5445-a44c-ae381376b10a', '34c68774-3748-5ce6-a5ce-5b0fc0b4dba0', 'A', 'Chest X-ray', false, 0),
  ('a9ee901d-2b53-5eed-b8d0-7d1a61648315', '34c68774-3748-5ce6-a5ce-5b0fc0b4dba0', 'B', 'Faecal elastase only', false, 1),
  ('5a6f9851-83eb-5ffc-8aca-f19a3e868000', '34c68774-3748-5ce6-a5ce-5b0fc0b4dba0', 'C', 'Serum IgE', false, 2),
  ('7e97e286-697d-5fca-ad06-5a1d626082c9', '34c68774-3748-5ce6-a5ce-5b0fc0b4dba0', 'D', 'Sweat chloride test', true, 3),
  ('a7350f76-6479-5caa-ae5d-f0be838f9d27', '34c68774-3748-5ce6-a5ce-5b0fc0b4dba0', 'E', 'Coeliac serology', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5a1d45c3-1ac8-5458-9244-d49cabd1e855', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 58 year old man who worked as a shipyard pipe lagger for 20 years has had increasing breathlessness and dull chest pain for 3 months. He has lost weight. A chest X-ray shows a unilateral pleural effusion with nodular pleural thickening. What is the SINGLE most likely diagnosis?', 'Asbestos exposure, chest pain, weight loss and a unilateral effusion with nodular pleural thickening suggest malignant mesothelioma. It has a latency of 20-40 years. Diagnosis is by CT and pleural biopsy (thoracoscopy), and the prognosis is poor. It is a prescribed industrial disease, so patients can claim compensation, and the coroner must be informed after death.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8e8c564c-50f9-57d2-a5d8-9ab31d18b6c7', '5a1d45c3-1ac8-5458-9244-d49cabd1e855', 'A', 'Tuberculous pleurisy', false, 0),
  ('7013f578-509d-57b3-a1ef-532fbb1243a7', '5a1d45c3-1ac8-5458-9244-d49cabd1e855', 'B', 'Asbestosis', false, 1),
  ('17a8ce72-0303-5b0e-9a84-0efc6e74f01f', '5a1d45c3-1ac8-5458-9244-d49cabd1e855', 'C', 'Pleural plaques', false, 2),
  ('739ecd31-8d12-57f6-a5dd-9df28b53737b', '5a1d45c3-1ac8-5458-9244-d49cabd1e855', 'D', 'Mesothelioma', true, 3),
  ('62463f1d-1dd6-57fb-a214-387a731f1387', '5a1d45c3-1ac8-5458-9244-d49cabd1e855', 'E', 'Sarcoidosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('517b694f-0ed2-5dc6-b3e7-236aae00b669', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 65 year old woman has a pleural effusion. Pleural fluid protein is 38 g/L and serum protein is 60 g/L. Pleural LDH is 320 U/L and serum LDH is 400 U/L. Which is the SINGLE most likely category and cause?', 'Light''s criteria: an exudate meets any one of pleural/serum protein over 0.5 (here 0.63), pleural/serum LDH over 0.6 (here 0.8), or pleural LDH over two-thirds of the upper limit of normal serum LDH. Exudates come from malignancy, infection (parapneumonic, TB), PE and rheumatoid arthritis. Transudates come from heart failure, cirrhosis and nephrotic syndrome.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0c4bc05f-7682-53f0-aff3-66d16e3da120', '517b694f-0ed2-5dc6-b3e7-236aae00b669', 'A', 'Transudate from heart failure', false, 0),
  ('c72c34ed-2eeb-514c-b226-079513f4328f', '517b694f-0ed2-5dc6-b3e7-236aae00b669', 'B', 'Transudate from nephrotic syndrome', false, 1),
  ('085a3c37-753a-56af-9743-b743f04bb03f', '517b694f-0ed2-5dc6-b3e7-236aae00b669', 'C', 'Transudate from hypothyroidism', false, 2),
  ('9af2cdcf-cdeb-54ab-9632-fe404320359b', '517b694f-0ed2-5dc6-b3e7-236aae00b669', 'D', 'Transudate from cirrhosis', false, 3),
  ('c3c72d67-0595-553c-816c-4bd797516616', '517b694f-0ed2-5dc6-b3e7-236aae00b669', 'E', 'Exudate, such as from malignancy or infection', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a14e3b96-6f6d-5a6f-a21e-88fa8b83f047', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 64 year old man who smokes has had a cough for 4 weeks and one episode of haemoptysis. He has no other symptoms. According to NICE, what is the SINGLE most appropriate action?', 'NICE NG12 recommends a suspected cancer referral for people aged 40 and over with unexplained haemoptysis, or with chest X-ray findings suggesting lung cancer. An urgent chest X-ray (within 2 weeks) is advised for people aged 40 and over with two or more unexplained symptoms (or one if they have ever smoked), such as cough, fatigue, breathlessness or weight loss.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6320c238-d629-5836-9b5a-c06d722891bf', 'a14e3b96-6f6d-5a6f-a21e-88fa8b83f047', 'A', 'Suspected cancer pathway referral (two-week wait) for lung cancer', true, 0),
  ('0e74132b-ed49-5d01-8330-b6dce76d1da6', 'a14e3b96-6f6d-5a6f-a21e-88fa8b83f047', 'B', 'Prescribe antibiotics and review in 6 weeks', false, 1),
  ('3310ccca-76db-5ac0-a1cf-419a02298035', 'a14e3b96-6f6d-5a6f-a21e-88fa8b83f047', 'C', 'Reassure as it is likely a smoker''s cough', false, 2),
  ('e259a7b3-4bb0-5a84-9197-226feae55cb3', 'a14e3b96-6f6d-5a6f-a21e-88fa8b83f047', 'D', 'Chest X-ray in 6 weeks', false, 3),
  ('2b19932a-de3b-5b0d-8c30-903bd33a63f7', 'a14e3b96-6f6d-5a6f-a21e-88fa8b83f047', 'E', 'Routine respiratory referral', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c03af797-2c13-5a2d-86b6-131852aefb7f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 66 year old man who smokes has a chest X-ray for a persistent cough. It shows a 3 cm right upper lobe mass. He is fit and has no other symptoms. What is the SINGLE most appropriate next investigation?', 'For suspected lung cancer, a contrast-enhanced CT of the chest, upper abdomen and adrenals is the first investigation for staging and to guide biopsy. PET-CT and EBUS-guided sampling follow. Treatment depends on histology and stage, and surgery is offered for early non-small cell lung cancer in fit patients.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
