  ('79978ee5-7293-55a2-b5b4-cef8f14f8fd8', 'c03af797-2c13-5a2d-86b6-131852aefb7f', 'A', 'MRI brain', false, 0),
  ('a22bfe52-6c4b-549b-9304-93e4fde90e00', 'c03af797-2c13-5a2d-86b6-131852aefb7f', 'B', 'Contrast-enhanced CT of the chest, liver and adrenal glands', true, 1),
  ('a4940cfc-3075-583c-ad69-056a992f9551', 'c03af797-2c13-5a2d-86b6-131852aefb7f', 'C', 'Bronchoscopy without imaging', false, 2),
  ('13fac405-355b-5947-9c92-0c54718015bd', 'c03af797-2c13-5a2d-86b6-131852aefb7f', 'D', 'Sputum cytology only', false, 3),
  ('a3f32fac-6b5b-5e2e-9579-58a60d5f0465', 'c03af797-2c13-5a2d-86b6-131852aefb7f', 'E', 'Repeat chest X-ray in 6 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0941cc80-c0e9-5fd8-942b-079829d03f6f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 52 year old woman has an incidental 6 mm solid pulmonary nodule on CT. She is a non-smoker with no history of cancer. According to British Thoracic Society guidance, what is the SINGLE most appropriate next step?', 'BTS guidance: nodules under 5 mm (or under 80 mm3) need no follow-up. Nodules of 5-6 mm (80-300 mm3) have CT surveillance at 1 year. Nodules of 8 mm or more (or over 300 mm3) are assessed with risk models (Brock), with PET-CT considered. Risk depends on size, growth, smoking and other features.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a9ca99d1-9a1a-530b-8cc2-fefb4c5145aa', '0941cc80-c0e9-5fd8-942b-079829d03f6f', 'A', 'PET-CT', false, 0),
  ('d5e3fd92-411e-5f4d-a1ce-0b7fdbccd2c1', '0941cc80-c0e9-5fd8-942b-079829d03f6f', 'B', 'CT surveillance (repeat CT at 1 year)', true, 1),
  ('604c6707-a9e0-559f-88ca-cd1e19a5eb67', '0941cc80-c0e9-5fd8-942b-079829d03f6f', 'C', 'Immediate surgical resection', false, 2),
  ('f58afad4-ba1d-54e0-85bd-ab7ad548414a', '0941cc80-c0e9-5fd8-942b-079829d03f6f', 'D', 'No follow-up', false, 3),
  ('a9facf9b-56c6-5ea4-aea5-07ca723d3708', '0941cc80-c0e9-5fd8-942b-079829d03f6f', 'E', 'CT-guided biopsy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('45d558e1-4722-55b2-a0a2-a4c1962fe17c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 34 year old non-smoker has had progressive breathlessness for 6 months. He keeps pigeons. He has inspiratory crackles. His symptoms improve when he is away from home on holiday. What is the SINGLE most likely diagnosis?', 'Breathlessness, crackles and symptoms that improve away from the exposure (here avian antigens) suggest hypersensitivity pneumonitis (bird fancier''s lung). Serum precipitins (IgG) support the diagnosis, and HRCT shows centrilobular nodules and ground glass. The key treatment is avoiding the antigen, with steroids for significant disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
