  ('c3dbdd6a-fbfe-56d4-82c8-9ea362cd2f44', '45d558e1-4722-55b2-a0a2-a4c1962fe17c', 'A', 'Hypersensitivity pneumonitis (extrinsic allergic alveolitis)', true, 0),
  ('bc207401-a3f5-54b1-9c3e-eee07c3b3ed4', '45d558e1-4722-55b2-a0a2-a4c1962fe17c', 'B', 'Asthma', false, 1),
  ('931a7592-9284-5631-9a5e-20bfa8e35707', '45d558e1-4722-55b2-a0a2-a4c1962fe17c', 'C', 'Sarcoidosis', false, 2),
  ('ebcd9d01-226b-5fa6-bcef-56cbcfdccddd', '45d558e1-4722-55b2-a0a2-a4c1962fe17c', 'D', 'Psittacosis', false, 3),
  ('08ffcc72-5022-5262-ad48-20b3a489b2c0', '45d558e1-4722-55b2-a0a2-a4c1962fe17c', 'E', 'Idiopathic pulmonary fibrosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1ac15d75-247b-5ae4-8b74-17aa429150aa', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 40 year old man has had a cough for 3 weeks after a flu-like illness. He has bilateral patchy consolidation on chest X-ray, haemolytic anaemia with cold agglutinins and erythema multiforme. What is the SINGLE most likely causative organism?', 'Mycoplasma pneumoniae causes atypical pneumonia in younger patients, often in epidemics. Extrapulmonary features include cold agglutinin haemolytic anaemia, erythema multiforme and myringitis. It lacks a cell wall, so beta-lactams do not work, and it is treated with macrolides or doxycycline.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e5dcd0d5-eba5-5441-ad23-b005f3046e05', '1ac15d75-247b-5ae4-8b74-17aa429150aa', 'A', 'Klebsiella pneumoniae', false, 0),
  ('26c16bb0-d4b8-5f22-98ea-f50d55d50e11', '1ac15d75-247b-5ae4-8b74-17aa429150aa', 'B', 'Staphylococcus aureus', false, 1),
  ('7942bc40-16b4-55a3-8320-4f3a1cead3d3', '1ac15d75-247b-5ae4-8b74-17aa429150aa', 'C', 'Mycoplasma pneumoniae', true, 2),
  ('40aac408-46c0-5b71-b934-58d9e08549c8', '1ac15d75-247b-5ae4-8b74-17aa429150aa', 'D', 'Streptococcus pneumoniae', false, 3),
  ('bad4bc1f-b385-5489-84f1-5030f2942b9f', '1ac15d75-247b-5ae4-8b74-17aa429150aa', 'E', 'Legionella pneumophila', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('75a8c058-1194-58d0-a687-fed8aeede278', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 61 year old man has pneumonia after a cruise. He has a fever of 39.5°C, diarrhoea, confusion and dry cough. His sodium is 126 mmol/L and LFTs are deranged. What is the SINGLE most appropriate diagnostic test for the likely organism?', 'Legionella pneumophila is spread from contaminated water systems (air conditioning, hotels, cruise ships). It causes pneumonia with hyponatraemia, deranged LFTs, GI symptoms and confusion. A urinary antigen test detects serogroup 1. Treatment is a macrolide or fluoroquinolone. It is notifiable.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('92ee5470-6ae6-5f60-9d6e-2616de84a8c8', '75a8c058-1194-58d0-a687-fed8aeede278', 'A', 'Sputum Ziehl-Neelsen stain', false, 0),
  ('0160e704-7c5d-5599-8719-659531867f98', '75a8c058-1194-58d0-a687-fed8aeede278', 'B', 'Throat swab for viral PCR', false, 1),
  ('569f7bd0-6c7b-5b58-a38e-c9ffa3e08620', '75a8c058-1194-58d0-a687-fed8aeede278', 'C', 'Urinary Legionella antigen', true, 2),
  ('a494c220-37f4-5f9f-80cf-dabc0a241ebe', '75a8c058-1194-58d0-a687-fed8aeede278', 'D', 'Cold agglutinins', false, 3),
  ('b1f5ef0e-f8dd-5796-90bd-b9fd35c594f5', '75a8c058-1194-58d0-a687-fed8aeede278', 'E', 'Blood film', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ec4ba4b5-438a-5c8a-9240-0609890cc813', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 76 year old man with Parkinson''s disease is admitted with fever and cough 3 days after an episode of choking while eating. A chest X-ray shows consolidation in the right lower lobe. What is the SINGLE most likely cause?', 'Aspiration is more likely in people with impaired swallowing (Parkinson''s disease, stroke, reduced consciousness). The right lower lobe is most often affected because the right main bronchus is wider, shorter and more vertical. A speech and language therapy swallowing assessment is important. Antibiotics are given according to local guidance.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('53352250-b48d-55a8-b3b6-3bc6005fdfd9', 'ec4ba4b5-438a-5c8a-9240-0609890cc813', 'A', 'Tuberculosis', false, 0),
  ('ccb526d2-0b87-5124-acc4-ac168db7ca6a', 'ec4ba4b5-438a-5c8a-9240-0609890cc813', 'B', 'Mycoplasma pneumonia', false, 1),
  ('b6211e87-98c0-5840-8bbf-3be0021bdd8d', 'ec4ba4b5-438a-5c8a-9240-0609890cc813', 'C', 'Aspiration pneumonia', true, 2),
  ('3f21a908-46b6-5f6c-9f84-c34d9df262ba', 'ec4ba4b5-438a-5c8a-9240-0609890cc813', 'D', 'Pulmonary embolism', false, 3),
  ('56b1cf78-d8bb-53cf-b8f9-d5c1546db35a', 'ec4ba4b5-438a-5c8a-9240-0609890cc813', 'E', 'Lung abscess from IV drug use', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('585dc069-e153-56a9-8750-6aaef8a215e8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 34 year old man with HIV and a CD4 count of 80 cells/mm3 has 3 weeks of progressive breathlessness on exertion, dry cough and fever. His oxygen saturations fall from 95% to 86% on walking. A chest X-ray shows bilateral perihilar ground-glass shadowing. What is the SINGLE most appropriate treatment?', 'Pneumocystis jirovecii pneumonia occurs with a CD4 count under 200. Exertional desaturation is typical, with perihilar ground glass on X-ray. Treatment is high-dose co-trimoxazole, plus corticosteroids if PaO2 is below 9.3 kPa. Prophylaxis with co-trimoxazole is given when the CD4 count is under 200.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cd2b1a1d-455b-5ebe-9791-b2ae1214644d', '585dc069-e153-56a9-8750-6aaef8a215e8', 'A', 'Fluconazole', false, 0),
  ('04829b05-be5a-5238-b663-9b8d7314246a', '585dc069-e153-56a9-8750-6aaef8a215e8', 'B', 'Rifampicin, isoniazid, pyrazinamide and ethambutol', false, 1),
  ('4802e717-ac71-5fc9-88c1-802996ac69cb', '585dc069-e153-56a9-8750-6aaef8a215e8', 'C', 'High-dose co-trimoxazole, with steroids if hypoxic', true, 2),
  ('86276e97-310a-5415-8f46-bbedd5655b38', '585dc069-e153-56a9-8750-6aaef8a215e8', 'D', 'Amoxicillin', false, 3),
  ('25262cfd-10ac-52ab-bb42-271e723b43e6', '585dc069-e153-56a9-8750-6aaef8a215e8', 'E', 'Aciclovir', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d9029c85-f771-5985-b2f7-2eeec0faac58', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 45 year old man has had an itchy rash, fever and wheeze since starting a new job. His blood eosinophils are very high. He has asthma that is now poorly controlled, with brown sputum plugs and fleeting infiltrates on chest X-ray. What is the SINGLE most likely diagnosis?', 'ABPA is a hypersensitivity reaction to Aspergillus in people with asthma or cystic fibrosis. It causes worsening asthma, eosinophilia, brown mucus plugs, fleeting infiltrates, raised total IgE, Aspergillus-specific IgE/IgG and later proximal bronchiectasis. Treatment is oral steroids with or without itraconazole.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b8801c10-e209-5cde-9a45-7bb6dc9170cd', 'd9029c85-f771-5985-b2f7-2eeec0faac58', 'A', 'Aspergilloma', false, 0),
  ('57c0ff06-edb4-5ee7-9870-f9d495aa50d9', 'd9029c85-f771-5985-b2f7-2eeec0faac58', 'B', 'Tuberculosis', false, 1),
  ('16d7cb4d-d133-5aef-b801-6ebd2abb8353', 'd9029c85-f771-5985-b2f7-2eeec0faac58', 'C', 'Allergic bronchopulmonary aspergillosis', true, 2),
  ('46ba2d86-f3ef-54f3-8cac-ff9959bf9d7a', 'd9029c85-f771-5985-b2f7-2eeec0faac58', 'D', 'Invasive aspergillosis', false, 3),
  ('ab5e08da-e37b-5457-a5b9-f8cfead5c0f5', 'd9029c85-f771-5985-b2f7-2eeec0faac58', 'E', 'Eosinophilic granulomatosis with polyangiitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('adbab086-0cdd-50fa-ba12-e8d2bb37f727', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 24 year old man has sudden breathlessness and right-sided chest pain. A chest X-ray shows a 3 cm right pneumothorax. He is breathless at rest. He has no underlying lung disease. Needle aspiration fails to resolve it. What is the SINGLE most appropriate next step?', 'BTS 2023 guidance: a symptomatic primary pneumothorax is managed with needle aspiration, an ambulatory device or a chest drain. If aspiration fails, a small-bore chest drain is inserted in the safe triangle (the 4th-5th intercostal space in the mid-axillary line, lateral border of pectoralis major, anterior border of latissimus dorsi). Surgery is for persistent air leak or recurrence.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bd73b81d-69cf-54d8-bb31-7b3a3187f7f4', 'adbab086-0cdd-50fa-ba12-e8d2bb37f727', 'A', 'Discharge with follow-up', false, 0),
  ('192021a3-d3d8-5b00-806b-fcf74171d0f0', 'adbab086-0cdd-50fa-ba12-e8d2bb37f727', 'B', 'Urgent surgical pleurodesis', false, 1),
  ('2d8522dc-8b5b-57ba-9d21-37083eb887bf', 'adbab086-0cdd-50fa-ba12-e8d2bb37f727', 'C', 'Repeat needle aspiration three more times', false, 2),
  ('4048cd7f-8f43-5a38-9a27-5084e33f87ca', 'adbab086-0cdd-50fa-ba12-e8d2bb37f727', 'D', 'Insert a small-bore chest drain (Seldinger technique) in the safe triangle', true, 3),
  ('147596c6-2f42-5a20-8938-c771df2ce8f8', 'adbab086-0cdd-50fa-ba12-e8d2bb37f727', 'E', 'High-flow oxygen alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5f93fec8-209d-5941-b957-9c211f0796ca', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 46 year old obese man has loud snoring, witnessed apnoeas and daytime sleepiness. A sleep study confirms moderate-severe obstructive sleep apnoea (AHI 32). He drives a car. What is the SINGLE most appropriate treatment?', 'CPAP is first-line for moderate to severe OSA with symptoms, together with weight loss and avoiding alcohol and sedatives. A mandibular advancement device is an option for mild OSA or CPAP intolerance. With excessive sleepiness, he must not drive and must tell the DVLA until symptoms are controlled.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6d22f462-c564-5aac-9275-25f85d298e0f', '5f93fec8-209d-5941-b957-9c211f0796ca', 'A', 'Benzodiazepine at night', false, 0),
  ('bdc670ed-d4ae-5983-bf03-be9ef825721e', '5f93fec8-209d-5941-b957-9c211f0796ca', 'B', 'Mandibular advancement device as the only option', false, 1),
  ('98957125-34ae-5860-8839-e1ca99546489', '5f93fec8-209d-5941-b957-9c211f0796ca', 'C', 'Tonsillectomy', false, 2),
  ('e8f5b668-966b-56ad-8496-ca576ef21389', '5f93fec8-209d-5941-b957-9c211f0796ca', 'D', 'Oral modafinil', false, 3),
  ('755789d4-8830-5c75-87f9-284bc24c9416', '5f93fec8-209d-5941-b957-9c211f0796ca', 'E', 'Continuous positive airway pressure (CPAP)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('27ce83d9-f881-575b-92b3-441ef506c43a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 55 year old woman has had a dry cough for 8 weeks since starting a new antihypertensive. Her chest examination and chest X-ray are normal. She does not smoke. What is the SINGLE most likely cause?', 'A dry, persistent cough affects up to 15% of people on ACE inhibitors, caused by bradykinin accumulation. It can start weeks to months after starting and resolves within weeks of stopping. An ARB (such as losartan) is a suitable alternative because it does not affect bradykinin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2b38de4b-b0d8-543e-b192-c5f7f8bab6b8', '27ce83d9-f881-575b-92b3-441ef506c43a', 'A', 'Asthma', false, 0),
  ('08aa8955-9216-5524-a859-ec960360dde9', '27ce83d9-f881-575b-92b3-441ef506c43a', 'B', 'Post-nasal drip', false, 1),
  ('c003d399-64d0-5cf1-be45-2fd86b5f4064', '27ce83d9-f881-575b-92b3-441ef506c43a', 'C', 'ACE inhibitor-induced cough', true, 2),
  ('8c3dca69-956f-5d61-859f-37338bc6d280', '27ce83d9-f881-575b-92b3-441ef506c43a', 'D', 'Lung cancer', false, 3),
  ('e9963b8e-b917-5e37-9aa4-f9749a2f7bb5', '27ce83d9-f881-575b-92b3-441ef506c43a', 'E', 'Gastro-oesophageal reflux', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2afb9f43-1ccc-5db4-b907-a3f51bb69315', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 60 year old man had a CT scan for weight loss. It shows enlarged bilateral hilar nodes with an egg-shell pattern of calcification. He worked in a quarry for 30 years. What is the SINGLE most likely diagnosis?', 'Egg-shell calcification of hilar lymph nodes with upper zone nodules is characteristic of silicosis, from inhaling crystalline silica (quarrying, sandblasting, stonework). It increases the risk of TB and lung cancer. Asbestosis causes lower zone fibrosis. These are prescribed industrial diseases.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bc57d662-2ce3-5c0b-a896-d8fbe30a9806', '2afb9f43-1ccc-5db4-b907-a3f51bb69315', 'A', 'Silicosis', true, 0),
  ('b81cd330-fdfd-5682-a98f-852a296bbe6f', '2afb9f43-1ccc-5db4-b907-a3f51bb69315', 'B', 'Berylliosis', false, 1),
  ('8ae9a861-08b4-56d7-b152-d712efa84fc6', '2afb9f43-1ccc-5db4-b907-a3f51bb69315', 'C', 'Sarcoidosis', false, 2),
  ('5b3adc81-eea3-5450-ba59-ac4122ed73fa', '2afb9f43-1ccc-5db4-b907-a3f51bb69315', 'D', 'Coal worker''s pneumoconiosis', false, 3),
  ('af8f31e6-2061-5710-a931-a77ca410bccf', '2afb9f43-1ccc-5db4-b907-a3f51bb69315', 'E', 'Asbestosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e4e7cdc4-f6ad-5f1a-86dd-7d0f048ab0a0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 32 year old woman has had progressive exertional breathlessness and fatigue for 1 year. She had an episode of syncope on exertion. Her chest X-ray and spirometry are normal. Echocardiogram shows an estimated pulmonary artery systolic pressure of 65 mmHg with right ventricular dilatation. CTPA shows no thromboembolic disease. What is the SINGLE most likely diagnosis?', 'Unexplained progressive breathlessness, exertional syncope, a raised pulmonary pressure and right heart strain in a young woman with normal lungs and no thromboembolism suggest pulmonary arterial hypertension (idiopathic or heritable). Right heart catheterisation confirms it (mean PAP over 20 mmHg). Specialist treatment includes endothelin receptor antagonists, PDE5 inhibitors and prostanoids.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a055ba66-3812-5da8-b609-07d650c84156', 'e4e7cdc4-f6ad-5f1a-86dd-7d0f048ab0a0', 'A', 'Mitral stenosis', false, 0),
  ('40cbdf42-31fc-5b53-847f-2e2b595ef344', 'e4e7cdc4-f6ad-5f1a-86dd-7d0f048ab0a0', 'B', 'Asthma', false, 1),
  ('492d39b9-fb74-5198-bc04-806087837c54', 'e4e7cdc4-f6ad-5f1a-86dd-7d0f048ab0a0', 'C', 'Interstitial lung disease', false, 2),
  ('315dd258-c3df-50d4-925e-9f47dbbe66f0', 'e4e7cdc4-f6ad-5f1a-86dd-7d0f048ab0a0', 'D', 'Anxiety', false, 3),
  ('e26f2967-a95c-51d7-a9bb-ad97a9514ef6', 'e4e7cdc4-f6ad-5f1a-86dd-7d0f048ab0a0', 'E', 'Pulmonary arterial hypertension', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f450ca10-67bc-5b55-98fc-f7ff71092e56', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 16 year old with known asthma attends with an acute attack. She is drowsy, her chest is silent, her PEF is 28% of best and her oxygen saturation is 89% on air. Her PaCO2 is 6.4 kPa. What is the SINGLE most appropriate immediate action?', 'Drowsiness, silent chest, PEF under 33%, saturations under 92% and a normal or raised PaCO2 indicate life-threatening asthma. A rising CO2 suggests she is tiring. She needs immediate high-flow oxygen, back-to-back nebulised salbutamol, ipratropium, steroids (IV hydrocortisone or oral prednisolone), IV magnesium and urgent senior or ICU review for possible intubation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6da709d6-9d68-5664-9e51-5b697a68f98f', 'f450ca10-67bc-5b55-98fc-f7ff71092e56', 'A', 'Give oxygen, nebulised salbutamol and ipratropium, IV hydrocortisone, and request immediate ICU/anaesthetic review', true, 0),
  ('74c8e297-b1ce-55a1-b27b-4e1d7ff5cd5f', 'f450ca10-67bc-5b55-98fc-f7ff71092e56', 'B', 'Give oral prednisolone and discharge', false, 1),
  ('99f426b9-d8d1-533d-aa96-f235539bc6c0', 'f450ca10-67bc-5b55-98fc-f7ff71092e56', 'C', 'Arrange a chest X-ray before any treatment', false, 2),
  ('0efdd9e5-c87f-52bf-8fd7-1c2e7ae6b32f', 'f450ca10-67bc-5b55-98fc-f7ff71092e56', 'D', 'Give a salbutamol inhaler via spacer and reassess in 4 hours', false, 3),
  ('9e565e94-fada-5b8e-97e7-0cd9e3b4aaf2', 'f450ca10-67bc-5b55-98fc-f7ff71092e56', 'E', 'Start nebulised budesonide only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('efafbe9d-92f3-59f9-8f17-5ea1c2f5dabf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 72 year old man has had breathlessness for 2 days. His ABG on air shows pH 7.30, PaCO2 7.8 kPa, PaO2 7.6 kPa and bicarbonate 33 mmol/L. He has COPD and remains acidotic despite 1 hour of optimal medical treatment with controlled oxygen. What is the SINGLE most appropriate next step?', 'Acute hypercapnic respiratory acidosis (pH under 7.35, PaCO2 over 6.5 kPa) in a COPD exacerbation that persists despite optimal medical therapy is an indication for NIV (BiPAP). A ceiling of care plan should be agreed before starting. The raised bicarbonate shows chronic CO2 retention with an acute-on-chronic picture. CPAP is used for OSA and type 1 failure.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fca80794-42e0-5bbc-be1e-66ebbf4df9ce', 'efafbe9d-92f3-59f9-8f17-5ea1c2f5dabf', 'A', 'Intubate immediately without trying NIV', false, 0),
  ('4f29eb25-a3f3-5685-bd9a-ee7bf9bd37dd', 'efafbe9d-92f3-59f9-8f17-5ea1c2f5dabf', 'B', 'CPAP', false, 1),
  ('0a7dcd56-5d59-5c6d-92ff-b14399eb92dd', 'efafbe9d-92f3-59f9-8f17-5ea1c2f5dabf', 'C', 'Give IV sodium bicarbonate', false, 2),
  ('6620ba5e-3b38-546f-a691-e1de0b088f2e', 'efafbe9d-92f3-59f9-8f17-5ea1c2f5dabf', 'D', 'Start non-invasive ventilation (BiPAP)', true, 3),
  ('5dad24d0-4d85-520e-ad9f-6e5bd90460dc', 'efafbe9d-92f3-59f9-8f17-5ea1c2f5dabf', 'E', 'Increase oxygen to 15 L/minute', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5ed02eef-f968-5b40-a29e-2c7f3841a8ff', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 52 year old man is reviewed after a first unprovoked pulmonary embolism treated with apixaban for 3 months. He has no active cancer and no ongoing risk factors. He has a low bleeding risk. What is the SINGLE most appropriate advice regarding anticoagulation?', 'NICE recommends at least 3 months of anticoagulation for VTE. For unprovoked VTE, anticoagulation should be considered beyond 3 months (often long-term) if bleeding risk is low and the patient agrees. Provoked VTE with a transient risk factor usually stops at 3 months. IVC filters are only for patients who cannot be anticoagulated.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b99c1be4-f94b-5d76-931b-8375ca39fdba', '5ed02eef-f968-5b40-a29e-2c7f3841a8ff', 'A', 'Switch to aspirin lifelong', false, 0),
  ('35d23611-c257-5d6f-9051-c18160681818', '5ed02eef-f968-5b40-a29e-2c7f3841a8ff', 'B', 'Switch to LMWH lifelong', false, 1),
  ('a26aacff-2a5f-5af8-8845-c02eec42160f', '5ed02eef-f968-5b40-a29e-2c7f3841a8ff', 'C', 'Insert an IVC filter', false, 2),
  ('d0063acb-29dc-560d-af4a-605629412dbc', '5ed02eef-f968-5b40-a29e-2c7f3841a8ff', 'D', 'Stop anticoagulation at 3 months in all cases', false, 3),
  ('2fef8c0b-aeed-5eb3-87e1-4734fcd35320', '5ed02eef-f968-5b40-a29e-2c7f3841a8ff', 'E', 'Consider continuing anticoagulation beyond 3 months after weighing the risks of recurrence and bleeding', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5270ab46-0044-5f82-9345-007f117dcd28', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 26 year old woman has had fever, malaise and a dry cough, followed by pleuritic chest pain. Her chest X-ray shows a large right pleural effusion. Pleural fluid is an exudate with lymphocytosis and low glucose. She was born in Somalia. What is the SINGLE most likely diagnosis?', 'A lymphocytic exudative effusion in someone from a high-prevalence area suggests TB pleurisy. Pleural fluid AFB and culture have low yield, and pleural biopsy (histology showing granulomas and culture) has the highest yield. Raised pleural adenosine deaminase supports the diagnosis. Treatment is standard anti-TB therapy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('233ca532-ed7d-5a74-ad17-aac349e59762', '5270ab46-0044-5f82-9345-007f117dcd28', 'A', 'Parapneumonic effusion', false, 0),
  ('5f888918-f2f0-5eae-b773-fa2f51fcbf42', '5270ab46-0044-5f82-9345-007f117dcd28', 'B', 'Tuberculous pleural effusion', true, 1),
  ('8bcf0c75-c9fe-5324-bfa3-8ca079eb45a2', '5270ab46-0044-5f82-9345-007f117dcd28', 'C', 'Heart failure', false, 2),
  ('6f1f84f5-35d9-5488-8207-37483790c6ba', '5270ab46-0044-5f82-9345-007f117dcd28', 'D', 'Mesothelioma', false, 3),
  ('0fd17334-b371-5586-8ad0-7c857524288d', '5270ab46-0044-5f82-9345-007f117dcd28', 'E', 'Pulmonary embolism', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7623d138-65d2-550c-a202-bdd10abcdc37', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 72 year old woman with known heart failure is reviewed. A chest X-ray shows bilateral pleural effusions. She is not unwell, has no fever and responds to increased diuretics. What is the SINGLE most appropriate management?', 'Bilateral effusions in known heart failure are usually transudates and resolve with diuretics. BTS guidance advises against diagnostic aspiration unless there are atypical features (unilateral, fever, pleuritic pain, or failure to respond to treatment). Unilateral effusions, or those that do not respond, need investigation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('962825bf-dc9f-593f-acbf-f72804e52981', '7623d138-65d2-550c-a202-bdd10abcdc37', 'A', 'Thoracic surgery', false, 0),
  ('95232fd8-ea96-5206-bba7-9b2d08042c52', '7623d138-65d2-550c-a202-bdd10abcdc37', 'B', 'Antibiotics', false, 1),
  ('3ddc4e93-4f6c-5dd6-9c72-e33433f58d1c', '7623d138-65d2-550c-a202-bdd10abcdc37', 'C', 'Immediate bilateral chest drains', false, 2),
  ('d4fe0049-0dd3-5b59-9bd0-8cdf2ff9c60b', '7623d138-65d2-550c-a202-bdd10abcdc37', 'D', 'Optimise heart failure treatment; diagnostic aspiration only if atypical features', true, 3),
  ('91ce2169-c556-51f5-b359-b9e939625a4d', '7623d138-65d2-550c-a202-bdd10abcdc37', 'E', 'Talc pleurodesis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3bf3fae5-6516-5a75-acb6-64766cce214b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 58 year old man has had a cough and weight loss and is diagnosed with non-small cell lung cancer (adenocarcinoma). Which tumour testing is MOST important to guide systemic therapy?', 'Advanced non-squamous NSCLC needs molecular testing (EGFR, ALK, ROS1, KRAS G12C, BRAF and others) and PD-L1 testing to guide targeted therapy (such as osimertinib for EGFR, alectinib for ALK) or immunotherapy (pembrolizumab). This has transformed outcomes. EGFR mutations are more common in non-smokers and in women of East Asian origin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6db85780-93a0-5551-84c2-ee050c44aa08', '3bf3fae5-6516-5a75-acb6-64766cce214b', 'A', 'Karyotype', false, 0),
  ('5a84f318-138e-5d45-b3ae-c4e4c33fb9c9', '3bf3fae5-6516-5a75-acb6-64766cce214b', 'B', 'CEA only', false, 1),
  ('3e705c10-f58d-5391-b83a-473da3f85a52', '3bf3fae5-6516-5a75-acb6-64766cce214b', 'C', 'Molecular testing for actionable mutations (EGFR, ALK, ROS1) and PD-L1 expression', true, 2),
  ('74b5e412-38ad-5082-85ab-ae5f874b79a0', '3bf3fae5-6516-5a75-acb6-64766cce214b', 'D', 'Serum calcium', false, 3),
  ('51f46630-b567-58d8-925d-dfb62a42c5e6', '3bf3fae5-6516-5a75-acb6-64766cce214b', 'E', 'HLA typing', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9b7e34f2-0593-572b-84df-2843caaa6452', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 34 year old woman has had progressive breathlessness. She has a firm, painless mass in her neck. Her chest X-ray shows a widened mediastinum with bilateral hilar lymphadenopathy. She reports pain in her lymph nodes after drinking alcohol. What is the SINGLE most appropriate investigation?', 'Mediastinal and hilar lymphadenopathy with a neck node and alcohol-induced node pain suggests Hodgkin lymphoma. An excision or core biopsy of an accessible node is needed for histology (Reed-Sternberg cells). Sarcoidosis and TB are differentials. PET-CT is used for staging.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b576cc7c-3d19-588c-9312-b4d84a7789c4', '9b7e34f2-0593-572b-84df-2843caaa6452', 'A', 'Lymph node excision biopsy', true, 0),
  ('d60b44b4-b426-5baf-8c6b-b88b763c8c99', '9b7e34f2-0593-572b-84df-2843caaa6452', 'B', 'Sputum culture', false, 1),
  ('f7155fc6-8b2d-534b-a41b-b415ab7e8d3d', '9b7e34f2-0593-572b-84df-2843caaa6452', 'C', 'ACE level', false, 2),
  ('d8ac053b-30ae-5732-b4fb-aa66dca4164f', '9b7e34f2-0593-572b-84df-2843caaa6452', 'D', 'Spirometry', false, 3),
  ('a3103f70-662c-56da-90db-cb87cefae0a3', '9b7e34f2-0593-572b-84df-2843caaa6452', 'E', 'Bronchoscopy only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('25ed42cf-1f98-5845-ab39-ca78fc6734de', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 75 year old woman has sudden onset left-sided chest pain and breathlessness for 1 hour on the orthopaedic ward. She also had one episode of haemoptysis. She had a total hip replacement for fractured neck of femur 3 days ago. Her temperature is 37.2°C, pulse rate 100 bpm, BP 132/78 mmHg, respiratory rate 22 breaths per minute and oxygen saturation 92% breathing air. Chest examination is normal. Which is the most appropriate diagnostic investigation?', 'Sudden pleuritic chest pain, breathlessness, haemoptysis and hypoxia 3 days after hip surgery strongly suggest pulmonary embolism. With a high clinical probability, CTPA is the definitive diagnostic investigation. A D-dimer is unhelpful after surgery because it will be raised anyway, and ECG, chest X-ray and ABG are supportive but not diagnostic.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
