  ('1a23f254-8134-5aea-b452-8a9bd05ebe71', '25ed42cf-1f98-5845-ab39-ca78fc6734de', 'A', 'Arterial blood gases', false, 0),
  ('29f7003d-5f24-5c36-a242-691930d7955f', '25ed42cf-1f98-5845-ab39-ca78fc6734de', 'B', 'Chest X-ray', false, 1),
  ('ba794e92-1f84-5595-b95b-6eca37bcc10c', '25ed42cf-1f98-5845-ab39-ca78fc6734de', 'C', 'CT pulmonary angiogram', true, 2),
  ('ff2acf54-e99f-5c71-b19b-c4eadd6af5aa', '25ed42cf-1f98-5845-ab39-ca78fc6734de', 'D', 'D-dimer', false, 3),
