insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a3566c3c-a87d-5feb-b04e-6b1ef16e18f4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 31 year old woman has increasing shortness of breath and left-sided pleuritic chest pain for 1 week. She smokes 10 cigarettes per day. She takes the combined oral contraceptive pill. Her temperature is 36.8°C, pulse rate 105 bpm, BP 105/80 mmHg, respiratory rate 22 breaths per minute and oxygen saturation 98% breathing air. Her chest is clear. Which is the most likely diagnosis?', 'Pleuritic chest pain, breathlessness and tachycardia in a woman who smokes and takes the COCP point to pulmonary embolism, despite normal saturations and a clear chest. Wells score assessment and CTPA (or D-dimer if PE is unlikely) are the next steps.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0c7abd97-34a5-5e5d-903b-0462861f3725', 'a3566c3c-a87d-5feb-b04e-6b1ef16e18f4', 'A', 'Bronchiectasis', false, 0),
  ('694d7cf5-b12e-5959-8935-f8fb457f0994', 'a3566c3c-a87d-5feb-b04e-6b1ef16e18f4', 'B', 'Lung cancer', false, 1),
  ('e3eacb57-62d5-5ffa-9311-fd4c021fd0f8', 'a3566c3c-a87d-5feb-b04e-6b1ef16e18f4', 'C', 'Pneumonia', false, 2),
  ('ffd70836-12a2-5df9-a01c-47cc799c68bd', 'a3566c3c-a87d-5feb-b04e-6b1ef16e18f4', 'D', 'Pulmonary embolism', true, 3),
  ('71f35500-9fea-55c1-92fe-8a88b6799e1a', 'a3566c3c-a87d-5feb-b04e-6b1ef16e18f4', 'E', 'Pulmonary tuberculosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bb76b2a4-6176-538f-8091-ab3d6fa53269', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 36 year old woman has left-sided chest pain on inspiration. whilst on the acute medical ward. She was admitted 3 days ago with fever, and worsening shortness of breath She has had 3 days of intravenous antibiotics. Her temperature is 38.0°C, pulse rate 102 bpm, BP 132/76 mmHg and oxygen saturation is 94% on 4 L/min oxygen with nasal prongs. She has dullness to percussion at the left base with bronchial breathing. Investigations: Chest X-ray on day 1 of admission: opacification in the left lower zone Chest X-ray on day 3 of admission: increased opacification with a fluid level to the left mid-zone Which is the most appropriate investigation at this stage?', 'Persistent fever and pleuritic pain with dullness at the base despite antibiotics for pneumonia suggest a parapneumonic effusion or empyema. Ultrasound-guided pleural aspiration is needed for pH, Gram stain and culture. A pH below 7.2 or pus indicates a chest drain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d39571ad-9ca4-572e-96b0-f6e719795541', 'bb76b2a4-6176-538f-8091-ab3d6fa53269', 'A', 'Blood cultures', false, 0),
  ('4e4101fc-7293-577b-93b4-1e3ce5e5e7e3', 'bb76b2a4-6176-538f-8091-ab3d6fa53269', 'B', 'Bronchoscopy', false, 1),
  ('83a3b671-85c6-5232-a399-5a255cda898f', 'bb76b2a4-6176-538f-8091-ab3d6fa53269', 'C', 'CT scan of chest', false, 2),
  ('9d1c7fea-9445-5540-9f55-09e0e2737cc5', 'bb76b2a4-6176-538f-8091-ab3d6fa53269', 'D', 'Induced sputum microscopy', false, 3),
  ('e2c58b98-819b-54f1-8153-a75603e9fc59', 'bb76b2a4-6176-538f-8091-ab3d6fa53269', 'E', 'Ultrasound guided pleural fluid aspiration', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a549f3a2-6b53-5c52-9600-b1cfb3c3558a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 65 year old man has a dry cough and progressive shortness of breath for 3 months. He is seen in the respiratory clinic. He has never smoked. His weight is stable. He has finger clubbing. His temperature is 36.5°C, pulse 70 bpm, BP 110/80 mmHg, respiratory rate 26 breaths per minute and oxygen saturation breathing air is 91%. He has bibasal fine end-inspiratory crackles. Investigation: Chest X-ray: reticulonodular shadowing at both bases Lung function tests: reduced vital capacity with an FEV1/FVC ratio of 85% Which is the most appropriate next investigation?', 'Progressive breathlessness, dry cough, clubbing, fine bibasal end-inspiratory crackles, reticular basal shadowing and a restrictive pattern suggest idiopathic pulmonary fibrosis. High-resolution CT is the key diagnostic investigation, typically showing a usual interstitial pneumonia pattern with honeycombing. Biopsy is rarely needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('96cf83e5-788f-58a5-9a35-b55c8a7a8fdf', 'a549f3a2-6b53-5c52-9600-b1cfb3c3558a', 'A', 'Broncho-alveolar lavage', false, 0),
  ('10c8e149-1784-5c51-b535-c480b402ca18', 'a549f3a2-6b53-5c52-9600-b1cfb3c3558a', 'B', 'Cardiopulmonary exercise test', false, 1),
  ('15ca7c30-5438-5ccc-8f89-c52baeb4116c', 'a549f3a2-6b53-5c52-9600-b1cfb3c3558a', 'C', 'Echocardiography', false, 2),
  ('4e469cb6-7c7e-5ed0-9b09-b21ba54f4856', 'a549f3a2-6b53-5c52-9600-b1cfb3c3558a', 'D', 'High resolution CT scan of chest', true, 3),
  ('9d8ccd1f-a7e1-512c-b0a3-c781005b4ea4', 'a549f3a2-6b53-5c52-9600-b1cfb3c3558a', 'E', 'Video-assisted thoracoscopic lung biopsy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('372ed841-d187-52a4-a1b4-c47074fd8715', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 72 year old woman has a worsening cough, fever, breathlessness and rigors for 6 days. She has left sided chest pain aggravated by breathing. Her temperature is 39.9°C, pulse rate 120 bpm, BP 90/50 mmHg and respiratory rate 30 breaths per minute. The percussion note is dull and there are no breath sounds over the lower left lung field. There are normal breath sounds otherwise throughout the lung fields. Which is the most likely finding on a chest X-ray?', 'A stony dull percussion note with absent breath sounds over the left lower zone points to a pleural effusion, here likely parapneumonic or empyema given the fever and sepsis. Consolidation would cause bronchial breathing and increased vocal resonance. Collapse causes tracheal deviation towards the affected side.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d830b4cd-5bf1-5d4c-b83c-e5c3c081d5a2', '372ed841-d187-52a4-a1b4-c47074fd8715', 'A', 'Enlarged hilar lymph nodes', false, 0),
  ('3e642e17-4dd6-595e-ba58-a4acc7b0dbc4', '372ed841-d187-52a4-a1b4-c47074fd8715', 'B', 'Lower lobe collapse', false, 1),
  ('4510e61e-749f-550b-b3b0-eeea575df0f6', '372ed841-d187-52a4-a1b4-c47074fd8715', 'C', 'Lower lobe consolidation', false, 2),
  ('4848a306-aeae-5f5e-a216-63a000a7e295', '372ed841-d187-52a4-a1b4-c47074fd8715', 'D', 'Lung mass', false, 3),
  ('4904ecad-c72b-5abf-aeb7-07649f7a62a1', '372ed841-d187-52a4-a1b4-c47074fd8715', 'E', 'Pleural effusion', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('698ab2bd-aa69-5955-9c45-e881a8822199', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 74 year old woman presents to her GP with a 2-week history of new right-sided headache, scalp tenderness when brushing her hair and pain in her jaw when chewing. She has no visual symptoms. Her ESR is 88 mm/hour and CRP 64 mg/L. What is the SINGLE most appropriate immediate management?', 'This is giant cell arteritis. To prevent irreversible vision loss, start high-dose oral prednisolone (40-60 mg) immediately and refer urgently to the specialist GCA pathway for temporal artery ultrasound or biopsy. Steroids should not be delayed for the biopsy, which stays positive for 1-2 weeks. IV methylprednisolone is for patients with visual symptoms. 15 mg is the starting dose for polymyalgia rheumatica.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('46b8f3c1-de41-512e-8873-66890ddd1de1', '698ab2bd-aa69-5955-9c45-e881a8822199', 'A', 'Start oral prednisolone 15 mg daily', false, 0),
  ('efad20d1-e9c6-5753-b11a-acac272fe5c8', '698ab2bd-aa69-5955-9c45-e881a8822199', 'B', 'Start high-dose oral prednisolone (40-60 mg) immediately', true, 1),
  ('be64574c-62bc-5920-8ec6-81c858e3c97e', '698ab2bd-aa69-5955-9c45-e881a8822199', 'C', 'Start oral naproxen', false, 2),
  ('62cc550c-f716-575e-9ef3-e2d30b40920b', '698ab2bd-aa69-5955-9c45-e881a8822199', 'D', 'Start IV methylprednisolone', false, 3),
  ('b6ce192b-a1c9-51fb-b4cc-dd784041e863', '698ab2bd-aa69-5955-9c45-e881a8822199', 'E', 'Wait for a temporal artery biopsy before starting steroids', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('be763f7d-1806-56d6-942f-2a7f666961d0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 45 year old woman has 4 months of pain and swelling in the small joints of both hands, with morning stiffness lasting 2 hours. Her MCP and PIP joints are swollen and tender symmetrically, and the DIP joints are spared. Rheumatoid factor and anti-CCP antibodies are positive. What is the SINGLE most appropriate first-line disease-modifying treatment?', 'This is rheumatoid arthritis: a symmetrical small-joint polyarthritis sparing the DIP joints, with prolonged morning stiffness and positive RF and anti-CCP (anti-CCP is the more specific). NICE recommends first-line conventional DMARD monotherapy with methotrexate (or leflunomide or sulfasalazine), started within 3 months, often with short-term bridging steroids. Methotrexate is given weekly with folic acid on a different day, and needs FBC and LFT monitoring. Biologics are used if conventional DMARDs fail.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d30bd64e-499a-55f3-9464-6795eedd674f', 'be763f7d-1806-56d6-942f-2a7f666961d0', 'A', 'Long-term oral prednisolone alone', false, 0),
  ('8cbea0d9-c7fd-5157-9579-3717f936cb44', 'be763f7d-1806-56d6-942f-2a7f666961d0', 'B', 'Infliximab as first-line', false, 1),
  ('c7ab7f91-5a83-5d26-8445-43429c4b1123', 'be763f7d-1806-56d6-942f-2a7f666961d0', 'C', 'Methotrexate', true, 2),
  ('9bdcb428-28bc-5769-a8a8-460765b1839e', 'be763f7d-1806-56d6-942f-2a7f666961d0', 'D', 'Hydroxychloroquine alone in all cases', false, 3),
  ('0e4d0b63-d612-5186-84c3-4bd819fd3903', 'be763f7d-1806-56d6-942f-2a7f666961d0', 'E', 'Allopurinol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0f63b31e-5689-502b-94a9-afefe4160962', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 72 year old man with a right knee replacement 4 years ago presents with 2 days of a hot, swollen, painful right knee and a fever of 38.6°C. He can barely move the knee. What is the SINGLE most appropriate next step?', 'A hot, swollen joint with fever is septic arthritis until proven otherwise. With a prosthetic joint, he needs urgent orthopaedic referral for aspiration (Gram stain, culture and crystals), which should be done before antibiotics if he is stable, followed by IV antibiotics. Staphylococcus aureus is the most common organism. A steroid injection is contraindicated when infection is possible.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('835b0b3b-4538-55fb-9dcf-6936cd30063b', '0f63b31e-5689-502b-94a9-afefe4160962', 'A', 'Start oral NSAID and review in 1 week', false, 0),
  ('f67b0c6f-55bb-57ea-908b-2920f2fe74cb', '0f63b31e-5689-502b-94a9-afefe4160962', 'B', 'Start oral colchicine', false, 1),
  ('87c8780d-84d4-52ce-a79d-57ad1ace29b9', '0f63b31e-5689-502b-94a9-afefe4160962', 'C', 'Intra-articular steroid injection', false, 2),
  ('109cf6a7-ab0e-5fe2-ad48-83afc32c57e2', '0f63b31e-5689-502b-94a9-afefe4160962', 'D', 'Urgent referral to orthopaedics for joint aspiration before antibiotics', true, 3),
  ('4827c5dc-dc61-57b9-89d6-55618809067b', '0f63b31e-5689-502b-94a9-afefe4160962', 'E', 'Plain X-ray only and discharge', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('41dcb9dc-f728-5e57-ba1a-121e4c92843c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 56 year old man wakes at night with sudden severe pain, swelling and redness of his right first metatarsophalangeal joint. He drinks beer most days and recently started bendroflumethiazide. He has no kidney disease or peptic ulcer history. What is the SINGLE most appropriate initial treatment?', 'Acute podagra in a man who drinks alcohol and takes a thiazide is typical of gout. NICE recommends an NSAID (with a PPI) or colchicine first-line, or a short course of oral steroids if these are contraindicated. Allopurinol (urate-lowering therapy) should be discussed and is usually started 2-4 weeks after the flare settles, with colchicine cover. Thiazides raise urate, so an alternative should be considered. Joint aspiration shows needle-shaped, negatively birefringent crystals.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('58718fe8-f9b6-5328-865b-2990d467223a', '41dcb9dc-f728-5e57-ba1a-121e4c92843c', 'A', 'Oral flucloxacillin', false, 0),
  ('f19a572d-adbd-5757-b8c3-1383f08e94bc', '41dcb9dc-f728-5e57-ba1a-121e4c92843c', 'B', 'Increase the bendroflumethiazide dose', false, 1),
  ('aa605a01-6bb8-598a-8b3d-df0467d37fb5', '41dcb9dc-f728-5e57-ba1a-121e4c92843c', 'C', 'Intra-articular steroid injection as the only option', false, 2),
  ('f8a1f31d-29ee-5d92-8882-55655f2fa3b3', '41dcb9dc-f728-5e57-ba1a-121e4c92843c', 'D', 'Oral naproxen with a PPI (or oral colchicine)', true, 3),
  ('4aae1618-9633-5207-84d8-e62df6e05923', '41dcb9dc-f728-5e57-ba1a-121e4c92843c', 'E', 'Start allopurinol immediately', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9511301c-67ea-5765-b532-96f1c994c321', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 24 year old man has 1 year of low back pain and stiffness that is worse in the morning, lasts over an hour and improves with exercise but not rest. He wakes in the second half of the night with pain. He had a painful red eye last year. Lumbar spine flexion is reduced (abnormal Schober''s test). What is the SINGLE most likely diagnosis?', 'Inflammatory back pain (onset under 40, insidious, improves with exercise and not rest, night pain, morning stiffness) with anterior uveitis suggests axial spondyloarthritis, associated with HLA-B27. MRI of the sacroiliac joints is the most sensitive imaging; plain X-rays may show sacroiliitis and later a ''bamboo spine''. Treatment is exercise, physiotherapy and NSAIDs, then anti-TNF biologics if needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f83d0fab-d6fc-5347-b118-63428dfee946', '9511301c-67ea-5765-b532-96f1c994c321', 'A', 'Mechanical back pain', false, 0),
  ('8078fef4-9c12-5674-99ad-25777652812b', '9511301c-67ea-5765-b532-96f1c994c321', 'B', 'Ankylosing spondylitis (axial spondyloarthritis)', true, 1),
  ('e1927d29-b6c4-5346-b0e2-070d578f87b9', '9511301c-67ea-5765-b532-96f1c994c321', 'C', 'Lumbar disc prolapse', false, 2),
  ('29683b71-3d34-5090-b12d-78fc9865a3f5', '9511301c-67ea-5765-b532-96f1c994c321', 'D', 'Spinal stenosis', false, 3),
  ('ee690856-45d1-5cac-8891-91d0e701d103', '9511301c-67ea-5765-b532-96f1c994c321', 'E', 'Rheumatoid arthritis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('53f12d49-ade9-5908-a86b-a43e9adf41bf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 28 year old woman has fatigue, painful joints in her hands, mouth ulcers and a red rash over her cheeks and the bridge of her nose that gets worse in sunlight. Urinalysis shows protein 2+. Her ANA is positive. What is the SINGLE most specific blood test for the most likely diagnosis?', 'A malar rash sparing the nasolabial folds, photosensitivity, oral ulcers, arthralgia and renal involvement in a young woman suggest systemic lupus erythematosus. ANA is very sensitive but not specific. Anti-dsDNA and anti-Smith are highly specific, and anti-dsDNA levels track disease activity, especially nephritis. Low complement (C3, C4) suggests active disease. Hydroxychloroquine is the cornerstone of treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f9f770f7-65ee-5b2f-90d2-996bb7869920', '53f12d49-ade9-5908-a86b-a43e9adf41bf', 'A', 'ANCA', false, 0),
  ('6136a573-0d1a-52c2-bc88-8243e71acbff', '53f12d49-ade9-5908-a86b-a43e9adf41bf', 'B', 'Rheumatoid factor', false, 1),
  ('60e0b0aa-ba6a-5853-a7ff-e45ed9f4a343', '53f12d49-ade9-5908-a86b-a43e9adf41bf', 'C', 'HLA-B27', false, 2),
  ('7e0b0981-5785-5a20-81dc-db492bc4ebde', '53f12d49-ade9-5908-a86b-a43e9adf41bf', 'D', 'Anti-CCP antibodies', false, 3),
  ('d208e256-e7a4-58d7-840a-6a5ec09381fd', '53f12d49-ade9-5908-a86b-a43e9adf41bf', 'E', 'Anti-double-stranded DNA antibodies', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2c457d38-1bd6-5fa2-9bb3-2c56e44e0604', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 69 year old woman has had pain and stiffness in both shoulders and hips for 6 weeks, worse in the morning and lasting more than 1 hour, which makes it hard to get out of bed. She has no headache, jaw claudication or visual symptoms. Her ESR is 64 mm/hour and CK is normal. What is the SINGLE most appropriate treatment?', 'Bilateral shoulder and hip girdle pain and stiffness in a person over 50, with raised inflammatory markers and a normal CK, is polymyalgia rheumatica. BSR recommends prednisolone 12.5-25 mg daily (commonly 15 mg), expecting a dramatic response within a week, then a slow taper over 1-2 years. Bone protection should be considered. Ask about giant cell arteritis symptoms, which need much higher doses. A normal CK helps exclude myositis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('58f58fca-7080-5321-a5c4-d5d7c5d32ee1', '2c457d38-1bd6-5fa2-9bb3-2c56e44e0604', 'A', 'Oral NSAIDs alone', false, 0),
  ('7bc67018-885a-52c5-848d-e71ae88af770', '2c457d38-1bd6-5fa2-9bb3-2c56e44e0604', 'B', 'Oral prednisolone 15 mg daily', true, 1),
  ('adc3405e-a7fd-5185-bcd7-8640563822c1', '2c457d38-1bd6-5fa2-9bb3-2c56e44e0604', 'C', 'IV methylprednisolone', false, 2),
  ('3e231f49-8796-5a4d-8353-e4477bf09258', '2c457d38-1bd6-5fa2-9bb3-2c56e44e0604', 'D', 'Oral methotrexate as first-line', false, 3),
  ('b3bb5d24-5e4f-53d2-b0a0-f80ec6f566b5', '2c457d38-1bd6-5fa2-9bb3-2c56e44e0604', 'E', 'Oral prednisolone 60 mg daily', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e2111c9f-7861-5447-9a31-801648b19bee', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 71 year old woman sustains a fracture of her left wrist after tripping on a kerb. A DEXA scan shows a T-score of -2.8 at the hip. Her adjusted calcium, vitamin D and kidney function are normal. She has no swallowing problems. What is the SINGLE most appropriate first-line treatment to reduce her fracture risk?', 'A fragility fracture with a T-score of -2.5 or lower confirms osteoporosis. First-line treatment is an oral bisphosphonate (alendronic acid 70 mg weekly), with calcium and vitamin D if intake is inadequate. It should be taken on an empty stomach with a full glass of water, staying upright for 30 minutes, because of the risk of oesophagitis. Osteonecrosis of the jaw and atypical femoral fractures are rare side effects, so a dental check is advised.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6c8a6df1-22be-524b-b639-602dd0cdb892', 'e2111c9f-7861-5447-9a31-801648b19bee', 'A', 'No treatment; she is low risk', false, 0),
  ('3433273b-e907-5e78-aba2-9ed4e8c03444', 'e2111c9f-7861-5447-9a31-801648b19bee', 'B', 'Oral alendronic acid weekly, with calcium and vitamin D supplements if needed', true, 1),
  ('8d5318d6-e96f-5497-b712-48f1a23318b3', 'e2111c9f-7861-5447-9a31-801648b19bee', 'C', 'Calcitonin', false, 2),
  ('3449100b-204a-5c2e-b74a-20928fe38417', 'e2111c9f-7861-5447-9a31-801648b19bee', 'D', 'Raloxifene as first-line', false, 3),
  ('528f9866-a342-5b3e-8056-b8438e3ef975', 'e2111c9f-7861-5447-9a31-801648b19bee', 'E', 'HRT as first-line at this age', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('68ae28ad-e3fa-5b4b-be9f-31a75f3040e9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 35 year old man has had swelling of his index finger (''sausage digit'') and painful heels for 3 months. He has psoriasis and nail pitting. X-ray shows erosions in the DIP joints with a ''pencil-in-cup'' appearance. What is the SINGLE most likely diagnosis?', 'Psoriatic arthritis is a seronegative spondyloarthritis that can cause DIP joint involvement, dactylitis, enthesitis, nail disease, asymmetric oligoarthritis or arthritis mutilans. X-ray shows ''pencil-in-cup'' erosions. NICE recommends annual screening of psoriasis patients for arthritis (PEST tool). Treatment is NSAIDs, DMARDs (methotrexate) and biologics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7a18df22-3db6-53d6-93a2-79237c96bd1c', '68ae28ad-e3fa-5b4b-be9f-31a75f3040e9', 'A', 'Psoriatic arthritis', true, 0),
  ('95efca6c-04d8-595f-ae4f-4df4986ca8da', '68ae28ad-e3fa-5b4b-be9f-31a75f3040e9', 'B', 'Rheumatoid arthritis', false, 1),
  ('ae6ef333-3eda-5303-a0c9-db4d7fe48341', '68ae28ad-e3fa-5b4b-be9f-31a75f3040e9', 'C', 'Osteoarthritis', false, 2),
  ('3d7c5f4b-8213-5c60-a8ab-6a3e91a56bc4', '68ae28ad-e3fa-5b4b-be9f-31a75f3040e9', 'D', 'Gout', false, 3),
  ('0741e2fc-f26c-52b2-8f0e-14cf7c703985', '68ae28ad-e3fa-5b4b-be9f-31a75f3040e9', 'E', 'Reactive arthritis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3b825981-67c6-560a-bbd5-781c5e76d4be', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 66 year old woman has had pain in her knees and the base of her thumbs for 2 years. The pain is worse with use and in the evening, with morning stiffness under 30 minutes. She has bony swellings of her DIP joints. What is the SINGLE most appropriate first-line management?', 'Osteoarthritis can be diagnosed clinically (age 45 or over, activity-related pain, morning stiffness under 30 minutes), without imaging. Heberden''s (DIP) and Bouchard''s (PIP) nodes are typical. NICE recommends therapeutic exercise and weight loss as core treatment, with topical NSAIDs for knee OA, then oral NSAIDs with a PPI for the shortest time. Arthroscopic washout is not recommended. Joint replacement is for severe symptoms.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e0a3e27a-9e1a-5b65-97d4-b1f348ca8970', '3b825981-67c6-560a-bbd5-781c5e76d4be', 'A', 'Arthroscopic washout', false, 0),
  ('7f038183-219b-531d-b86e-4abfd73d8019', '3b825981-67c6-560a-bbd5-781c5e76d4be', 'B', 'Oral methotrexate', false, 1),
  ('f3af007f-8d8c-5f8d-a0d2-0fe8599c09c8', '3b825981-67c6-560a-bbd5-781c5e76d4be', 'C', 'Long-term oral prednisolone', false, 2),
  ('fdaccfdc-e3df-55cb-87cf-a78bfa25a633', '3b825981-67c6-560a-bbd5-781c5e76d4be', 'D', 'Strong opioids', false, 3),
  ('ff3f0373-f372-54f3-a6a6-55d1b89ca9e1', '3b825981-67c6-560a-bbd5-781c5e76d4be', 'E', 'Exercise, weight loss and topical NSAIDs (for knees)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8a3eb2d5-4b40-552f-bcdc-280db36cba21', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 50 year old woman has had pain and stiffness in her hands for 3 months. Her fingers turn white, then blue, then red in the cold. She has tight, shiny skin on her fingers, telangiectasia on her face and difficulty swallowing. Anti-centromere antibodies are positive. What is the SINGLE most likely diagnosis?', 'Limited cutaneous systemic sclerosis (CREST: Calcinosis, Raynaud''s, oEsophageal dysmotility, Sclerodactyly, Telangiectasia) is associated with anti-centromere antibodies and carries a risk of pulmonary arterial hypertension. Diffuse systemic sclerosis (anti-Scl-70) affects the trunk and proximal limbs with early organ involvement (interstitial lung disease, scleroderma renal crisis). Calcium channel blockers (nifedipine) treat Raynaud''s.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1e025737-fdf5-5c56-ac0e-e5345ad9714a', '8a3eb2d5-4b40-552f-bcdc-280db36cba21', 'A', 'Primary Raynaud''s phenomenon', false, 0),
  ('31246245-0f29-5b67-83e6-f4a543c8ac6e', '8a3eb2d5-4b40-552f-bcdc-280db36cba21', 'B', 'Diffuse systemic sclerosis', false, 1),
  ('e2f8643c-1ca1-528c-9c3a-7db348525b9d', '8a3eb2d5-4b40-552f-bcdc-280db36cba21', 'C', 'Rheumatoid arthritis', false, 2),
  ('9da47e0b-e054-59d5-91fa-03634767e2a0', '8a3eb2d5-4b40-552f-bcdc-280db36cba21', 'D', 'Limited cutaneous systemic sclerosis (CREST)', true, 3),
  ('201a22aa-693f-5901-9fb4-c2e29739455f', '8a3eb2d5-4b40-552f-bcdc-280db36cba21', 'E', 'SLE', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e9a55051-7946-5a5c-80e2-24e60464aab2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 45 year old woman has dry eyes and mouth and parotid swelling. Anti-Ro and anti-La antibodies are positive. What is the SINGLE most important long-term complication to monitor for?', 'Primary Sjögren''s syndrome carries a much higher risk of non-Hodgkin lymphoma, especially MALT lymphoma of the parotid. Persistent parotid swelling, lymphadenopathy, purpura and low C4 are warning signs. Anti-Ro antibodies in pregnancy can cause congenital heart block and neonatal lupus. Management is artificial tears and saliva, pilocarpine and hydroxychloroquine for systemic features.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7a156345-f0a3-54b0-8be3-02ec67aa2c30', 'e9a55051-7946-5a5c-80e2-24e60464aab2', 'A', 'Glaucoma', false, 0),
  ('de09c763-3330-54ee-afa6-a53ebaf0655a', 'e9a55051-7946-5a5c-80e2-24e60464aab2', 'B', 'Bladder cancer', false, 1),
  ('3b7dbd1e-a626-5cda-a601-9d85bd443ce4', 'e9a55051-7946-5a5c-80e2-24e60464aab2', 'C', 'Hepatocellular carcinoma', false, 2),
  ('049eaf1a-f573-59f9-b2df-9322795a103c', 'e9a55051-7946-5a5c-80e2-24e60464aab2', 'D', 'Osteoporosis', false, 3),
  ('a3926a6e-647f-5b3e-a2e4-aa443cb18d3f', 'e9a55051-7946-5a5c-80e2-24e60464aab2', 'E', 'Non-Hodgkin lymphoma (MALT)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e36690bc-ce4e-558e-a56a-d9d408a16643', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 25 year old woman with SLE has had two miscarriages at 12 weeks and a DVT. Lupus anticoagulant and anticardiolipin antibodies are positive on two occasions 12 weeks apart. What is the SINGLE most likely diagnosis?', 'Antiphospholipid syndrome is arterial or venous thrombosis and/or pregnancy morbidity with persistent antiphospholipid antibodies (lupus anticoagulant, anticardiolipin, anti-beta2 glycoprotein I) on two occasions at least 12 weeks apart. It can be primary or secondary to SLE. Long-term warfarin (not DOACs) is used after thrombosis. In pregnancy, aspirin plus LMWH is used.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e6a809be-c6e1-549e-a4c8-c1b5ec9e30dd', 'e36690bc-ce4e-558e-a56a-d9d408a16643', 'A', 'Nephrotic syndrome', false, 0),
  ('7056ed5b-7e91-5e2a-b029-dd3db1821460', 'e36690bc-ce4e-558e-a56a-d9d408a16643', 'B', 'Factor V Leiden', false, 1),
  ('ac46ee9c-e387-5ba2-a448-699b2c6720d5', 'e36690bc-ce4e-558e-a56a-d9d408a16643', 'C', 'Protein C deficiency', false, 2),
  ('9c9e65a8-4fb7-5645-aa8b-7ae97b655e7e', 'e36690bc-ce4e-558e-a56a-d9d408a16643', 'D', 'Antiphospholipid syndrome', true, 3),
  ('827c1da7-4064-58cd-ba80-9641c0483ffe', 'e36690bc-ce4e-558e-a56a-d9d408a16643', 'E', 'Disseminated intravascular coagulation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('089708f0-047f-5c63-bca4-79bbf3c382ac', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 28 year old woman of Japanese origin has had fever, weight loss, headache and arm claudication. Her BP differs by 30 mmHg between her arms and there are bruits over the subclavian arteries. What is the SINGLE most likely diagnosis?', 'Takayasu arteritis is a large-vessel vasculitis of the aorta and its branches, typically in young Asian women under 40, causing claudication, absent pulses, BP differences between the arms and bruits (''pulseless disease''). In older people, large-vessel giant cell arteritis is more likely. Diagnosis is by MR or CT angiography and PET. Treatment is steroids and immunosuppression.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('08e3db70-d2a3-571f-aef2-6a4835f11393', '089708f0-047f-5c63-bca4-79bbf3c382ac', 'A', 'Kawasaki disease', false, 0),
  ('65a0488c-b340-56a7-85b3-b97585ad11dc', '089708f0-047f-5c63-bca4-79bbf3c382ac', 'B', 'Atherosclerosis', false, 1),
  ('ffcc1dd6-2265-5314-b166-931ac3f8f402', '089708f0-047f-5c63-bca4-79bbf3c382ac', 'C', 'Takayasu arteritis', true, 2),
  ('aa0eea4b-0cab-57f1-aee9-11f070cef9af', '089708f0-047f-5c63-bca4-79bbf3c382ac', 'D', 'Polyarteritis nodosa', false, 3),
  ('9423345a-b048-5fd9-a5c8-24d12b28ba7a', '089708f0-047f-5c63-bca4-79bbf3c382ac', 'E', 'Giant cell arteritis only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d40d9f4c-7420-5727-bb0b-5dbf8cea66c0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 48 year old man with hepatitis B has fever, weight loss, painful peripheral neuropathy (mononeuritis multiplex), testicular pain, livedo reticularis and new hypertension. ANCA is negative. Angiography shows renal and mesenteric microaneurysms. What is the SINGLE most likely diagnosis?', 'Polyarteritis nodosa is a medium-vessel necrotising vasculitis, often associated with hepatitis B. It causes mononeuritis multiplex, livedo reticularis, testicular pain, hypertension (renal artery involvement) and microaneurysms. It is typically ANCA negative and spares the lungs. Treatment is steroids and cyclophosphamide, with antivirals for hepatitis B.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ecf44304-acdf-5da6-8c76-55cac941625d', 'd40d9f4c-7420-5727-bb0b-5dbf8cea66c0', 'A', 'Takayasu arteritis', false, 0),
  ('1c0c1c29-80c5-568c-8a5a-862e9790058f', 'd40d9f4c-7420-5727-bb0b-5dbf8cea66c0', 'B', 'Polyarteritis nodosa', true, 1),
  ('c31b65c1-f1e1-5d7e-8882-cecd65877202', 'd40d9f4c-7420-5727-bb0b-5dbf8cea66c0', 'C', 'Microscopic polyangiitis', false, 2),
  ('ef055297-fd39-551d-8506-0676d33a079e', 'd40d9f4c-7420-5727-bb0b-5dbf8cea66c0', 'D', 'Granulomatosis with polyangiitis', false, 3),
  ('eef40c26-9c6f-5ff9-9f77-bd1216fdef03', 'd40d9f4c-7420-5727-bb0b-5dbf8cea66c0', 'E', 'Henoch-Schönlein purpura', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('22f6ceed-760e-5979-9a90-9d2c0193d55c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 36 year old woman with asthma has had nasal polyps and sinusitis, then developed eosinophilia, mononeuritis multiplex and a purpuric rash. p-ANCA (MPO) is positive. What is the SINGLE most likely diagnosis?', 'EGPA (formerly Churg-Strauss) is a small-vessel vasculitis with asthma, eosinophilia, sinusitis or polyps, neuropathy and cardiac involvement. About 40% are p-ANCA positive. Treatment is steroids, with immunosuppression (mepolizumab, cyclophosphamide) for severe disease. Cardiac involvement is the main cause of death.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('886b3754-d430-567b-9a3d-c66ab5e57c45', '22f6ceed-760e-5979-9a90-9d2c0193d55c', 'A', 'Granulomatosis with polyangiitis', false, 0),
  ('37595959-a277-583f-bfcd-25aaef6d575d', '22f6ceed-760e-5979-9a90-9d2c0193d55c', 'B', 'Microscopic polyangiitis', false, 1),
  ('e78d19cf-8651-5fc5-ae85-4bd7f06a6225', '22f6ceed-760e-5979-9a90-9d2c0193d55c', 'C', 'Polyarteritis nodosa', false, 2),
  ('c1565b99-8bc4-59ed-be05-2686aaea3066', '22f6ceed-760e-5979-9a90-9d2c0193d55c', 'D', 'Eosinophilic granulomatosis with polyangiitis', true, 3),
  ('a64e2512-ab7b-5c06-91ab-246612924248', '22f6ceed-760e-5979-9a90-9d2c0193d55c', 'E', 'Allergic bronchopulmonary aspergillosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fcdac0b7-e0e7-52b0-b39e-16e9d140fbc6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 30 year old man has had recurrent painful oral and genital ulcers. He now has a painful red eye with blurred vision (uveitis). He develops a pustule at the site of a blood test. What is the SINGLE most likely diagnosis?', 'Behçet''s disease is a variable-vessel vasculitis with recurrent oral and genital ulcers, uveitis, skin lesions (erythema nodosum, pathergy), arthritis, thrombosis and neurological involvement. It is common along the Silk Road (Turkey, Middle East, East Asia) and associated with HLA-B51. Treatment includes colchicine, steroids and immunosuppression.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6b0daa0c-023b-5355-836e-05324bdeb07c', 'fcdac0b7-e0e7-52b0-b39e-16e9d140fbc6', 'A', 'SLE', false, 0),
  ('67210f1c-f973-554e-af9b-46b435b9989f', 'fcdac0b7-e0e7-52b0-b39e-16e9d140fbc6', 'B', 'Behçet''s disease', true, 1),
  ('9ff81044-5658-5141-8314-7120f421a03d', 'fcdac0b7-e0e7-52b0-b39e-16e9d140fbc6', 'C', 'Herpes simplex', false, 2),
  ('1dcd585d-1e24-5ec1-98e7-51f52d3e4ef1', 'fcdac0b7-e0e7-52b0-b39e-16e9d140fbc6', 'D', 'Reactive arthritis', false, 3),
  ('45d66dbe-5300-5579-a261-39a9c3ac056d', 'fcdac0b7-e0e7-52b0-b39e-16e9d140fbc6', 'E', 'Crohn''s disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('47b5f8f1-0ac9-5d0a-a07e-86c229ed3bd9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 30 year old woman has had widespread chronic pain for 2 years, with fatigue, unrefreshing sleep and poor concentration. Examination is otherwise normal and her bloods (FBC, ESR, CRP, CK, TFT, calcium, vitamin D) are normal. What is the SINGLE most appropriate management?', 'Fibromyalgia (chronic primary pain) is diagnosed clinically with widespread pain for 3 months or more, fatigue, sleep disturbance and cognitive symptoms, with normal investigations. NICE recommends exercise programmes, psychological therapy (CBT, ACT), acupuncture and antidepressants (amitriptyline, duloxetine, SSRIs). Opioids, gabapentinoids and NSAIDs are not recommended for chronic primary pain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7dcb690b-a491-5cb5-b762-9e19ccdd153f', '47b5f8f1-0ac9-5d0a-a07e-86c229ed3bd9', 'A', 'Explanation, graded exercise and psychological approaches (CBT); consider antidepressants such as amitriptyline', true, 0),
  ('e83e0f89-e6b0-5267-ad99-e2170b562ad5', '47b5f8f1-0ac9-5d0a-a07e-86c229ed3bd9', 'B', 'Bed rest', false, 1),
  ('aecc8eff-3848-5315-aae7-9eef3cd0c836', '47b5f8f1-0ac9-5d0a-a07e-86c229ed3bd9', 'C', 'Methotrexate', false, 2),
  ('947a3dac-9fe0-53ad-9189-167a95997c5e', '47b5f8f1-0ac9-5d0a-a07e-86c229ed3bd9', 'D', 'Long-term opioids', false, 3),
  ('1d15307d-5283-5f77-984c-a5eb61752d50', '47b5f8f1-0ac9-5d0a-a07e-86c229ed3bd9', 'E', 'Oral prednisolone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d6b9e986-e0da-56ed-a8fd-7f61886eb621', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 70 year old man has had a hot, swollen left knee for 2 days. Aspiration shows rhomboid-shaped, weakly positively birefringent crystals. Knee X-ray shows chondrocalcinosis. What is the SINGLE most likely diagnosis?', 'Calcium pyrophosphate deposition (pseudogout) typically affects the knee or wrist of older people. Crystals are rhomboid and weakly positively birefringent, and X-ray shows chondrocalcinosis. Associations include haemochromatosis, hyperparathyroidism, hypomagnesaemia and hypophosphatasia (consider these in younger patients). Treatment is joint aspiration, intra-articular steroids, NSAIDs or colchicine. Septic arthritis must be excluded.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c29a1d88-2051-587e-a62b-fd03a9767ec6', 'd6b9e986-e0da-56ed-a8fd-7f61886eb621', 'A', 'Reactive arthritis', false, 0),
  ('3fc4039d-26b5-5297-b0ca-866dc05c2114', 'd6b9e986-e0da-56ed-a8fd-7f61886eb621', 'B', 'Osteoarthritis flare', false, 1),
  ('a5ffab82-6d8f-5c21-ba54-9a580c3addb1', 'd6b9e986-e0da-56ed-a8fd-7f61886eb621', 'C', 'Gout', false, 2),
  ('901fd1fa-ab48-578d-a2c8-5e1695d12d9c', 'd6b9e986-e0da-56ed-a8fd-7f61886eb621', 'D', 'Septic arthritis', false, 3),
  ('10e82339-a3c6-5510-8fcc-848a5b88790f', 'd6b9e986-e0da-56ed-a8fd-7f61886eb621', 'E', 'Acute calcium pyrophosphate crystal arthritis (pseudogout)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('403e95e6-f121-57cc-b1f0-60a866c0bbb1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 58 year old man has had recurrent gout flares (three this year) with a serum urate of 0.55 mmol/L and a tophus on his ear. His renal function is normal. What is the SINGLE most appropriate long-term management?', 'NICE recommends urate-lowering therapy (allopurinol or febuxostat, first-line) for people with recurrent flares, tophi, CKD, diuretic use or chronic gouty arthritis. The dose is titrated to a urate target below 0.36 mmol/L (below 0.30 if tophi are present). Prophylaxis with colchicine or a low-dose NSAID reduces flares in the early months. Allopurinol can be started during a flare.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('95861226-a629-54c7-8c15-fddb762adaa0', '403e95e6-f121-57cc-b1f0-60a866c0bbb1', 'A', 'Start febuxostat during the acute flare only', false, 0),
  ('c65be3b1-3452-5561-9028-e38184604876', '403e95e6-f121-57cc-b1f0-60a866c0bbb1', 'B', 'Start allopurinol, titrated to a serum urate target of below 0.36 mmol/L, with colchicine cover', true, 1),
  ('57697cfd-ac78-5100-b6bc-a926ed428dc7', '403e95e6-f121-57cc-b1f0-60a866c0bbb1', 'C', 'Long-term NSAIDs alone', false, 2),
  ('ecd680ce-946e-576f-890e-a6fa6a98756f', '403e95e6-f121-57cc-b1f0-60a866c0bbb1', 'D', 'Probenecid as first-line', false, 3),
  ('326f3b2f-3786-5f74-a8cd-095acc46e8fd', '403e95e6-f121-57cc-b1f0-60a866c0bbb1', 'E', 'No long-term treatment', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('46bde701-8df3-57ff-afe3-8e0abf5f07c7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 6 year old girl has had a swollen right knee and left ankle for 10 weeks, with morning stiffness. She is otherwise well. ANA is positive. What is the SINGLE most important screening to arrange?', 'Juvenile idiopathic arthritis is arthritis lasting more than 6 weeks before age 16. The oligoarticular type (4 or fewer joints) is commonest in young girls. ANA positivity increases the risk of chronic anterior uveitis, which is often asymptomatic and can cause blindness, so regular slit-lamp screening is essential. Treatment includes intra-articular steroids, NSAIDs, methotrexate and biologics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('75d16f9f-53aa-5b82-afe1-18d53ab77094', '46bde701-8df3-57ff-afe3-8e0abf5f07c7', 'A', 'Annual chest X-ray', false, 0),
  ('8a76a785-4ffc-540a-844e-90de469a98a3', '46bde701-8df3-57ff-afe3-8e0abf5f07c7', 'B', 'Echocardiogram', false, 1),
  ('2a3a106e-ef1e-5ea8-83ce-15733990e85f', '46bde701-8df3-57ff-afe3-8e0abf5f07c7', 'C', 'Regular ophthalmology screening (slit-lamp) for uveitis', true, 2),
  ('246a6e72-d507-583e-b127-65942ed7a1bc', '46bde701-8df3-57ff-afe3-8e0abf5f07c7', 'D', 'Colonoscopy', false, 3),
  ('9ea04078-add4-52b7-a74e-0ac76b00c4f2', '46bde701-8df3-57ff-afe3-8e0abf5f07c7', 'E', 'Renal biopsy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('58c09c8f-09ca-57fa-a3bb-1629551e82ac', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 55 year old woman with rheumatoid arthritis has dry eyes, splenomegaly and recurrent infections. Her neutrophil count is 0.8 x 10^9/L. What is the SINGLE most likely diagnosis?', 'Felty''s syndrome is rheumatoid arthritis plus splenomegaly plus neutropenia, usually in long-standing seropositive RA, with an increased risk of infection. Large granular lymphocyte leukaemia is a differential. Treatment is control of the RA (methotrexate, rituximab), and G-CSF for infections. Drug-induced neutropenia must be excluded.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6e1b0890-3f30-5893-9623-308c301afc3b', '58c09c8f-09ca-57fa-a3bb-1629551e82ac', 'A', 'Hodgkin lymphoma', false, 0),
  ('4939bb63-67c0-5b9d-b85b-620a8c6461a9', '58c09c8f-09ca-57fa-a3bb-1629551e82ac', 'B', 'SLE', false, 1),
  ('644d35ce-21d5-5e03-982c-71d2d17a8cf6', '58c09c8f-09ca-57fa-a3bb-1629551e82ac', 'C', 'Sjögren''s syndrome alone', false, 2),
  ('644daea3-3319-5520-b2eb-9a72303c188f', '58c09c8f-09ca-57fa-a3bb-1629551e82ac', 'D', 'Felty''s syndrome', true, 3),
  ('0e6c16f2-d7fb-5e3a-9911-dd5f73ecbe8d', '58c09c8f-09ca-57fa-a3bb-1629551e82ac', 'E', 'Methotrexate toxicity only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7eb5a981-e5c2-5a1b-8889-150228493d7d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 62 year old woman with rheumatoid arthritis is about to start anti-TNF therapy (adalimumab). Which screening test is MOST important before starting?', 'Anti-TNF drugs increase the risk of serious infections, especially reactivation of latent TB. Screening with an IGRA and/or chest X-ray, plus hepatitis B and C and HIV testing, is needed before starting. Live vaccines should be avoided during treatment. Patients should report signs of infection promptly.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
