  ('6593ea6c-d45f-509b-b8fc-75e44c3fcd65', '7eb5a981-e5c2-5a1b-8889-150228493d7d', 'A', 'Bone density scan', false, 0),
  ('62ee3a76-9746-5836-acb2-3d20faf17c0a', '7eb5a981-e5c2-5a1b-8889-150228493d7d', 'B', 'ECG', false, 1),
  ('ce9671d3-ad13-5dd2-9042-c0c0ee2e84ba', '7eb5a981-e5c2-5a1b-8889-150228493d7d', 'C', 'Colonoscopy', false, 2),
  ('82537823-0f5c-5341-a11b-a6dcfb767427', '7eb5a981-e5c2-5a1b-8889-150228493d7d', 'D', 'Thyroid function', false, 3),
  ('870ff66e-5193-5b19-9c08-2cc804ec5a4e', '7eb5a981-e5c2-5a1b-8889-150228493d7d', 'E', 'Screening for latent tuberculosis (IGRA and chest X-ray)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('06fc89d9-9477-556f-8e54-966fd6a2f0b5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 22 year old woman attends a sexual health clinic as her partner has been diagnosed with chlamydia. She has no symptoms. She is not pregnant and has no allergies. A swab is taken. What is the SINGLE most appropriate treatment?', 'BASHH recommends doxycycline 100 mg twice daily for 7 days as first-line for uncomplicated chlamydia; azithromycin is an alternative, for example in pregnancy. Sexual contacts should be treated empirically. She should avoid sex until she and her partner have completed treatment (and for 7 days after single-dose treatment) and be offered testing for other STIs. Ceftriaxone treats gonorrhoea.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('74e43472-0b45-5c7e-9bfa-d797b6099cbd', '06fc89d9-9477-556f-8e54-966fd6a2f0b5', 'A', 'Oral amoxicillin for 7 days', false, 0),
  ('de13f229-f1e5-509b-9812-6143178ba726', '06fc89d9-9477-556f-8e54-966fd6a2f0b5', 'B', 'IM ceftriaxone 1 g single dose', false, 1),
  ('52b13e7e-665b-5940-90fa-304f1e929a91', '06fc89d9-9477-556f-8e54-966fd6a2f0b5', 'C', 'Oral azithromycin 1 g single dose as first-line', false, 2),
  ('3ab6ffdd-ac44-5216-9c91-c0ca574c86cc', '06fc89d9-9477-556f-8e54-966fd6a2f0b5', 'D', 'Oral doxycycline 100 mg twice daily for 7 days', true, 3),
  ('3c117059-8b36-5077-a72c-c8cc6b9c9b6d', '06fc89d9-9477-556f-8e54-966fd6a2f0b5', 'E', 'Oral metronidazole for 7 days', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('077bd494-de1e-595a-8af1-e34c4a1ef4a4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 24 year old man has had dysuria and a purulent urethral discharge for 3 days after unprotected sex with a new partner. Gram stain of the discharge shows intracellular Gram-negative diplococci. What is the SINGLE most appropriate treatment?', 'Intracellular Gram-negative diplococci indicate Neisseria gonorrhoeae. BASHH recommends ceftriaxone 1 g IM as a single dose (ciprofloxacin only if sensitivity is known). Test of cure is needed because resistance is rising. Partners must be notified and tested. He should be tested for other STIs including chlamydia, HIV and syphilis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
