  ('5516f3a2-1698-57f7-a1ef-f9ee86ddbb0e', '077bd494-de1e-595a-8af1-e34c4a1ef4a4', 'A', 'IM ceftriaxone 1 g single dose', true, 0),
  ('bab8de2b-1a27-5562-b026-e1dbed8a0836', '077bd494-de1e-595a-8af1-e34c4a1ef4a4', 'B', 'Oral metronidazole', false, 1),
  ('1b2b2304-831d-511e-bed5-0214f38286c0', '077bd494-de1e-595a-8af1-e34c4a1ef4a4', 'C', 'Oral doxycycline for 7 days', false, 2),
  ('02d7e99b-9dfa-552d-9f9d-65b6546eb5dd', '077bd494-de1e-595a-8af1-e34c4a1ef4a4', 'D', 'Oral ciprofloxacin as first-line without sensitivities', false, 3),
  ('f9646f09-d55a-5277-936d-3923131677dd', '077bd494-de1e-595a-8af1-e34c4a1ef4a4', 'E', 'Oral amoxicillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8cfbf249-33fe-5197-8876-013e834bf741', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 25 year old woman has had painful blisters and ulcers on her vulva for 3 days, with dysuria, fever and tender inguinal nodes. This is her first episode. What is the SINGLE most appropriate treatment?', 'Multiple painful genital ulcers with systemic symptoms indicate primary genital herpes (usually HSV-2, increasingly HSV-1). A swab for PCR confirms it. Oral antivirals (aciclovir or valaciclovir) within 5 days of onset shorten symptoms. Supportive measures include saline bathing, analgesia and topical lidocaine. Urinary retention can occur.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
