  ('26b13f80-b22e-5690-90c3-1b5d47a4e28e', '8cfbf249-33fe-5197-8876-013e834bf741', 'A', 'Oral aciclovir for 5 days (plus saline bathing and analgesia)', true, 0),
  ('4a0229dc-15cb-5805-a7c5-2ad886377c16', '8cfbf249-33fe-5197-8876-013e834bf741', 'B', 'Oral metronidazole', false, 1),
  ('2696b8f6-63fb-5e0c-8fa7-da4e9be3a70e', '8cfbf249-33fe-5197-8876-013e834bf741', 'C', 'IM ceftriaxone', false, 2),
  ('3e1400ff-d799-52e5-ab5e-3bfb2f5af9ac', '8cfbf249-33fe-5197-8876-013e834bf741', 'D', 'Topical steroid', false, 3),
  ('65c9e949-d308-5598-ba9c-a1e17cc10341', '8cfbf249-33fe-5197-8876-013e834bf741', 'E', 'Benzathine penicillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('20ba3a94-7c65-5243-834d-f77f7b78c5fe', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 27 year old man has had several painless, flesh-coloured, cauliflower-like papules on the shaft of his penis for 2 months. What is the SINGLE most appropriate first-line treatment for multiple non-keratinised lesions?', 'Anogenital warts are caused by HPV types 6 and 11. Soft, non-keratinised warts respond to topical podophyllotoxin, and keratinised warts respond better to cryotherapy. Imiquimod is another option. Podophyllotoxin is contraindicated in pregnancy. Treatment is cosmetic, because the virus may persist.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
