  ('e3f034f5-cb15-5c76-b1b0-cd85cfe72d70', '20ba3a94-7c65-5243-834d-f77f7b78c5fe', 'A', 'Surgical excision for all lesions', false, 0),
  ('13f48792-00d6-53ef-b477-7092bb964406', '20ba3a94-7c65-5243-834d-f77f7b78c5fe', 'B', 'Topical podophyllotoxin', true, 1),
  ('5e558241-836e-56ec-aa07-4aeebb4a32fa', '20ba3a94-7c65-5243-834d-f77f7b78c5fe', 'C', 'Oral doxycycline', false, 2),
  ('938f95db-6631-5b77-a001-ec1d879c6873', '20ba3a94-7c65-5243-834d-f77f7b78c5fe', 'D', 'Oral aciclovir', false, 3),
  ('6beb1930-916d-5fcb-92b7-338f660cd81e', '20ba3a94-7c65-5243-834d-f77f7b78c5fe', 'E', 'IM benzathine penicillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0cfc8e66-3949-5b86-9bb0-608a2128d9c3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 22 year old woman has had a frothy, yellow-green, offensive vaginal discharge for a week, with vulval itch. Her cervix has a ''strawberry'' appearance. Microscopy shows motile flagellated organisms. What is the SINGLE most appropriate treatment?', 'Trichomonas vaginalis is a sexually transmitted flagellated protozoan. It causes a frothy, yellow-green discharge, pH over 4.5 and a strawberry cervix. It is treated with metronidazole (7 days or 2 g single dose), and current partners must be treated at the same time. Screening for other STIs is advised.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
