  ('1b83c850-7d19-593d-a7a1-f0b3daeea8f0', '0cfc8e66-3949-5b86-9bb0-608a2128d9c3', 'A', 'Oral fluconazole', false, 0),
  ('e916fb11-cf1f-5569-b560-43e9cd05c76a', '0cfc8e66-3949-5b86-9bb0-608a2128d9c3', 'B', 'No treatment for partners', false, 1),
  ('eb91e33f-6a95-5eb5-a7d6-85c7bac4573a', '0cfc8e66-3949-5b86-9bb0-608a2128d9c3', 'C', 'Clotrimazole pessary', false, 2),
  ('36760602-179a-50d6-8c37-a658ffca9009', '0cfc8e66-3949-5b86-9bb0-608a2128d9c3', 'D', 'Oral metronidazole for her and her sexual partner(s)', true, 3),
  ('0459c5a5-f170-5f78-bde5-f9a74baaa6a3', '0cfc8e66-3949-5b86-9bb0-608a2128d9c3', 'E', 'IM ceftriaxone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a21f7ecd-1fd1-5113-b477-577b9f8a96e4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 30 year old man has HIV diagnosed today. His CD4 count is 450 cells/mm3 and he feels well. What is the SINGLE most appropriate advice about antiretroviral therapy (ART)?', 'BHIVA recommends offering ART to everyone with HIV regardless of CD4 count, because early treatment improves outcomes. A sustained undetectable viral load also means HIV is not transmitted sexually (U=U). Baseline tests include viral load, resistance testing, HLA-B*5701 (before abacavir) and screening for coinfections.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ea885143-6216-58b7-92ad-bcaca4543b97', 'a21f7ecd-1fd1-5113-b477-577b9f8a96e4', 'A', 'Start ART only if he develops symptoms', false, 0),
  ('f735cf6e-87d1-5e58-94a6-9a1c0aec2a4e', 'a21f7ecd-1fd1-5113-b477-577b9f8a96e4', 'B', 'ART is not needed with a normal CD4 count', false, 1),
  ('07942183-fe87-56ab-ac3e-48a994ace1c4', 'a21f7ecd-1fd1-5113-b477-577b9f8a96e4', 'C', 'Start ART as soon as possible, regardless of CD4 count', true, 2),
  ('1a42f035-c9e5-5439-a7df-45d162983525', 'a21f7ecd-1fd1-5113-b477-577b9f8a96e4', 'D', 'Start co-trimoxazole only', false, 3),
  ('908a4b65-3b57-5211-9556-65ec5a25dd79', 'a21f7ecd-1fd1-5113-b477-577b9f8a96e4', 'E', 'Wait until his CD4 count falls below 200', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c00223cd-3571-5aff-b7cb-27e082af55d1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 28 year old man asks about HIV prevention. He is HIV negative and has condomless anal sex with male partners whose HIV status he does not know. What is the SINGLE most appropriate preventive option?', 'PrEP with tenofovir disoproxil/emtricitabine, taken daily or event-based for MSM, is highly effective at preventing HIV. It is available free through NHS sexual health services. Before starting and every 3 months, he needs HIV tests, kidney function and STI screening. Condoms are still advised to protect against other STIs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('583fd0a1-2da9-5a81-8143-cf261986e57c', 'c00223cd-3571-5aff-b7cb-27e082af55d1', 'A', 'HIV pre-exposure prophylaxis (PrEP) with tenofovir disoproxil/emtricitabine', true, 0),
  ('4ba0e1c7-69c2-56fb-bef5-97e5b9540bb9', 'c00223cd-3571-5aff-b7cb-27e082af55d1', 'B', 'Zidovudine monotherapy', false, 1),
  ('6da302ee-6fd6-525a-8052-50487b34ed21', 'c00223cd-3571-5aff-b7cb-27e082af55d1', 'C', 'Annual HIV testing only with no other measures', false, 2),
  ('df39acc8-a57c-5aff-9e51-4462f2a00a43', 'c00223cd-3571-5aff-b7cb-27e082af55d1', 'D', 'Post-exposure prophylaxis taken daily', false, 3),
  ('d0a0ad91-3e67-5e6c-985e-f7f2825c8f89', 'c00223cd-3571-5aff-b7cb-27e082af55d1', 'E', 'Co-trimoxazole', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3a72e705-fb9e-583c-bc9e-3902fa27722d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 26 year old man has had a painless swollen right knee and a painful, red left ankle for 1 week. He has dysuria and red eyes. Three weeks ago he had unprotected sex. Joint aspiration shows no crystals or bacteria. What is the SINGLE most likely diagnosis?', 'Reactive arthritis is a sterile asymmetrical oligoarthritis, often of the lower limbs, developing 1-4 weeks after a GI or genitourinary infection (Chlamydia, Salmonella, Shigella, Campylobacter). It can occur with urethritis and conjunctivitis. It is linked to HLA-B27. Treatment is NSAIDs and treating the triggering infection, with steroid injections for persistent joints.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('88bbb000-25a6-5e16-9944-2c3688710d5d', '3a72e705-fb9e-583c-bc9e-3902fa27722d', 'A', 'Disseminated gonococcal infection', false, 0),
  ('2acb29fb-6717-55f2-99f0-d6e5fe245116', '3a72e705-fb9e-583c-bc9e-3902fa27722d', 'B', 'Reactive arthritis', true, 1),
  ('dbad7ae5-257f-54b3-b4cb-bd711c233119', '3a72e705-fb9e-583c-bc9e-3902fa27722d', 'C', 'Gout', false, 2),
  ('0a870122-5236-57a2-ac43-9d273f4e71a3', '3a72e705-fb9e-583c-bc9e-3902fa27722d', 'D', 'Rheumatoid arthritis', false, 3),
  ('123af594-dadc-5ba2-ae06-d13e470a2da4', '3a72e705-fb9e-583c-bc9e-3902fa27722d', 'E', 'Septic arthritis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f8d4de8c-2bf6-5e6c-9a64-c8bc840a5210', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 22 year old woman is pregnant and her antenatal syphilis screen is positive. She has no allergies. What is the SINGLE most appropriate treatment?', 'Syphilis in pregnancy can cause miscarriage, stillbirth and congenital syphilis. The NHS antenatal screening programme tests all pregnant women. Benzathine benzylpenicillin is the treatment of choice in pregnancy. Doxycycline is contraindicated in pregnancy. The Jarisch-Herxheimer reaction (fever and myalgia after treatment) can cause preterm labour, so monitoring is advised. The baby needs assessment at birth.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dc073d36-e582-5b43-991c-a8ebcb8ed808', 'f8d4de8c-2bf6-5e6c-9a64-c8bc840a5210', 'A', 'Oral doxycycline', false, 0),
  ('19afc5d4-7c76-549d-b65e-3827f2ff1563', 'f8d4de8c-2bf6-5e6c-9a64-c8bc840a5210', 'B', 'No treatment until delivery', false, 1),
  ('dd5edd94-50d1-5d45-b3ca-8a53bb7c545a', 'f8d4de8c-2bf6-5e6c-9a64-c8bc840a5210', 'C', 'Oral metronidazole', false, 2),
  ('815a2227-b94a-501a-9c8f-1098c880dc82', 'f8d4de8c-2bf6-5e6c-9a64-c8bc840a5210', 'D', 'Oral azithromycin', false, 3),
  ('91fbf0f6-82f7-5985-bc1e-98790bcb290c', 'f8d4de8c-2bf6-5e6c-9a64-c8bc840a5210', 'E', 'IM benzathine benzylpenicillin', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('18d290dd-2cf5-5632-86b6-a6c8e2747dc0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 20 year old man has had unilateral testicular pain and swelling over 2 days with dysuria. He is sexually active with a new partner. His testis is tender, and lifting it relieves the pain (positive Prehn''s sign). The cremasteric reflex is present. What is the SINGLE most appropriate treatment?', 'Epididymo-orchitis in a sexually active man under 35 is usually caused by chlamydia or gonorrhoea. Empirical treatment covers both with ceftriaxone and doxycycline. In older men with likely enteric organisms (UTI), ofloxacin or levofloxacin is used. Torsion must be excluded: the onset of torsion is sudden and the cremasteric reflex is usually absent.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7de1b32b-55e9-59c4-a5b7-8508c280f00d', '18d290dd-2cf5-5632-86b6-a6c8e2747dc0', 'A', 'No treatment', false, 0),
  ('19b473c1-9892-5543-8e9a-ee4cd45ebefc', '18d290dd-2cf5-5632-86b6-a6c8e2747dc0', 'B', 'Urgent surgical exploration', false, 1),
  ('16d56ea0-72a8-5c97-81fc-cc0e316fd338', '18d290dd-2cf5-5632-86b6-a6c8e2747dc0', 'C', 'IM ceftriaxone 1 g plus oral doxycycline 100 mg twice daily for 10-14 days', true, 2),
  ('03be2d8a-e98f-55bb-8e1a-74e682911baf', '18d290dd-2cf5-5632-86b6-a6c8e2747dc0', 'D', 'Oral ciprofloxacin as first-line', false, 3),
  ('b5337165-5b67-56bc-a9eb-4f6d5c72625e', '18d290dd-2cf5-5632-86b6-a6c8e2747dc0', 'E', 'Oral nitrofurantoin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e3704840-6211-5c80-b80f-b2d4ce58e21e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 24 year old woman asks for chlamydia testing because she has no symptoms but has a new partner. What is the SINGLE most appropriate test?', 'NAAT (nucleic acid amplification testing) is the most sensitive test for chlamydia and gonorrhoea. In women, a self-taken or clinician-taken vulvovaginal swab is preferred, and in men, a first-void urine. Rectal and pharyngeal swabs are taken depending on sexual history. Testing should be at least 2 weeks after exposure to avoid false negatives.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ef64eec9-5c37-50fb-ade8-4b0df28aef2c', 'e3704840-6211-5c80-b80f-b2d4ce58e21e', 'A', 'Blood serology', false, 0),
  ('552b6c3e-724b-507a-9f9c-f9b453c55191', 'e3704840-6211-5c80-b80f-b2d4ce58e21e', 'B', 'Self-taken vulvovaginal swab for NAAT', true, 1),
  ('e3f5183f-d099-5506-941e-a260e333fb5f', 'e3704840-6211-5c80-b80f-b2d4ce58e21e', 'C', 'Endocervical swab for culture', false, 2),
  ('bf071258-cbf1-5247-995d-0ab2457c0231', 'e3704840-6211-5c80-b80f-b2d4ce58e21e', 'D', 'High vaginal swab for microscopy', false, 3),
  ('54e82a6b-bb31-59b3-ae42-bbb9597231e5', 'e3704840-6211-5c80-b80f-b2d4ce58e21e', 'E', 'Urine culture', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('09b2b9c9-095a-5cd5-b1ad-12a9a99c8509', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 19 year old woman is diagnosed with chlamydia. What is the SINGLE most appropriate partner notification action?', 'Partner notification for chlamydia covers partners from the past 6 months for asymptomatic women (4 weeks before symptom onset for symptomatic men), or the most recent partner if outside this window. Patient referral, provider referral or online services can be used. Re-testing is recommended at 3-6 months for under-25s because of the high reinfection rate.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b724ab0a-5510-58d4-8343-c209bd48b6a2', '09b2b9c9-095a-5cd5-b1ad-12a9a99c8509', 'A', 'Notify only her current partner', false, 0),
  ('c495d4b9-d18d-547b-a1f4-9537bc5d8a60', '09b2b9c9-095a-5cd5-b1ad-12a9a99c8509', 'B', 'Notify her parents', false, 1),
  ('002fd1a0-9356-5e83-98cd-cd033d860bd9', '09b2b9c9-095a-5cd5-b1ad-12a9a99c8509', 'C', 'Notify and offer testing and treatment to sexual partners from the past 6 months (or the last partner if longer)', true, 2),
  ('68385440-483a-5631-9eb5-c95f113f81f5', '09b2b9c9-095a-5cd5-b1ad-12a9a99c8509', 'D', 'Inform the police', false, 3),
  ('cb01f3b2-f6a1-5dd0-8f09-d2423933d9f6', '09b2b9c9-095a-5cd5-b1ad-12a9a99c8509', 'E', 'No notification needed', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bd5ba6c9-8391-534a-8975-0c978b3cd32d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 30 year old man who has sex with men attends the sexual health clinic for routine screening. He has no symptoms. Which sites should be swabbed for chlamydia and gonorrhoea NAAT?', 'MSM should be tested at all exposed sites: first-void urine, pharyngeal and rectal swabs for gonorrhoea and chlamydia NAAT, plus blood tests for HIV and syphilis, and hepatitis B (and vaccination), with hepatitis C if there are risk factors. Rectal and pharyngeal infections are often asymptomatic. Screening every 3 months is advised for higher-risk MSM.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2178c2b4-20a2-5c68-bc6d-8d43543cf198', 'bd5ba6c9-8391-534a-8975-0c978b3cd32d', 'A', 'Rectum only', false, 0),
  ('0a3ab8a7-a5aa-549b-b944-bc85a785125b', 'bd5ba6c9-8391-534a-8975-0c978b3cd32d', 'B', 'Blood test only', false, 1),
  ('f65fc4eb-d94d-5035-b571-8e1cee3b18a0', 'bd5ba6c9-8391-534a-8975-0c978b3cd32d', 'C', 'Urethral swab only', false, 2),
  ('569a65b4-5b70-5875-b2c2-3e6d3156bd75', 'bd5ba6c9-8391-534a-8975-0c978b3cd32d', 'D', 'Urine, pharynx and rectum', true, 3),
  ('0668a783-bad0-5c73-8e41-02befe73ddd9', 'bd5ba6c9-8391-534a-8975-0c978b3cd32d', 'E', 'Urine only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('486da407-98ba-518d-a5aa-e4b99e86b309', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 25 year old woman has had post-coital bleeding for 2 months. She is 25 and her last cervical screen was normal 1 year ago. Speculum examination shows a contact-bleeding cervix. What is the SINGLE most appropriate next step?', 'Post-coital bleeding needs a speculum examination and STI tests (chlamydia is a common cause of cervicitis). Ectropion is common. A suspicious cervix needs a suspected cancer referral for colposcopy, and persistent unexplained bleeding needs gynaecology referral. A recent normal screen does not exclude cancer, and cervical screening is not a diagnostic test.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5c15c289-c223-5aa2-8c94-a345a3788101', '486da407-98ba-518d-a5aa-e4b99e86b309', 'A', 'Test for chlamydia and gonorrhoea; refer for colposcopy if the cervix looks suspicious or bleeding persists', true, 0),
  ('32ee6155-940a-52d9-b8b9-75ab15963907', '486da407-98ba-518d-a5aa-e4b99e86b309', 'B', 'Repeat smear immediately', false, 1),
  ('3a421b90-9d4d-5f40-8f43-b813e4ba49a4', '486da407-98ba-518d-a5aa-e4b99e86b309', 'C', 'Reassure; she had a normal smear', false, 2),
  ('f4081749-857b-5ea3-92ab-c078dfc0c2b5', '486da407-98ba-518d-a5aa-e4b99e86b309', 'D', 'Start the COCP', false, 3),
  ('4da5050b-2288-5631-8f03-dea4fee3df45', '486da407-98ba-518d-a5aa-e4b99e86b309', 'E', 'Hysterectomy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('75ceb775-85ea-5844-b9bd-8f8c293faa5b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 23 year old woman has had a vaginal discharge with dysuria. Swabs show Mycoplasma genitalium on NAAT. Macrolide resistance testing is unavailable. What is the SINGLE most appropriate treatment?', 'Mycoplasma genitalium causes urethritis, cervicitis and PID, with rising antimicrobial resistance. BASHH recommends doxycycline for 7 days (to reduce organism load), followed by azithromycin if macrolide-sensitive, or moxifloxacin if resistant or unknown. Test of cure is recommended because of resistance.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
