  ('8b3db7c8-048b-5e5e-9ca1-7d8f6c7ebff6', '75ceb775-85ea-5844-b9bd-8f8c293faa5b', 'A', 'Ceftriaxone alone', false, 0),
  ('2c5b1923-38ca-55f8-b8be-42dfab30b9cd', '75ceb775-85ea-5844-b9bd-8f8c293faa5b', 'B', 'Metronidazole', false, 1),
  ('b5e1fddb-90a8-5746-8f65-8d2a8db9d04a', '75ceb775-85ea-5844-b9bd-8f8c293faa5b', 'C', 'No treatment', false, 2),
  ('22b11fb1-d1a4-5f61-8c46-f77c273f59a8', '75ceb775-85ea-5844-b9bd-8f8c293faa5b', 'D', 'Doxycycline for 7 days followed by moxifloxacin (or azithromycin if sensitive)', true, 3),
  ('ab489a73-72c6-57f1-a0de-5c12456037c5', '75ceb775-85ea-5844-b9bd-8f8c293faa5b', 'E', 'Fluconazole', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('975d5557-bab5-54ff-a3f9-8c5b34b8f1bf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 35 year old woman with HIV has a CD4 count of 180 cells/mm3. Which prophylaxis is MOST appropriate?', 'Co-trimoxazole is given when the CD4 count is under 200 (or under 14%) to prevent PCP, and also protects against toxoplasmosis. Prophylaxis against Mycobacterium avium complex (azithromycin) is considered under 50 if the patient is not starting ART promptly. Starting ART quickly is the most important intervention. Prophylaxis can stop when the CD4 count recovers on ART.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
