  ('70da8d22-4c39-5bc9-9deb-dcf6a3f3dc5b', '975d5557-bab5-54ff-a3f9-8c5b34b8f1bf', 'A', 'Fluconazole prophylaxis for all', false, 0),
  ('1c53f5f4-594a-5bc3-9d33-b019c92b88b0', '975d5557-bab5-54ff-a3f9-8c5b34b8f1bf', 'B', 'Isoniazid for everyone', false, 1),
  ('8add8847-31c6-53ca-a546-071468243fa4', '975d5557-bab5-54ff-a3f9-8c5b34b8f1bf', 'C', 'No prophylaxis needed', false, 2),
  ('b0bbbbe8-2954-5cac-957d-83947bdc1fb5', '975d5557-bab5-54ff-a3f9-8c5b34b8f1bf', 'D', 'Co-trimoxazole prophylaxis against Pneumocystis jirovecii pneumonia', true, 3),
  ('0bf7eee1-4b94-5a18-988d-eec7c23d6c2c', '975d5557-bab5-54ff-a3f9-8c5b34b8f1bf', 'E', 'Azithromycin weekly for MAC', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1cb555bc-4dea-596b-a6ff-4fcf5482752a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 28 year old man has had a painless genital ulcer for 1 week, followed by very large, painful, matted inguinal lymph nodes that are discharging (buboes). He has sex with men and travels frequently. What is the SINGLE most likely diagnosis?', 'LGV is caused by invasive Chlamydia trachomatis serovars L1-L3. It causes a transient painless ulcer, then painful inguinal lymphadenopathy (buboes) with possible sinus formation, or proctitis in MSM. Diagnosis is by chlamydia NAAT with LGV genotyping. Treatment is doxycycline for 21 days.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
