  ('390e7345-cd2a-5243-b9c1-276467b1a031', '1cb555bc-4dea-596b-a6ff-4fcf5482752a', 'A', 'Primary syphilis', false, 0),
  ('bca5d23d-0526-5419-80b6-6ddf87cf75a7', '1cb555bc-4dea-596b-a6ff-4fcf5482752a', 'B', 'Genital herpes', false, 1),
  ('38c35afe-e40b-53e7-821e-dbdf3c41768a', '1cb555bc-4dea-596b-a6ff-4fcf5482752a', 'C', 'Chancroid', false, 2),
  ('426429a4-c7b0-5ac0-8ae2-c74f326571e6', '1cb555bc-4dea-596b-a6ff-4fcf5482752a', 'D', 'Lymphogranuloma venereum (Chlamydia trachomatis serovars L1-L3)', true, 3),
  ('d4d5a159-c894-58ec-aeb6-caa0cea15a93', '1cb555bc-4dea-596b-a6ff-4fcf5482752a', 'E', 'Donovanosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('11b27269-709b-5caf-8d82-5bd065d7ed25', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 22 year old pregnant woman has a positive hepatitis B surface antigen at booking. Which intervention MOST reduces the risk of transmission to her baby?', 'All babies born to mothers with hepatitis B receive a hepatitis B vaccine within 24 hours of birth, plus hepatitis B immunoglobulin if the mother is highly infectious (HBeAg positive or high viral load). Antivirals (tenofovir) in the third trimester are given to mothers with a high viral load. Breastfeeding is not contraindicated and caesarean section is not needed for HBV alone. Babies are tested at 12 months.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e9070758-44f8-5998-9aeb-882b4578538c', '11b27269-709b-5caf-8d82-5bd065d7ed25', 'A', 'Termination of pregnancy', false, 0),
  ('4b2cadd1-b4d6-537d-a374-52afec567882', '11b27269-709b-5caf-8d82-5bd065d7ed25', 'B', 'Hepatitis B vaccine for the baby at birth (plus HBIG if indicated), with completion of the vaccine schedule', true, 1),
  ('2871f542-87d6-560c-abd8-5ba2be1c5a1b', '11b27269-709b-5caf-8d82-5bd065d7ed25', 'C', 'Avoid breastfeeding', false, 2),
  ('36be3eef-ab6b-5aa1-9944-25c9dca259c1', '11b27269-709b-5caf-8d82-5bd065d7ed25', 'D', 'No intervention needed', false, 3),
  ('97e26c1d-8aac-5285-a0e8-3c3288ed827b', '11b27269-709b-5caf-8d82-5bd065d7ed25', 'E', 'Caesarean section', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('493aeabf-8bea-5822-99fc-34c1748b6da2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 32 year old man is diagnosed with gonorrhoea. Which follow-up is MOST important?', 'BASHH recommends a test of cure for all gonorrhoea, because of rising antimicrobial resistance: culture at least 72 hours after treatment, or NAAT at least 2 weeks after. Partner notification and screening for other STIs (including HIV and syphilis) are also needed. Treatment failure should be reported to UKHSA.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3f494bbe-90d2-5034-ae4b-c3859c4380d3', '493aeabf-8bea-5822-99fc-34c1748b6da2', 'A', 'Test of cure (NAAT 2 weeks after treatment or culture at 72 hours)', true, 0),
  ('c7521bf0-b995-5c04-a910-a045dbe64605', '493aeabf-8bea-5822-99fc-34c1748b6da2', 'B', 'No follow-up needed', false, 1),
  ('7dba0a0d-6f82-5488-974b-62115b673519', '493aeabf-8bea-5822-99fc-34c1748b6da2', 'C', 'Chest X-ray', false, 2),
  ('a5218dc4-68d7-5981-a4fc-90268c94d8ee', '493aeabf-8bea-5822-99fc-34c1748b6da2', 'D', 'Repeat syphilis serology only', false, 3),
  ('bff51079-0298-537c-8281-0397f9799f45', '493aeabf-8bea-5822-99fc-34c1748b6da2', 'E', 'Repeat treatment monthly', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f239a491-779c-5369-923b-0c9e93ab3ffc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'Researchers identify 200 patients recently diagnosed with mesothelioma from hospital records and 400 people of similar age and sex without mesothelioma from the same area. All participants are interviewed about their past jobs to find out whether they were exposed to asbestos. The proportion exposed is compared between the two groups. Which study design is being described?', 'In a case-control study, participants are selected by outcome (people with the disease and people without it) and then looked at backwards for past exposures. It suits rare diseases such as mesothelioma and gives an odds ratio. Recall bias is a key weakness. A cohort study selects by exposure and follows people forward for outcomes. A cross-sectional study measures exposure and outcome at a single point in time.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('52b5d3e0-7b98-555b-977c-19cb97bbd703', 'f239a491-779c-5369-923b-0c9e93ab3ffc', 'A', 'Cross-sectional study', false, 0),
  ('467d499f-af6a-5678-85ea-fa20505bf6d5', 'f239a491-779c-5369-923b-0c9e93ab3ffc', 'B', 'Case-control study', true, 1),
  ('4360e9b9-4811-580c-9798-047f31e2de8e', 'f239a491-779c-5369-923b-0c9e93ab3ffc', 'C', 'Ecological study', false, 2),
  ('9c0db0cb-5172-517f-80c8-62482c8517e8', 'f239a491-779c-5369-923b-0c9e93ab3ffc', 'D', 'Prospective cohort study', false, 3),
  ('5d41d151-7f08-5810-9b1b-7b52555c49cf', 'f239a491-779c-5369-923b-0c9e93ab3ffc', 'E', 'Randomised controlled trial', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2597a27a-bbc6-5b2e-9504-017dfe40861c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A new blood test for a disease is evaluated in 1000 people. Of 100 people who have the disease, 80 test positive. Of 900 people without the disease, 855 test negative. What is the positive predictive value of the test?', 'True positives = 80, false positives = 900 - 855 = 45. PPV = TP / (TP + FP) = 80 / 125 = 64%. Sensitivity is 80/100 = 80%, specificity is 855/900 = 95%, and NPV is 855/(855 + 20) = 98%. PPV depends on prevalence: the same test gives a lower PPV when the disease is rarer.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e2a3691d-c30b-5ba0-acce-51f595f997e6', '2597a27a-bbc6-5b2e-9504-017dfe40861c', 'A', '36%', false, 0),
  ('a58ae34c-ed75-595f-b2b3-47241cae4629', '2597a27a-bbc6-5b2e-9504-017dfe40861c', 'B', '64%', true, 1),
  ('2c61e952-53dc-5638-a955-7313e5fa4579', '2597a27a-bbc6-5b2e-9504-017dfe40861c', 'C', '80%', false, 2),
  ('544ed658-8631-5b69-914f-3e159780c2de', '2597a27a-bbc6-5b2e-9504-017dfe40861c', 'D', '95%', false, 3),
  ('81101f59-cb3c-5320-9243-ead18f4fcb54', '2597a27a-bbc6-5b2e-9504-017dfe40861c', 'E', '98%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d8e563e7-5623-5a8b-babb-f364476ec3e1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'In a randomised controlled trial of a new drug for preventing stroke in high-risk patients, 20% of patients in the placebo group had a stroke over 5 years compared with 15% in the treatment group. How many patients need to be treated for 5 years to prevent one stroke?', 'Absolute risk reduction (ARR) = control event rate - experimental event rate = 20% - 15% = 5% (0.05). Number needed to treat (NNT) = 1 / ARR = 1 / 0.05 = 20. The relative risk reduction is 5/20 = 25%, which is a common distractor. Always state the time period with an NNT.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('54d0a87c-816d-5513-bc81-c80abd8303a7', 'd8e563e7-5623-5a8b-babb-f364476ec3e1', 'A', '5', false, 0),
  ('9ebe5550-5af6-5e94-8cf1-7961b0d46da5', 'd8e563e7-5623-5a8b-babb-f364476ec3e1', 'B', '10', false, 1),
  ('6c5f11c6-571f-59e6-89a7-04e1c39027fd', 'd8e563e7-5623-5a8b-babb-f364476ec3e1', 'C', '20', true, 2),
  ('f63269a6-34d4-5c72-8d33-9addc5c1afe5', 'd8e563e7-5623-5a8b-babb-f364476ec3e1', 'D', '25', false, 3),
  ('db781f49-4afd-5b3a-9827-f3ac09045c1d', 'd8e563e7-5623-5a8b-babb-f364476ec3e1', 'E', '50', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('58dc3e0e-4fdf-5f62-8835-2f9d1e0cc819', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A case-control study of smoking and bladder cancer finds that 60 of 100 cases smoked and 30 of 100 controls smoked. What is the odds ratio for smoking in cases compared with controls?', 'Odds of exposure in cases = 60/40 = 1.5. Odds of exposure in controls = 30/70 = 0.43. Odds ratio = 1.5 / 0.43 = 3.5 (or (60 x 70) / (40 x 30) = 4200/1200 = 3.5). The odds ratio is the measure of association in case-control studies. Relative risk is calculated from cohort studies and RCTs, where incidence can be measured.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4dc9656d-2b7e-565e-98bf-6b3daf89cde3', '58dc3e0e-4fdf-5f62-8835-2f9d1e0cc819', 'A', '0.29', false, 0),
  ('8dcd1ce7-8a9b-5d1f-a526-4da67a49348e', '58dc3e0e-4fdf-5f62-8835-2f9d1e0cc819', 'B', '1.5', false, 1),
  ('c950834f-d040-5b42-b986-c0b591732e26', '58dc3e0e-4fdf-5f62-8835-2f9d1e0cc819', 'C', '2.0', false, 2),
  ('5bbd7a41-d132-5e1a-be0d-5247ab8c96e3', '58dc3e0e-4fdf-5f62-8835-2f9d1e0cc819', 'D', '3.5', true, 3),
  ('83434a89-3735-5f91-b929-6a13098904a8', '58dc3e0e-4fdf-5f62-8835-2f9d1e0cc819', 'E', '6.0', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3990d07c-13ff-5eec-82e0-57ec9a46db80', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A new screening test for a cancer is introduced. Patients diagnosed through screening appear to survive longer from diagnosis than those diagnosed after symptoms, but the age at which they die is the same in both groups. Which bias BEST explains this finding?', 'Lead-time bias happens when screening detects a disease earlier, so survival from diagnosis looks longer even though death is not delayed. Length-time bias happens because screening picks up slow-growing, less aggressive tumours more often. Both make screening programmes look more effective than they are. RCTs measuring mortality are the best way to evaluate screening.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('26e4c104-967e-5079-837b-584096f053ef', '3990d07c-13ff-5eec-82e0-57ec9a46db80', 'A', 'Lead-time bias', true, 0),
  ('950b80b1-7597-532b-b07b-f3909f3470be', '3990d07c-13ff-5eec-82e0-57ec9a46db80', 'B', 'Observer bias', false, 1),
  ('52c63913-665f-5987-b66f-1a352b81d7c6', '3990d07c-13ff-5eec-82e0-57ec9a46db80', 'C', 'Recall bias', false, 2),
  ('8c7ff4f1-cfbc-5605-8eae-e34975bd5d48', '3990d07c-13ff-5eec-82e0-57ec9a46db80', 'D', 'Selection bias', false, 3),
  ('14ad108f-38bb-5799-b653-9c6054d3be7d', '3990d07c-13ff-5eec-82e0-57ec9a46db80', 'E', 'Publication bias', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5f910a7d-f66c-5e9f-a368-8095071af032', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'In a town of 50,000 people, 500 people are living with type 2 diabetes on 1 January. During that year, 100 new cases are diagnosed. Which of the following correctly describes these figures?', 'Prevalence is the proportion of a population with a condition at a point in time: 500/50,000 = 1%. Incidence is the number of new cases in a period divided by the population at risk: 100/49,500, about 0.2% per year. Prevalence is roughly incidence x average duration, so chronic diseases with long survival have high prevalence. Prevalence is useful for planning services and incidence for studying causes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('acbeb253-c1a3-5b6a-ae3b-915885c16daa', '5f910a7d-f66c-5e9f-a368-8095071af032', 'A', 'Incidence cannot be calculated from these data', false, 0),
  ('1c321dc5-f65d-50c3-840b-97696e12bd32', '5f910a7d-f66c-5e9f-a368-8095071af032', 'B', 'Point prevalence and incidence are both 1%', false, 1),
  ('cea61e13-a150-5afb-a84a-e77611d387f9', '5f910a7d-f66c-5e9f-a368-8095071af032', 'C', 'Point prevalence is 1% and annual incidence is about 0.2%', true, 2),
  ('8ca99904-2899-51b9-a991-db83e2b80c65', '5f910a7d-f66c-5e9f-a368-8095071af032', 'D', 'Point prevalence is 1.2% and annual incidence is 0.2%', false, 3),
  ('3064871e-7ad0-5865-8da7-c018b6aba35c', '5f910a7d-f66c-5e9f-a368-8095071af032', 'E', 'Point prevalence is 0.2% and annual incidence is 1%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ac093be5-c946-5069-8292-f275421695e4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A cohort study follows 1,000 smokers and 1,000 non-smokers for 10 years. Lung cancer develops in 40 smokers and 4 non-smokers. What is the relative risk of lung cancer in smokers compared with non-smokers?', 'Relative risk = incidence in exposed / incidence in unexposed = (40/1000) / (4/1000) = 0.04 / 0.004 = 10. Smokers are 10 times more likely to develop lung cancer over this period. The absolute risk difference is 4% - 0.4% = 3.6%, so the number needed to harm is 1/0.036, about 28. A relative risk above 1 means increased risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7ae797f9-a1a5-5a93-8d84-de1004eecfdd', 'ac093be5-c946-5069-8292-f275421695e4', 'A', '0.1', false, 0),
  ('276b46f0-042a-5083-8ff8-947be7fe36d7', 'ac093be5-c946-5069-8292-f275421695e4', 'B', '3.6', false, 1),
  ('c9aa62fc-00c1-5f23-8cfa-778fc2efd755', 'ac093be5-c946-5069-8292-f275421695e4', 'C', '4', false, 2),
  ('b170b60a-8f81-507f-971e-fa69b3e2c8f4', 'ac093be5-c946-5069-8292-f275421695e4', 'D', '10', true, 3),
  ('8c97c999-7fef-57ed-a46d-871a44af437c', 'ac093be5-c946-5069-8292-f275421695e4', 'E', '36', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2c4ad97e-a8c5-55ac-aa52-2e4b855aa49d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A researcher wants to know whether a new antihypertensive reduces stroke compared with the current standard drug. Patients are randomly allocated to each drug, and neither the patients nor the doctors assessing the outcome know which drug is given. What is the main purpose of the blinding?', 'Randomisation balances known and unknown confounders between the groups at baseline. Blinding patients and assessors reduces performance bias (different behaviour or care) and observer or detection bias (different outcome assessment). Allocation concealment prevents selection bias during recruitment. Generalisability (external validity) depends on how representative the participants are.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cfbea47e-4c95-5f4d-8890-1152a98a5861', '2c4ad97e-a8c5-55ac-aa52-2e4b855aa49d', 'A', 'To eliminate confounding at baseline', false, 0),
  ('fbc80b5b-1bb9-58dd-a103-70f9cb52d10e', '2c4ad97e-a8c5-55ac-aa52-2e4b855aa49d', 'B', 'To reduce observer (measurement) and performance bias', true, 1),
  ('df30dde1-33cf-5ca6-a6f8-dc62555fc16c', '2c4ad97e-a8c5-55ac-aa52-2e4b855aa49d', 'C', 'To increase the sample size', false, 2),
  ('bc96e5e7-f986-503e-a1b8-540dca333fdc', '2c4ad97e-a8c5-55ac-aa52-2e4b855aa49d', 'D', 'To make the results generalisable', false, 3),
  ('1d5f3da7-4927-5afd-96d8-ab4f3054c9f4', '2c4ad97e-a8c5-55ac-aa52-2e4b855aa49d', 'E', 'To reduce recall bias', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1ca56b3a-585a-5394-9d60-1994b0e29238', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A study of 1,000 people finds that people who carry a lighter are more likely to develop lung cancer. When smoking is accounted for, the association disappears. What does smoking represent in this study?', 'A confounder is associated with both the exposure (carrying a lighter) and the outcome (lung cancer), and is not on the causal pathway, creating a false association. Confounding is controlled by randomisation, restriction, matching, stratification and multivariable analysis. Bias is a systematic error in design or measurement. Random error is reduced by larger samples.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('531898ec-52a8-5802-9b82-dd3c488fe30a', '1ca56b3a-585a-5394-9d60-1994b0e29238', 'A', 'An outcome', false, 0),
  ('1fb560fa-7e21-5713-90d7-83e7170b1b4f', '1ca56b3a-585a-5394-9d60-1994b0e29238', 'B', 'Bias from blinding', false, 1),
  ('0fee8f5d-7476-5468-abe2-0d82ce27bb57', '1ca56b3a-585a-5394-9d60-1994b0e29238', 'C', 'Effect modifier', false, 2),
  ('44e3432c-a993-5cfa-9095-bd8b01fe17a0', '1ca56b3a-585a-5394-9d60-1994b0e29238', 'D', 'A confounder', true, 3),
  ('615cf1da-0ad9-5d20-8be0-c4c84a1dd46f', '1ca56b3a-585a-5394-9d60-1994b0e29238', 'E', 'A random error', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('48901840-a10d-5249-ab04-732cd4e27308', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A new test for a disease is used in a population where the disease prevalence falls from 20% to 2%. The sensitivity and specificity of the test remain unchanged. What happens to the positive predictive value (PPV)?', 'Sensitivity and specificity are properties of the test and do not change with prevalence. Predictive values depend on prevalence. As prevalence falls, PPV falls (more false positives relative to true positives) and NPV rises. This is why screening rare diseases in low-risk populations produces many false positives.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('169bf7e9-204d-58d9-b411-27d1fd6d2336', '48901840-a10d-5249-ab04-732cd4e27308', 'A', 'Sensitivity falls', false, 0),
  ('acb0ef04-87ca-536a-a93b-4266aa1ae550', '48901840-a10d-5249-ab04-732cd4e27308', 'B', 'Specificity rises', false, 1),
  ('082f3771-baa9-5f38-b80d-20579a377dd1', '48901840-a10d-5249-ab04-732cd4e27308', 'C', 'PPV rises', false, 2),
  ('b5c3715b-166c-5744-aa22-7dbfe6944f2a', '48901840-a10d-5249-ab04-732cd4e27308', 'D', 'PPV falls', true, 3),
  ('7676dfa3-ebbe-52ce-afac-6fc136b85050', '48901840-a10d-5249-ab04-732cd4e27308', 'E', 'PPV stays the same', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b515b4d7-5441-5b51-b6f7-f17e6f1cefcd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A new test is evaluated. Of 200 people with the disease, 180 test positive. Of 800 without the disease, 720 test negative. What is the specificity of the test?', 'Specificity = true negatives / all people without disease = 720/800 = 90%. Sensitivity = true positives / all people with disease = 180/200 = 90%. A highly sensitive test, when negative, rules the disease out (SnNout). A highly specific test, when positive, rules it in (SpPin).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4872dc8a-8ee2-52ee-a5f2-c8772874ceef', 'b515b4d7-5441-5b51-b6f7-f17e6f1cefcd', 'A', '60%', false, 0),
  ('1beba202-f605-5145-9582-4ab05ec93448', 'b515b4d7-5441-5b51-b6f7-f17e6f1cefcd', 'B', '72%', false, 1),
  ('36307e03-d799-582f-b82a-6cb461f4a366', 'b515b4d7-5441-5b51-b6f7-f17e6f1cefcd', 'C', '80%', false, 2),
  ('f14cd239-a908-5bcb-8436-020bfef2ae41', 'b515b4d7-5441-5b51-b6f7-f17e6f1cefcd', 'D', '90%', true, 3),
  ('f4d38020-a0d1-5a21-939d-ba375f2b8a0f', 'b515b4d7-5441-5b51-b6f7-f17e6f1cefcd', 'E', '95%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c981ad6b-6968-5656-b889-bf9a3906c046', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A trial reports a p-value of 0.03 for the difference in mortality between a new drug and placebo. What is the SINGLE most accurate interpretation?', 'A p-value is the probability of observing a result at least as extreme as this one if the null hypothesis is true. A p-value under 0.05 is conventionally ''statistically significant'', but it does not measure the size of the effect or its clinical importance. Confidence intervals give the precision and plausible range of the effect.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('932bc6f3-506b-52e5-bb27-0a11ca2861f3', 'c981ad6b-6968-5656-b889-bf9a3906c046', 'A', 'The drug reduces mortality by 3%', false, 0),
  ('f6bf80a5-7991-53e6-8107-5d9e86188a75', 'c981ad6b-6968-5656-b889-bf9a3906c046', 'B', 'The result is clinically important', false, 1),
  ('be531478-ca19-52ab-953f-3f56ef141033', 'c981ad6b-6968-5656-b889-bf9a3906c046', 'C', 'If there were truly no difference, a result this extreme or more would occur 3% of the time by chance', true, 2),
  ('bca989cb-f6a2-51de-8a27-8230040243f5', 'c981ad6b-6968-5656-b889-bf9a3906c046', 'D', 'There is a 3% chance the drug works', false, 3),
  ('6647b23a-c43d-552f-af2c-cf3dd19e26e0', 'c981ad6b-6968-5656-b889-bf9a3906c046', 'E', 'There is a 97% chance the drug works', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('22decfd9-fda0-54d4-9372-dba05ba9691c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A randomised trial concludes a new drug has no effect, but only 30 patients were included and the confidence interval is very wide. Which error is MOST likely?', 'A type II error (beta) is failing to detect a real difference (a false negative), usually because the sample size is too small (low power). Power = 1 - beta, conventionally 80% or more. A type I error (alpha) is a false positive, rejecting a true null hypothesis, conventionally set at 5%. Sample size calculations aim to ensure adequate power.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4349ee01-3ccf-5b37-b5e9-fc77e8031a86', '22decfd9-fda0-54d4-9372-dba05ba9691c', 'A', 'Recall bias', false, 0),
  ('6121d225-3432-5173-aa7d-714c5b650cd4', '22decfd9-fda0-54d4-9372-dba05ba9691c', 'B', 'Lead-time bias', false, 1),
  ('99324c9e-96dc-5206-889c-caa85f950e88', '22decfd9-fda0-54d4-9372-dba05ba9691c', 'C', 'Selection bias', false, 2),
  ('3af6c3f5-3707-5f06-bda3-0b268e5bbb22', '22decfd9-fda0-54d4-9372-dba05ba9691c', 'D', 'Type II error (false negative) due to low power', true, 3),
  ('f604bca0-d42b-5735-b479-b3761adc1388', '22decfd9-fda0-54d4-9372-dba05ba9691c', 'E', 'Type I error (false positive)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('606d1cee-406f-512a-b178-12a8615dfae1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'In a trial, some patients assigned to the new treatment stop taking it and some in the control group start it. Analysing patients in the groups they were originally randomised to, regardless of what they received, is called what?', 'Intention-to-treat analysis keeps patients in their randomised groups, preserving the benefits of randomisation and reflecting real-world effectiveness. Per-protocol analysis includes only those who followed the protocol and can introduce bias, although it is useful for assessing efficacy and in non-inferiority trials.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('18804c72-532c-5d7b-ba85-e57f0a7450cc', '606d1cee-406f-512a-b178-12a8615dfae1', 'A', 'Per-protocol analysis', false, 0),
  ('489d016c-403d-568f-be34-7d4a1b4ad0cc', '606d1cee-406f-512a-b178-12a8615dfae1', 'B', 'Meta-analysis', false, 1),
  ('0c289e80-d5e2-5e97-a2a1-d1e38f041016', '606d1cee-406f-512a-b178-12a8615dfae1', 'C', 'Intention-to-treat analysis', true, 2),
  ('61aa0dad-d6fb-59c3-8dd2-5a976b7acb91', '606d1cee-406f-512a-b178-12a8615dfae1', 'D', 'Subgroup analysis', false, 3),
  ('a7271bc2-4c3b-5a5b-811b-e6458c3c5a93', '606d1cee-406f-512a-b178-12a8615dfae1', 'E', 'Crossover analysis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f580dcfd-cd9a-5db5-be18-2d59abd73049', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A meta-analysis plots each study''s effect size against its sample size. The plot is asymmetrical, with small negative studies missing. What does this suggest?', 'A funnel plot asymmetry suggests publication bias, where small studies with negative or null results are less likely to be published. This can make the pooled estimate look better than it is. Prospective trial registration and searching grey literature reduce it. Heterogeneity between studies is assessed with I squared.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('26e7ec03-db8a-5572-a35c-2d503b0c2ba4', 'f580dcfd-cd9a-5db5-be18-2d59abd73049', 'A', 'Recall bias', false, 0),
  ('03942291-4b84-50fe-9a69-0e7dd282276b', 'f580dcfd-cd9a-5db5-be18-2d59abd73049', 'B', 'Confounding', false, 1),
  ('e428ad7e-f54a-550d-acbc-e85bf28a60f1', 'f580dcfd-cd9a-5db5-be18-2d59abd73049', 'C', 'Observer bias', false, 2),
  ('81049cf0-427c-524a-ae51-796042cd8b04', 'f580dcfd-cd9a-5db5-be18-2d59abd73049', 'D', 'Publication bias', true, 3),
  ('10248dfa-6336-54ae-9a0f-2021057887c6', 'f580dcfd-cd9a-5db5-be18-2d59abd73049', 'E', 'Lead-time bias', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('395b1c71-8f74-5436-b220-a5d2a141c5c2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'Which level of evidence is generally considered the HIGHEST in the hierarchy of evidence for treatment effectiveness?', 'The evidence hierarchy (highest to lowest) is: systematic reviews and meta-analyses of RCTs, individual RCTs, cohort studies, case-control studies, case series or reports, then expert opinion. Quality within each level matters, and GRADE assesses the certainty of evidence. Different study designs suit different questions, such as cohort studies for prognosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0a70e58a-d178-50aa-b88f-9eb2166e9788', '395b1c71-8f74-5436-b220-a5d2a141c5c2', 'A', 'Systematic review and meta-analysis of randomised controlled trials', true, 0),
  ('2dffd994-304a-5664-a0fd-2f9bef075b9e', '395b1c71-8f74-5436-b220-a5d2a141c5c2', 'B', 'Case-control study', false, 1),
  ('7496a746-bb37-59b5-8a73-1dc90f2dd20c', '395b1c71-8f74-5436-b220-a5d2a141c5c2', 'C', 'Case series', false, 2),
  ('9e4e8777-f31e-5ab2-aac0-897ea1c74a5f', '395b1c71-8f74-5436-b220-a5d2a141c5c2', 'D', 'Expert opinion', false, 3),
  ('8fa8a410-b466-54f4-ae05-97bb3c97b5bc', '395b1c71-8f74-5436-b220-a5d2a141c5c2', 'E', 'Cohort study', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4eba9e33-e1a1-5501-b381-c625704f9ecb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A clinical trial reports a relative risk reduction of 50% for a new drug, from 2% to 1%. What is the absolute risk reduction and number needed to treat?', 'ARR = 2% - 1% = 1% (0.01), so NNT = 1/0.01 = 100. The relative risk reduction (1%/2% = 50%) sounds impressive but hides the small absolute benefit when the baseline risk is low. Absolute measures (ARR, NNT) are more useful for shared decision-making.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2ea0cec4-7855-57ec-8e7e-37d508546b4d', '4eba9e33-e1a1-5501-b381-c625704f9ecb', 'A', 'ARR 0.5%, NNT 200', false, 0),
  ('a0cfac0f-fa6d-5cb6-8681-b763e059dbfd', '4eba9e33-e1a1-5501-b381-c625704f9ecb', 'B', 'ARR 1%, NNT 100', true, 1),
  ('86b27485-2aef-5f18-9006-0678eeef1422', '4eba9e33-e1a1-5501-b381-c625704f9ecb', 'C', 'ARR 2%, NNT 50', false, 2),
  ('3569e236-bc75-5837-8a36-ba7c5addcbc2', '4eba9e33-e1a1-5501-b381-c625704f9ecb', 'D', 'ARR 1%, NNT 50', false, 3),
  ('67c47087-20fb-57b2-82e0-a3835f6f6b2e', '4eba9e33-e1a1-5501-b381-c625704f9ecb', 'E', 'ARR 50%, NNT 2', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c962ad1e-7948-5881-8d30-02d468ee8fe4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'According to the Wilson and Jungner criteria, which of the following is a requirement for a screening programme?', 'Wilson and Jungner criteria include: an important health problem, a known natural history with a detectable latent stage, an acceptable and accurate test, effective treatment that works better when started early, agreed policy on whom to treat, a cost-effective programme and continuous case-finding. The UK National Screening Committee uses updated criteria.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('59ee68bf-6e16-516d-8538-f61c07b115b1', 'c962ad1e-7948-5881-8d30-02d468ee8fe4', 'A', 'The condition should be an important health problem with a recognisable latent or early asymptomatic stage', true, 0),
  ('c7518f1f-cc35-50fc-8262-face2554ea76', 'c962ad1e-7948-5881-8d30-02d468ee8fe4', 'B', 'The cost should not be considered', false, 1),
  ('39740e6b-e205-51e7-be99-670f79877766', 'c962ad1e-7948-5881-8d30-02d468ee8fe4', 'C', 'The test must be 100% sensitive', false, 2),
  ('64bbb8f8-efef-5020-8ce5-fbf7ba098399', 'c962ad1e-7948-5881-8d30-02d468ee8fe4', 'D', 'The disease must be rare', false, 3),
  ('d46e7ec4-09a0-5c75-ad7c-6da65c125db6', 'c962ad1e-7948-5881-8d30-02d468ee8fe4', 'E', 'The treatment must be experimental', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6b771f2e-d51d-5f86-870d-faa4c187d867', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A doctor is reviewing why most coronary heart disease events occur in people with moderate risk factors rather than high-risk individuals. Which public health approach does this support?', 'Rose''s prevention paradox says that a large number of people at small risk may give rise to more cases than a small number at high risk. Population strategies (salt reduction, smoking bans, sugar taxes) shift the whole distribution and prevent more disease overall, even though individual benefit is small. High-risk strategies target individuals (such as statins for high QRISK).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('77aecfba-2a02-523e-b842-8bfc861c5e74', '6b771f2e-d51d-5f86-870d-faa4c187d867', 'A', 'Screening only the elderly', false, 0),
  ('569e5e43-b009-5e7b-974c-9c3850b2d1b4', '6b771f2e-d51d-5f86-870d-faa4c187d867', 'B', 'A high-risk strategy only', false, 1),
  ('40b412b9-220a-5714-800f-1ec0db570469', '6b771f2e-d51d-5f86-870d-faa4c187d867', 'C', 'Tertiary prevention only', false, 2),
  ('845791ca-c43d-5e09-8a94-cad66a42f20c', '6b771f2e-d51d-5f86-870d-faa4c187d867', 'D', 'A population strategy (shifting the whole distribution of risk), as described by Geoffrey Rose', true, 3),
  ('63a33ecf-166f-5325-8b0d-a1110e8b21f0', '6b771f2e-d51d-5f86-870d-faa4c187d867', 'E', 'No preventive approach', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('61bf739c-2e82-5c60-b5b5-ec6ad1847d77', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'Which of the following is an example of secondary prevention?', 'Primary prevention stops disease before it occurs (vaccination, smoking cessation, seatbelts). Secondary prevention detects disease early, before symptoms, to change its course (screening such as cervical screening, mammography, BP checks). Tertiary prevention reduces the impact of established disease (cardiac rehabilitation, stroke rehabilitation, diabetic foot care).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4110d9f3-22c1-5a15-8384-1e5b42e38e3f', '61bf739c-2e82-5c60-b5b5-ec6ad1847d77', 'A', 'Cardiac rehabilitation after MI', false, 0),
  ('3c3c4f54-425c-5981-8f93-6b11eee2184a', '61bf739c-2e82-5c60-b5b5-ec6ad1847d77', 'B', 'Smoking cessation in a healthy adult', false, 1),
  ('8a0b823d-f727-59a0-ae82-cf51f333dabb', '61bf739c-2e82-5c60-b5b5-ec6ad1847d77', 'C', 'Cervical screening to detect pre-cancerous changes', true, 2),
  ('41f9ca76-8b4e-56da-97fa-ec5c11e753f0', '61bf739c-2e82-5c60-b5b5-ec6ad1847d77', 'D', 'HPV vaccination', false, 3),
  ('915a98e5-43b9-5af9-8412-c899708655ab', '61bf739c-2e82-5c60-b5b5-ec6ad1847d77', 'E', 'Seat belt laws', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('741cd2b4-ffe9-5766-b1dc-d24985efef1f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A researcher wants to compare the number of new cases of tuberculosis across different areas, accounting for different population sizes and age structures. What is the SINGLE most appropriate method?', 'Standardisation adjusts for differences in population age structure, allowing fair comparisons between areas or over time. Direct standardisation applies age-specific rates to a standard population. Indirect standardisation gives the standardised mortality ratio (SMR). Crude rates can be misleading when age structures differ.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cd05eb69-ec1f-5a75-a796-7f11d59cf6cc', '741cd2b4-ffe9-5766-b1dc-d24985efef1f', 'A', 'Case fatality rate only', false, 0),
  ('9a3d1802-df2a-5eef-9c31-4f001661a51c', '741cd2b4-ffe9-5766-b1dc-d24985efef1f', 'B', 'Odds ratio', false, 1),
  ('f821e2ba-22e5-5c3e-8028-f9f5bf35777c', '741cd2b4-ffe9-5766-b1dc-d24985efef1f', 'C', 'Age-standardised incidence rates', true, 2),
  ('60209cab-6f41-5ede-8fc1-befa16d63a42', '741cd2b4-ffe9-5766-b1dc-d24985efef1f', 'D', 'Absolute numbers of cases', false, 3),
  ('44704151-6e5e-5cb3-b52a-f71e7fe596fb', '741cd2b4-ffe9-5766-b1dc-d24985efef1f', 'E', 'Crude prevalence', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5abde404-e581-5f9e-b8ac-1cbc7478d598', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A screening test for prostate cancer is evaluated. Men diagnosed by screening appear to live longer from diagnosis, partly because screening picks up slow-growing tumours that would never have caused harm. What is this called?', 'Overdiagnosis is detecting disease that would never have caused symptoms or death in the person''s lifetime, leading to unnecessary treatment and harm. Length-time bias happens because screening preferentially detects slow-growing, less aggressive disease. These are key concerns in prostate (PSA) and breast screening, and are why informed choice is emphasised.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5268a5b6-beca-5e10-b5bd-00522042dd56', '5abde404-e581-5f9e-b8ac-1cbc7478d598', 'A', 'Overdiagnosis (and length-time bias)', true, 0),
  ('4ee85124-22f2-56d0-8cea-6a017372c165', '5abde404-e581-5f9e-b8ac-1cbc7478d598', 'B', 'Lead-time bias only', false, 1),
  ('90d6019e-f17a-5580-938f-3c5ad6813bc7', '5abde404-e581-5f9e-b8ac-1cbc7478d598', 'C', 'Recall bias', false, 2),
  ('36fe4f5c-8296-5bbe-8a03-d89ce6ea114b', '5abde404-e581-5f9e-b8ac-1cbc7478d598', 'D', 'Publication bias', false, 3),
  ('d658c88e-f292-5533-8c66-8cccc18365de', '5abde404-e581-5f9e-b8ac-1cbc7478d598', 'E', 'Attrition bias', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2d1ec9f8-8089-5a27-8cdb-16905319400c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A researcher measures smoking status and the presence of COPD in 2,000 adults at a single point in time using a questionnaire and spirometry. Which study design is this?', 'A cross-sectional study measures exposure and outcome at the same time in a defined population. It is useful for estimating prevalence and generating hypotheses, but cannot establish temporality or causation. Ecological studies compare groups or populations rather than individuals, and are vulnerable to the ecological fallacy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('64f0758b-f6ff-5cc1-9e46-c64c794a3044', '2d1ec9f8-8089-5a27-8cdb-16905319400c', 'A', 'Randomised controlled trial', false, 0),
  ('0b395abf-acf2-5231-a9ef-4e07c9409573', '2d1ec9f8-8089-5a27-8cdb-16905319400c', 'B', 'Ecological study', false, 1),
  ('26acddbe-c6bc-5791-91ba-890a068ae4f3', '2d1ec9f8-8089-5a27-8cdb-16905319400c', 'C', 'Case-control study', false, 2),
  ('db2c3350-0d0f-5f43-9a0e-19c0fe3044a2', '2d1ec9f8-8089-5a27-8cdb-16905319400c', 'D', 'Cross-sectional study', true, 3),
  ('f49013b8-ce0f-5a11-99e2-54a7942fc1b5', '2d1ec9f8-8089-5a27-8cdb-16905319400c', 'E', 'Cohort study', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('37d7e76f-5ed4-5e93-87aa-7a786ebdaafa', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'Which of the following BEST describes the Bradford Hill criteria?', 'The Bradford Hill criteria for causation include strength of association, consistency, specificity, temporality (exposure must come before outcome, the only essential criterion), biological gradient (dose-response), plausibility, coherence, experiment and analogy. They were used to establish the link between smoking and lung cancer.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('58359c36-917b-5e06-ab33-fc31825e773e', '37d7e76f-5ed4-5e93-87aa-7a786ebdaafa', 'A', 'Criteria for brain death', false, 0),
  ('df60ce77-dc0d-5234-bd23-e4ad73120117', '37d7e76f-5ed4-5e93-87aa-7a786ebdaafa', 'B', 'Criteria to assess whether an observed association is likely to be causal', true, 1),
  ('1e9f2ff9-fedb-5ec7-b4fb-7434edf753b4', '37d7e76f-5ed4-5e93-87aa-7a786ebdaafa', 'C', 'A scoring system for pneumonia severity', false, 2),
  ('cae4b77f-4d2d-51a4-9012-dd7d02117e60', '37d7e76f-5ed4-5e93-87aa-7a786ebdaafa', 'D', 'Criteria for diagnosing myocardial infarction', false, 3),
  ('be2bdd59-8c2c-5cbd-a548-5d1de7f40e1b', '37d7e76f-5ed4-5e93-87aa-7a786ebdaafa', 'E', 'Criteria for screening programmes', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('77ffc489-4f0c-51d7-99c9-03c6b14c130d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'In the UK, which body is responsible for assessing the clinical and cost-effectiveness of new drugs and issuing guidance for use in the NHS in England?', 'NICE assesses clinical and cost-effectiveness (using QALYs and cost per QALY thresholds, typically £20,000-£30,000) and issues guidelines and technology appraisals. The MHRA licenses medicines and monitors safety (Yellow Card scheme). The CQC regulates care providers. The GMC regulates doctors. UKHSA leads on infectious disease and health security.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a78c0c82-9811-520c-b81c-268be7ed9a25', '77ffc489-4f0c-51d7-99c9-03c6b14c130d', 'A', 'National Institute for Health and Care Excellence (NICE)', true, 0),
  ('8364290e-28d6-505d-8dbb-431b882dd42c', '77ffc489-4f0c-51d7-99c9-03c6b14c130d', 'B', 'General Medical Council', false, 1),
  ('8571800d-73dc-5708-9b03-21870641eb98', '77ffc489-4f0c-51d7-99c9-03c6b14c130d', 'C', 'MHRA', false, 2),
  ('38d5911a-748c-5300-b8e3-5b28247ca19c', '77ffc489-4f0c-51d7-99c9-03c6b14c130d', 'D', 'Care Quality Commission', false, 3),
  ('e43d4d8d-6954-5d23-acd6-3dee0948921e', '77ffc489-4f0c-51d7-99c9-03c6b14c130d', 'E', 'UK Health Security Agency', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f4bbd36b-8159-5715-99ef-d170a7dd47da', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A doctor suspects an adverse drug reaction to a newly licensed medicine marked with a black triangle. What is the SINGLE most appropriate action?', 'The Yellow Card scheme collects reports of suspected adverse drug reactions. For black triangle (intensively monitored) medicines, all suspected reactions should be reported, and for established drugs, serious reactions. Anyone, including patients, can report. This supports pharmacovigilance and drug safety.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5f27d72e-f496-5cde-b505-4f307fa441c0', 'f4bbd36b-8159-5715-99ef-d170a7dd47da', 'A', 'Report it to the GMC', false, 0),
  ('4a9a4041-d3bc-5486-9d6a-c4a8da75a778', 'f4bbd36b-8159-5715-99ef-d170a7dd47da', 'B', 'Report it via the MHRA Yellow Card scheme', true, 1),
  ('1b7291a0-ef29-5657-8bb5-3c1daf4ead6d', 'f4bbd36b-8159-5715-99ef-d170a7dd47da', 'C', 'Inform the drug company only', false, 2),
  ('37944670-b927-5d82-886a-ce01df7b351d', 'f4bbd36b-8159-5715-99ef-d170a7dd47da', 'D', 'Report it to the CQC', false, 3),
  ('28ca9d98-a0ed-5de8-96c5-c0b7fc09812a', 'f4bbd36b-8159-5715-99ef-d170a7dd47da', 'E', 'No reporting needed', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('19dd0e14-2f18-57e6-8cc6-7939530b0c0e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 74 year old man who smokes collapses at home with sudden severe abdominal pain radiating to his back. In the Emergency Department his heart rate is 128 beats/minute and blood pressure 78/44 mmHg. A pulsatile, expansile mass is felt in the epigastrium. What is the SINGLE most appropriate management?', 'Abdominal or back pain, shock and a pulsatile mass in an older male smoker is a ruptured abdominal aortic aneurysm. An unstable patient goes straight to theatre with the vascular team. Permissive hypotension (a target systolic BP of around 70-90 mmHg while conscious) reduces further bleeding. CT angiography is only for stable patients. In England, men are offered a one-off ultrasound screening for AAA at age 65.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('09e0ff0c-13b7-53e1-b0c2-3f56f9c73717', '19dd0e14-2f18-57e6-8cc6-7939530b0c0e', 'A', 'Admit to the ward for serial abdominal examination', false, 0),
  ('fa1f0cb0-5ff2-5413-815a-887f55d1d466', '19dd0e14-2f18-57e6-8cc6-7939530b0c0e', 'B', 'Immediate transfer to theatre or vascular surgery for emergency repair, with permissive hypotension', true, 1),
  ('91af228b-5bb0-5638-9ac4-5813b1f054e3', '19dd0e14-2f18-57e6-8cc6-7939530b0c0e', 'C', 'Aggressive IV fluids to achieve a systolic BP of 140 mmHg', false, 2),
  ('415dbc87-6cf5-5b8f-875f-02aa10e49338', '19dd0e14-2f18-57e6-8cc6-7939530b0c0e', 'D', 'Urgent upper GI endoscopy', false, 3),
  ('27bf3428-0ac0-513b-a720-2f768b500db7', '19dd0e14-2f18-57e6-8cc6-7939530b0c0e', 'E', 'CT angiogram before contacting the vascular team', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b7e8608a-f2a7-5941-8163-33d8882ae1ed', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 69 year old woman with atrial fibrillation who stopped her apixaban 2 weeks ago presents with 3 hours of sudden severe pain in her right leg. The leg is cold, pale and pulseless below the femoral pulse, with reduced sensation and weakness in the toes. What is the SINGLE most appropriate immediate management?', 'This is acute limb ischaemia, probably embolic given her untreated AF: the 6 Ps are pain, pallor, pulselessness, perishingly cold, paraesthesia and paralysis. Sensory or motor loss means the limb is threatened. Give IV heparin straight away and refer for urgent revascularisation (embolectomy, thrombolysis or bypass), ideally within 6 hours. Compression is contraindicated in arterial disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('821725d2-9285-5eed-8b16-2944b6d163a2', 'b7e8608a-f2a7-5941-8163-33d8882ae1ed', 'A', 'Oral aspirin and outpatient review', false, 0),
  ('12fa582f-5fe2-56cb-92fc-89b08d71831f', 'b7e8608a-f2a7-5941-8163-33d8882ae1ed', 'B', 'Arterial duplex in 1 week', false, 1),
  ('78ed5db9-d5e5-5927-bbb1-b4464748645f', 'b7e8608a-f2a7-5941-8163-33d8882ae1ed', 'C', 'Start a statin and supervised exercise programme', false, 2),
  ('8922a228-d16c-50ff-b5e0-0e928c1ad683', 'b7e8608a-f2a7-5941-8163-33d8882ae1ed', 'D', 'IV unfractionated heparin and urgent vascular surgery referral', true, 3),
  ('1ff33d4d-0607-581b-9817-cca7ce410359', 'b7e8608a-f2a7-5941-8163-33d8882ae1ed', 'E', 'Elevate the leg and apply compression stockings', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('539c7c35-7d08-5750-aaf2-845910b85b1d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 45 year old woman presents with a 2-day history of a painful, swollen left calf. She had a knee arthroscopy 2 weeks ago. The left calf is 4 cm larger in circumference than the right, with pitting oedema. Her two-level DVT Wells score is 3. She has no symptoms of pulmonary embolism. What is the SINGLE most appropriate next investigation?', 'With a DVT Wells score of 2 or more, DVT is ''likely''. NICE recommends a proximal leg vein ultrasound within 4 hours. If it cannot be done in that time, take a D-dimer and start interim anticoagulation (such as apixaban). A D-dimer alone is the first step only when the Wells score is 1 or less. A confirmed provoked DVT (such as after surgery) is usually treated with anticoagulation for 3 months.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('14a500bd-83f0-5c7e-8e9c-f525d4ca4eb6', '539c7c35-7d08-5750-aaf2-845910b85b1d', 'A', 'Proximal leg vein ultrasound within 4 hours', true, 0),
  ('cffc5450-64d8-5a12-8b75-bc2f8f1fef6b', '539c7c35-7d08-5750-aaf2-845910b85b1d', 'B', 'Venography', false, 1),
  ('406a779a-4339-5dbb-bc0b-486d7ce8d956', '539c7c35-7d08-5750-aaf2-845910b85b1d', 'C', 'No investigation; reassure', false, 2),
  ('a8c50448-7531-510d-a9fa-94b3a025255a', '539c7c35-7d08-5750-aaf2-845910b85b1d', 'D', 'CT pulmonary angiography', false, 3),
  ('28372b62-cc91-500d-a60a-a74cea1cd43c', '539c7c35-7d08-5750-aaf2-845910b85b1d', 'E', 'D-dimer only, and scan if positive', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('048897e7-f480-538d-ae7d-82a22b8e16fa', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 64 year old woman who had a hysterectomy 10 years ago presents with 2 days of colicky central abdominal pain, bilious vomiting, abdominal distension and no flatus for 24 hours. Bowel sounds are high-pitched and tinkling. An abdominal X-ray shows multiple central dilated loops of bowel with valvulae conniventes. What is the SINGLE most likely cause?', 'This is small bowel obstruction: central dilated loops with valvulae conniventes crossing the whole width of the bowel. In the UK, adhesions from previous surgery are the most common cause, followed by hernias. Initial management is ''drip and suck'' (IV fluids, NG decompression and analgesia) with a CT scan. Surgery is needed for strangulation or failure to resolve. Colorectal cancer is the most common cause of large bowel obstruction.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4a8e4eda-2295-50f8-8f5a-7be0697a4a4c', '048897e7-f480-538d-ae7d-82a22b8e16fa', 'A', 'Colorectal cancer', false, 0),
  ('a614b203-7a02-5aa9-93c0-5cf106a57126', '048897e7-f480-538d-ae7d-82a22b8e16fa', 'B', 'Adhesions', true, 1),
  ('dc9d5d86-587b-5474-9118-04cc1400af1a', '048897e7-f480-538d-ae7d-82a22b8e16fa', 'C', 'Diverticular stricture', false, 2),
  ('de4ce6a8-eedf-58e3-bdb5-bebdb527d253', '048897e7-f480-538d-ae7d-82a22b8e16fa', 'D', 'Sigmoid volvulus', false, 3),
  ('e8fa15cc-e802-58b4-a210-74ef3b28648b', '048897e7-f480-538d-ae7d-82a22b8e16fa', 'E', 'Gallstone ileus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('49913ffa-e2c4-5dad-8801-add5a2d503cd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 71 year old man is referred with tiredness. His blood tests show haemoglobin 88 g/L and MCV 69 fL. He has no change in bowel habit and no rectal bleeding. On examination there is a vague mass in the right iliac fossa. What is the SINGLE most likely diagnosis?', 'Right-sided colon cancers often present with iron deficiency anaemia and a right iliac fossa mass rather than a change in bowel habit or obstruction, because the right colon is wider and its contents are liquid. Left-sided and rectal cancers more often cause altered bowel habit, rectal bleeding, tenesmus or obstruction. He needs a suspected cancer referral for colonoscopy and CT staging.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5830fed2-64cd-5d02-9ff8-aeb54a34cbc8', '49913ffa-e2c4-5dad-8801-add5a2d503cd', 'A', 'Sigmoid carcinoma', false, 0),
  ('3ca1f865-0f1a-5331-b152-1d586f24db4a', '49913ffa-e2c4-5dad-8801-add5a2d503cd', 'B', 'Caecal (right-sided colon) carcinoma', true, 1),
  ('218edbfc-a2c6-526c-b6a2-3a89d3aaf9fe', '49913ffa-e2c4-5dad-8801-add5a2d503cd', 'C', 'Appendix mass', false, 2),
  ('b5b15213-f681-5466-88cf-38bcc0c11a23', '49913ffa-e2c4-5dad-8801-add5a2d503cd', 'D', 'Crohn''s disease', false, 3),
  ('6632677d-e5cc-52be-8bf0-30e208dd4d97', '49913ffa-e2c4-5dad-8801-add5a2d503cd', 'E', 'Rectal carcinoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0644b555-6c7e-5431-a392-9af6c20910f1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 58 year old man presents with 6 hours of a painful, tense, irreducible lump in his right groin with vomiting. The lump lies below and lateral to the pubic tubercle and is red and tender. What is the SINGLE most appropriate management?', 'A lump below and lateral to the pubic tubercle is a femoral hernia. A tender, irreducible, red hernia with vomiting suggests incarceration with strangulation and obstruction. It needs emergency surgery to save the bowel. Femoral hernias have a narrow neck and a high risk of strangulation, so even asymptomatic ones should be repaired urgently. Inguinal hernias lie above and medial to the pubic tubercle.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c867898e-8f3c-5999-a521-2afd14c8d447', '0644b555-6c7e-5431-a392-9af6c20910f1', 'A', 'Elective repair in 6 weeks', false, 0),
  ('64d02501-1d0a-532c-9275-fdf3646b7cf6', '0644b555-6c7e-5431-a392-9af6c20910f1', 'B', 'Emergency surgical repair', true, 1),
  ('b9282e64-d59c-5d83-8250-292464ab18fd', '0644b555-6c7e-5431-a392-9af6c20910f1', 'C', 'Supportive truss', false, 2),
  ('0b639068-58e3-5cb1-a59a-2dc6da73ae28', '0644b555-6c7e-5431-a392-9af6c20910f1', 'D', 'Ultrasound and outpatient review', false, 3),
  ('e0d2f50e-0e48-5507-9d47-1a8e5b8224c2', '0644b555-6c7e-5431-a392-9af6c20910f1', 'E', 'Attempt forceful manual reduction then discharge', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1d470782-6ebf-57b8-b7de-4e9a9b14cbac', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 32 year old man presents with 3 days of severe, throbbing pain next to his anus, worse on sitting. He has a fever of 38.2°C. On examination there is a tender, fluctuant, red swelling 2 cm from the anal verge. What is the SINGLE most appropriate management?', 'This is a perianal abscess. The definitive treatment is surgical incision and drainage, and antibiotics alone are not enough. Recurrent abscesses can indicate a fistula-in-ano or Crohn''s disease. Topical GTN is used for anal fissures (severe pain on defecation with bright red blood). Rubber band ligation is for haemorrhoids.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('238a56d8-695e-5c41-94eb-8d51b008bde8', '1d470782-6ebf-57b8-b7de-4e9a9b14cbac', 'A', 'Incision and drainage under anaesthesia', true, 0),
  ('58c874b1-1e42-5e43-890f-42826757825a', '1d470782-6ebf-57b8-b7de-4e9a9b14cbac', 'B', 'High-fibre diet and stool softeners', false, 1),
  ('27ca1df7-6031-5f97-87fa-38aef75d7961', '1d470782-6ebf-57b8-b7de-4e9a9b14cbac', 'C', 'Rubber band ligation', false, 2),
  ('83eae7d5-0ed9-5e4e-a007-2ea8cdd27798', '1d470782-6ebf-57b8-b7de-4e9a9b14cbac', 'D', 'Oral antibiotics alone', false, 3),
  ('d51208e9-1e68-5912-b8c1-ffb438380d5e', '1d470782-6ebf-57b8-b7de-4e9a9b14cbac', 'E', 'Topical glyceryl trinitrate', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3f65d13f-6194-5e8d-af6f-02323119be1e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 76 year old woman with atrial fibrillation who is not anticoagulated presents with severe central abdominal pain that started suddenly 6 hours ago. She is in agony, but her abdomen is soft and only mildly tender. Her lactate is 6.2 mmol/L. What is the SINGLE most likely diagnosis?', 'Pain out of proportion to the examination findings, in a patient with AF (an embolic source), with a raised lactate, is classic for acute mesenteric ischaemia, usually from an embolus to the superior mesenteric artery. CT angiography confirms it. Management is urgent resuscitation, anticoagulation and surgery or endovascular revascularisation, with resection of non-viable bowel. Mortality is high, so it must be recognised early.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('22cba8d1-4761-5d50-a705-8ff84d165b4d', '3f65d13f-6194-5e8d-af6f-02323119be1e', 'A', 'Acute pancreatitis', false, 0),
  ('f3b735cc-98d4-5945-a8b2-27cd373a7758', '3f65d13f-6194-5e8d-af6f-02323119be1e', 'B', 'Diverticulitis', false, 1),
  ('074ee033-d8b7-5a94-b622-1de9e4f1afc2', '3f65d13f-6194-5e8d-af6f-02323119be1e', 'C', 'Acute mesenteric ischaemia', true, 2),
  ('8e6acad2-a06f-5d15-a69c-0e99cd0dc295', '3f65d13f-6194-5e8d-af6f-02323119be1e', 'D', 'Irritable bowel syndrome', false, 3),
  ('fbc74c29-cc5f-52aa-a873-7489e559e3f2', '3f65d13f-6194-5e8d-af6f-02323119be1e', 'E', 'Biliary colic', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0abba8bf-e63e-5909-8008-fd8d59247457', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 78 year old man has had abdominal distension, absolute constipation and colicky pain for 2 days. An abdominal X-ray shows a massively dilated loop of large bowel in a ''coffee bean'' shape arising from the pelvis. He is not peritonitic. What is the SINGLE most appropriate initial management?', 'Sigmoid volvulus occurs in older, constipated, institutionalised or neurologically impaired patients and causes large bowel obstruction with a coffee bean sign. Initial treatment (without peritonitis or ischaemia) is endoscopic decompression with a flatus tube. Recurrence is common, so elective sigmoid colectomy is considered. Caecal volvulus usually needs surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b4b0f98b-4991-5cdd-b6b1-72f7c0990891', '0abba8bf-e63e-5909-8008-fd8d59247457', 'A', 'Flexible sigmoidoscopy and insertion of a flatus tube for decompression', true, 0),
  ('30e61c74-18bb-56e5-b6cf-0fae982fd7ea', '0abba8bf-e63e-5909-8008-fd8d59247457', 'B', 'Barium enema', false, 1),
  ('23a329f8-ea13-5324-af86-ef46b96bac4c', '0abba8bf-e63e-5909-8008-fd8d59247457', 'C', 'Emergency right hemicolectomy', false, 2),
  ('f202a281-f8a1-59ec-b0e2-e5958b11bb79', '0abba8bf-e63e-5909-8008-fd8d59247457', 'D', 'Laxatives and discharge', false, 3),
  ('1aef7192-1fb2-5901-b95e-3f1e92c28105', '0abba8bf-e63e-5909-8008-fd8d59247457', 'E', 'Colonoscopy in 6 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('19ccb03d-9ee2-5b51-9712-3905b506d007', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 80 year old woman has had abdominal distension and vomiting for 4 days. She has had altered bowel habit and weight loss over 3 months. An abdominal X-ray shows dilated large bowel with no gas in the rectum. Her caecum measures 11 cm and is tender. What is the SINGLE most likely cause?', 'Colorectal cancer is the commonest cause of large bowel obstruction in adults. With a competent ileocaecal valve, the caecum distends (closed-loop obstruction). A caecal diameter over 9-12 cm with tenderness risks perforation, so urgent CT and surgery or stenting are needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dbd2a4bd-8a99-5e20-b900-6b9069a687d2', '19ccb03d-9ee2-5b51-9712-3905b506d007', 'A', 'Pseudo-obstruction without cause', false, 0),
  ('057684fc-5408-5f8d-8f1f-776629342624', '19ccb03d-9ee2-5b51-9712-3905b506d007', 'B', 'Hernia', false, 1),
  ('a5a6b1e2-a533-5818-a7ae-7e61e8d78ac9', '19ccb03d-9ee2-5b51-9712-3905b506d007', 'C', 'Gallstone ileus', false, 2),
  ('05e5e9bf-f304-58b2-867b-50b98a2de6f6', '19ccb03d-9ee2-5b51-9712-3905b506d007', 'D', 'Obstructing colorectal cancer', true, 3),
  ('b03671fe-3141-5911-81e2-2929778ac1e5', '19ccb03d-9ee2-5b51-9712-3905b506d007', 'E', 'Adhesions', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6013a504-a5ed-573c-99c4-17c29f129803', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 70 year old man is 4 days after hip replacement surgery. He has abdominal distension and is not passing flatus. He has no peritonism. He is on opioids. An abdominal X-ray and CT show massive colonic dilatation without a mechanical obstruction point. What is the SINGLE most likely diagnosis?', 'Ogilvie''s syndrome is acute colonic dilatation without mechanical obstruction, often after surgery, illness or with medications (opioids, anticholinergics). Management is conservative: correct electrolytes (K, Mg, Ca), stop causative drugs, NG and rectal decompression. Neostigmine or colonoscopic decompression is used if needed, with surgery for perforation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('472d7274-2039-5d68-a4a3-25e8c12599fe', '6013a504-a5ed-573c-99c4-17c29f129803', 'A', 'Toxic megacolon', false, 0),
  ('f47cb1c2-4c88-55f1-bc25-de42769f6ca4', '6013a504-a5ed-573c-99c4-17c29f129803', 'B', 'Sigmoid volvulus', false, 1),
  ('24e5d4b6-93cc-5561-9fad-97b12ec4f2c7', '6013a504-a5ed-573c-99c4-17c29f129803', 'C', 'Colorectal cancer', false, 2),
  ('03efba00-316f-5713-945b-26fd5cf8f940', '6013a504-a5ed-573c-99c4-17c29f129803', 'D', 'Acute colonic pseudo-obstruction (Ogilvie''s syndrome)', true, 3),
  ('fcf3ff7f-3edf-58dc-9d4a-4612803eefba', '6013a504-a5ed-573c-99c4-17c29f129803', 'E', 'Small bowel obstruction', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5a63599e-aff5-5348-ad89-be91d678622f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 72 year old woman has had left iliac fossa pain for 2 days with a temperature of 37.8°C. She is tolerating fluids and is not systemically unwell. She has had similar episodes before. What is the SINGLE most appropriate management?', 'NICE recommends that uncomplicated acute diverticulitis in a well patient can be managed at home with analgesia (paracetamol, avoiding NSAIDs and opioids if possible) and a no-antibiotic approach unless systemically unwell, immunosuppressed or with significant comorbidity. Admission is needed for uncontrolled pain, inability to drink, or suspected complications (abscess, perforation).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f0417802-754e-5c68-8f6e-75a7d2ad4ecb', '5a63599e-aff5-5348-ad89-be91d678622f', 'A', 'Analgesia, clear fluids and safety-netting, with antibiotics only if systemically unwell or immunosuppressed', true, 0),
  ('4e25f2ca-dcc8-5224-8384-e91e2ad95a67', '5a63599e-aff5-5348-ad89-be91d678622f', 'B', 'Colonoscopy during the acute episode', false, 1),
  ('b2c5d041-f1c0-5472-9455-1ff90e45802d', '5a63599e-aff5-5348-ad89-be91d678622f', 'C', 'Hartmann''s procedure', false, 2),
  ('a0cee71a-2f63-5cdf-9731-b0b199ecb7ae', '5a63599e-aff5-5348-ad89-be91d678622f', 'D', 'IV antibiotics for all', false, 3),
  ('6ea42652-5254-56d0-974f-3a0c0527d6b9', '5a63599e-aff5-5348-ad89-be91d678622f', 'E', 'Admit for emergency surgery', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d98dfc29-d42d-521d-aca4-ca9462340c54', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 63 year old man has an inguinal swelling that appears on standing and coughing and disappears on lying down. It is above and medial to the pubic tubercle. When reduced and pressure is applied over the deep inguinal ring, the swelling does not reappear on coughing. What is the SINGLE most likely diagnosis?', 'An inguinal hernia lies above and medial to the pubic tubercle. An indirect hernia goes through the deep ring (lateral to the inferior epigastric vessels), so it is controlled by pressure over the deep ring. A direct hernia comes through Hesselbach''s triangle and is not controlled. Symptomatic hernias are repaired electively (mesh repair).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cf2fe032-b85f-5f4a-b274-f7c0819adf53', 'd98dfc29-d42d-521d-aca4-ca9462340c54', 'A', 'Saphena varix', false, 0),
  ('4b447a58-d940-5888-8505-6f26785e853d', 'd98dfc29-d42d-521d-aca4-ca9462340c54', 'B', 'Direct inguinal hernia', false, 1),
  ('361e8e68-c499-5491-9f8e-b962ffe4ead7', 'd98dfc29-d42d-521d-aca4-ca9462340c54', 'C', 'Hydrocele', false, 2),
  ('c1ef642b-6438-59dd-b196-24f51a8d4eca', 'd98dfc29-d42d-521d-aca4-ca9462340c54', 'D', 'Femoral hernia', false, 3),
  ('20e810cb-dec6-5d83-b9c8-ad5945705ad8', 'd98dfc29-d42d-521d-aca4-ca9462340c54', 'E', 'Indirect inguinal hernia', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d97745c8-121d-5f45-8303-d399b0ad5786', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 34 year old woman has a 1 cm painless lump in the anterior midline of her neck that moves up when she protrudes her tongue. What is the SINGLE most likely diagnosis?', 'A thyroglossal cyst is a remnant of the thyroglossal duct. It lies in the midline (often near the hyoid) and moves on swallowing and on tongue protrusion. Treatment is surgical excision with the central hyoid (Sistrunk''s procedure) to prevent recurrence. A branchial cyst lies lateral, anterior to sternocleidomastoid.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
