  ('dd308678-c5bd-5d12-92bf-ab351a985763', 'd97745c8-121d-5f45-8303-d399b0ad5786', 'A', 'Branchial cyst', false, 0),
  ('85654f90-df7d-5d54-976a-c72d361434d4', 'd97745c8-121d-5f45-8303-d399b0ad5786', 'B', 'Thyroid nodule', false, 1),
  ('a978e683-0f22-57b0-ba0d-33be0a7bf0f7', 'd97745c8-121d-5f45-8303-d399b0ad5786', 'C', 'Dermoid cyst', false, 2),
  ('b19d1eb7-bb2d-5c53-afd2-e94dd2b9619a', 'd97745c8-121d-5f45-8303-d399b0ad5786', 'D', 'Lymph node', false, 3),
  ('9ce9b551-5e46-5887-9007-8cf590fac20a', 'd97745c8-121d-5f45-8303-d399b0ad5786', 'E', 'Thyroglossal cyst', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c8950436-a690-5a46-a693-47c02a38c95f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 50 year old woman has a solitary 2 cm thyroid nodule. TFTs are normal. Ultrasound shows a hypoechoic solid nodule with microcalcification and irregular margins (U4). What is the SINGLE most appropriate next investigation?', 'Thyroid nodules are assessed with ultrasound (U1-U5 grading). Suspicious nodules (U3-U5) need ultrasound-guided FNA, and cytology is graded Thy1-Thy5. Papillary carcinoma is the commonest thyroid cancer, spreads by lymph nodes and has an excellent prognosis. Hyperthyroid patients with nodules need an isotope scan (hot nodules are rarely malignant).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
