  ('4d4faff8-2013-5dea-8e03-c7cda4c85ea8', 'c8950436-a690-5a46-a693-47c02a38c95f', 'A', 'Repeat ultrasound in 1 year', false, 0),
  ('9853fbec-56eb-535d-9640-d650859bfcdd', 'c8950436-a690-5a46-a693-47c02a38c95f', 'B', 'Thyroidectomy without cytology', false, 1),
  ('fb953ed3-043d-5e59-bd35-6dc9f5421a87', 'c8950436-a690-5a46-a693-47c02a38c95f', 'C', 'Ultrasound-guided fine needle aspiration cytology', true, 2),
  ('7e550ea3-459f-5a0a-a8d6-00d3b5cc75f4', 'c8950436-a690-5a46-a693-47c02a38c95f', 'D', 'Radioactive iodine scan', false, 3),
  ('8ecbb0e0-c7ea-5a11-8bd0-03e115c5cb0e', 'c8950436-a690-5a46-a693-47c02a38c95f', 'E', 'CT neck', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9c690a85-b750-5efb-8747-20f6135dd77b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 55 year old woman had a total thyroidectomy yesterday. She now has perioral tingling and cramps in her hands. Tapping in front of her ear causes twitching of her facial muscles. What is the SINGLE most appropriate investigation?', 'Hypocalcaemia after thyroidectomy is common, from damage to or removal of the parathyroid glands. It causes perioral paraesthesia, carpopedal spasm, Chvostek''s sign and Trousseau''s sign, and prolonged QT. Severe or symptomatic cases need IV calcium gluconate, and milder cases oral calcium and vitamin D. Recurrent laryngeal nerve injury is another complication, causing hoarseness.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
