  ('62cf9408-1f88-51b1-8733-f38b66d05a68', '9c690a85-b750-5efb-8747-20f6135dd77b', 'A', 'Serum sodium', false, 0),
  ('9dd07deb-5672-59ff-b321-ed35862db5d9', '9c690a85-b750-5efb-8747-20f6135dd77b', 'B', 'Serum magnesium alone', false, 1),
  ('6b9f8589-9e0b-59f7-99fb-11c4e76611b9', '9c690a85-b750-5efb-8747-20f6135dd77b', 'C', 'ECG only', false, 2),
  ('5b915d67-79a1-56ee-8e13-f9d6e1b63316', '9c690a85-b750-5efb-8747-20f6135dd77b', 'D', 'Serum calcium', true, 3),
  ('3e588e07-34f0-50d7-abb9-ea82bb3a16e3', '9c690a85-b750-5efb-8747-20f6135dd77b', 'E', 'Thyroid function tests', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8df24430-11d2-5ad7-af14-9d2b99b60653', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 26 year old man has had a painful, discharging lump at the top of his natal cleft for 2 weeks. He has a hairy back and a sedentary job. There are small midline pits in the natal cleft. What is the SINGLE most likely diagnosis?', 'A pilonidal sinus forms when hair becomes embedded in the natal cleft, typically in young hairy men who sit a lot, causing midline pits, abscesses and chronic discharge. An acute abscess is incised and drained off the midline. Chronic disease needs excision with off-midline closure.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6bbed1e4-3133-5547-a28b-aa3b240e29e2', '8df24430-11d2-5ad7-af14-9d2b99b60653', 'A', 'Hidradenitis suppurativa', false, 0),
  ('bccb5fd4-25b9-5324-aa34-0a918e3ef25b', '8df24430-11d2-5ad7-af14-9d2b99b60653', 'B', 'Anal fistula', false, 1),
  ('11c2d7ed-df2e-5b8c-992f-221900d0b326', '8df24430-11d2-5ad7-af14-9d2b99b60653', 'C', 'Pilonidal sinus/abscess', true, 2),
  ('7281cb9a-8362-53dd-a5ad-7c72e58d0a35', '8df24430-11d2-5ad7-af14-9d2b99b60653', 'D', 'Sebaceous cyst', false, 3),
  ('2a5d72b6-5e8e-5f7b-9d6e-ab441c86d13e', '8df24430-11d2-5ad7-af14-9d2b99b60653', 'E', 'Perianal abscess', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('68471fda-6419-5bc2-a37c-389a41bbf85f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 35 year old woman has had severe pain on opening her bowels, like passing glass, with a streak of bright red blood on the paper for 3 weeks. She is constipated. Examination shows a tear in the posterior midline of the anal canal. What is the SINGLE most appropriate initial management?', 'An acute anal fissure (less than 6 weeks) is usually posterior midline. Management is softening stools (fibre, fluids, bulk-forming laxatives), sitz baths and topical analgesia. Topical GTN (or diltiazem) is used for chronic fissures (6 weeks or more). Botulinum toxin or lateral sphincterotomy is used if these fail. Fissures off the midline suggest Crohn''s, HIV, TB or malignancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2acddb16-2e4d-5e0b-bc79-cf2ecd2c3d96', '68471fda-6419-5bc2-a37c-389a41bbf85f', 'A', 'Increase fibre and fluids, laxatives and topical analgesia, then topical GTN if not healing in 1 week', true, 0),
  ('dd960d7a-7528-5726-88f0-23343bbda637', '68471fda-6419-5bc2-a37c-389a41bbf85f', 'B', 'Oral antibiotics', false, 1),
  ('a92bccc9-935a-5c09-9a58-f905bcad4ea1', '68471fda-6419-5bc2-a37c-389a41bbf85f', 'C', 'Rubber band ligation', false, 2),
  ('b95e48f9-2be9-5fb5-acc0-452a0a56e2c4', '68471fda-6419-5bc2-a37c-389a41bbf85f', 'D', 'Lateral sphincterotomy as first-line', false, 3),
  ('bdcef0c3-f3a8-58ed-a5bb-0b6e3808f4b9', '68471fda-6419-5bc2-a37c-389a41bbf85f', 'E', 'Colonoscopy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b87e76c8-df30-5e50-86ec-3047f50e20c7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 55 year old man has had recurrent perianal abscesses and now has a persistent discharging opening near his anus. What is the SINGLE most appropriate investigation to delineate the anatomy?', 'A fistula-in-ano is an abnormal connection between the anal canal and the perianal skin, often after an abscess. MRI pelvis (or endoanal ultrasound) defines its course relative to the sphincters. Goodsall''s rule predicts the course. Treatment is fistulotomy for low fistulas, or a seton for high or complex ones, to avoid incontinence. Crohn''s disease should be considered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2381632d-0327-57ea-bb06-058b9ef61d4b', 'b87e76c8-df30-5e50-86ec-3047f50e20c7', 'A', 'MRI of the pelvis', true, 0),
  ('c812f3d2-1ed0-5b1d-99b2-0272e675f1e9', 'b87e76c8-df30-5e50-86ec-3047f50e20c7', 'B', 'Plain abdominal X-ray', false, 1),
  ('0c03c746-8313-5b53-b47d-41f0236c52e7', 'b87e76c8-df30-5e50-86ec-3047f50e20c7', 'C', 'Colonoscopy', false, 2),
  ('1a6daf80-0f61-5f4d-9bd5-2d7693034636', 'b87e76c8-df30-5e50-86ec-3047f50e20c7', 'D', 'Barium enema', false, 3),
  ('03167eb6-2fec-54bc-9799-bc85cad7c9d0', 'b87e76c8-df30-5e50-86ec-3047f50e20c7', 'E', 'CT abdomen', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1b0500bd-2f8e-5941-8b5a-58c50cbea6bf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 74 year old man has had painless jaundice, weight loss and pruritus. On examination there is a palpable, non-tender gallbladder. What is the SINGLE most likely diagnosis?', 'Courvoisier''s law: painless jaundice with a palpable gallbladder is unlikely to be caused by stones (which scar and shrink the gallbladder) and suggests malignant obstruction, such as cancer of the pancreatic head or cholangiocarcinoma. CT (pancreatic protocol) is the key investigation. Only about 20% of patients are resectable (Whipple''s procedure).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0be60a6a-757f-5e6e-a60e-d8b87d9198ac', '1b0500bd-2f8e-5941-8b5a-58c50cbea6bf', 'A', 'Hepatitis A', false, 0),
  ('eda296fd-2de3-5fc3-b041-394fa0beff97', '1b0500bd-2f8e-5941-8b5a-58c50cbea6bf', 'B', 'Carcinoma of the head of the pancreas', true, 1),
  ('ec6c865a-5318-5d58-a5b9-b85b91e2131d', '1b0500bd-2f8e-5941-8b5a-58c50cbea6bf', 'C', 'Primary biliary cholangitis', false, 2),
  ('cb4d6506-49b6-5ac6-8b66-0272e163775d', '1b0500bd-2f8e-5941-8b5a-58c50cbea6bf', 'D', 'Acute cholecystitis', false, 3),
  ('1bbc0668-9747-5103-86bb-ccdc4e1d9b16', '1b0500bd-2f8e-5941-8b5a-58c50cbea6bf', 'E', 'Gallstones in the common bile duct', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8ca9f5ab-b797-518f-ba17-99a2dd03a6d6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 66 year old man has had dysphagia for solids, a gurgling sound in his neck and regurgitation of undigested food with halitosis. He has a soft swelling on the left side of his neck. What is the SINGLE most likely diagnosis?', 'A pharyngeal pouch is a herniation through Killian''s dehiscence (between the thyropharyngeus and cricopharyngeus). It causes dysphagia, regurgitation, halitosis, aspiration and a neck lump. A barium swallow is diagnostic, and endoscopy should be avoided at first because of the risk of perforation. Treatment is endoscopic stapling or open surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('01b9c8a8-63b1-5923-a5d5-204f15977f78', '8ca9f5ab-b797-518f-ba17-99a2dd03a6d6', 'A', 'Oesophageal cancer', false, 0),
  ('f78536ec-fafa-547c-9695-d1185ba110c7', '8ca9f5ab-b797-518f-ba17-99a2dd03a6d6', 'B', 'Pharyngeal pouch (Zenker''s diverticulum)', true, 1),
  ('bae4b093-1250-59dc-82b4-608c97f75c7e', '8ca9f5ab-b797-518f-ba17-99a2dd03a6d6', 'C', 'Achalasia', false, 2),
  ('dc0ecdb9-03ae-525d-bcc8-96150505b6a5', '8ca9f5ab-b797-518f-ba17-99a2dd03a6d6', 'D', 'Globus pharyngeus', false, 3),
  ('bd362f92-7e6f-52aa-b52b-8a7ae1151759', '8ca9f5ab-b797-518f-ba17-99a2dd03a6d6', 'E', 'Thyroglossal cyst', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4dd9538f-7b82-5c27-abf7-baf3244948b1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 45 year old man has a 3 cm smooth, soft, mobile, painless lump on his back that has been present for years. It is not attached to the skin and has a ''slipping edge''. What is the SINGLE most likely diagnosis?', 'A lipoma is a benign tumour of fat, soft and mobile with a slipping edge. Features suggesting soft tissue sarcoma include size over 5 cm, rapid growth, pain, a deep site (below fascia) or recurrence after excision, which need urgent ultrasound and a suspected cancer referral. An epidermoid cyst is attached to the skin with a central punctum.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
