  ('3d0764e1-a490-5672-a6d2-b8fe32e12960', '4dd9538f-7b82-5c27-abf7-baf3244948b1', 'A', 'Sebaceous cyst', false, 0),
  ('179030cc-5a5d-5c2c-bcdc-f474fb51a3e2', '4dd9538f-7b82-5c27-abf7-baf3244948b1', 'B', 'Lymph node', false, 1),
  ('3c8490c2-5cd2-5e72-b073-059dbb7fa674', '4dd9538f-7b82-5c27-abf7-baf3244948b1', 'C', 'Lipoma', true, 2),
  ('c2b16ba3-71d2-5c20-b7e7-af524494825c', '4dd9538f-7b82-5c27-abf7-baf3244948b1', 'D', 'Ganglion', false, 3),
  ('9da1fc91-e41c-583b-8613-c3866026747b', '4dd9538f-7b82-5c27-abf7-baf3244948b1', 'E', 'Liposarcoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d1a6558f-b9ac-5872-9b31-e35c307319b3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 35 year old man has had a painful, swollen, red, hot great toe for 3 days. The nail fold is inflamed with pus at the lateral edge of his ingrown nail. What is the SINGLE most appropriate management?', 'An ingrown toenail (onychocryptosis) with paronychia is managed with warm soaks, drainage of any pus and antibiotics if there is spreading infection. For recurrent or persistent cases, a wedge resection of the nail edge with phenol ablation of the nail matrix prevents recurrence.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3851d1b8-f394-5b7f-9be4-f0209593fae8', 'd1a6558f-b9ac-5872-9b31-e35c307319b3', 'A', 'Oral aciclovir', false, 0),
  ('575698af-eaad-56db-8ec5-5e9b9ec258d9', 'd1a6558f-b9ac-5872-9b31-e35c307319b3', 'B', 'Drainage of the paronychia, with antibiotics if there is cellulitis, then wedge resection of the nail with phenolisation if recurrent', true, 1),
  ('d9fba5f5-ef51-5a98-a0b8-307f0fba8f52', 'd1a6558f-b9ac-5872-9b31-e35c307319b3', 'C', 'No treatment', false, 2),
  ('d391b195-2447-5dff-b219-cefc3663288f', 'd1a6558f-b9ac-5872-9b31-e35c307319b3', 'D', 'Topical steroid', false, 3),
  ('e38b65ab-a899-554a-9b8f-1e76d426dc55', 'd1a6558f-b9ac-5872-9b31-e35c307319b3', 'E', 'Below-knee amputation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6cef8a93-e28b-5e5a-949c-e530de796d30', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 58 year old man has had a 3 cm firm, painless, gradually enlarging lump in the upper outer quadrant of his left buttock after an injection 2 years ago. It is deep to fascia and has grown over 3 months. What is the SINGLE most appropriate management?', 'Red flags for soft tissue sarcoma are a lump over 5 cm, increasing in size, deep to fascia, painful or recurrent after excision. NICE recommends an urgent direct-access ultrasound within 2 weeks for adults with an unexplained lump that is increasing in size, and a suspected cancer referral if the ultrasound suggests sarcoma. Biopsy should be done at the sarcoma centre.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('94c6c8d3-735a-581a-aa99-e9a63e37fe81', '6cef8a93-e28b-5e5a-949c-e530de796d30', 'A', 'Excise in the GP surgery', false, 0),
  ('983b9c1d-39b6-53e2-a09f-5a7a1bac6655', '6cef8a93-e28b-5e5a-949c-e530de796d30', 'B', 'Review in 1 year', false, 1),
  ('a7ae0405-1de8-5170-b176-450ea3609297', '6cef8a93-e28b-5e5a-949c-e530de796d30', 'C', 'Incision and drainage', false, 2),
  ('c4a7dcf6-537c-58e6-ac4f-9a4e082a27fa', '6cef8a93-e28b-5e5a-949c-e530de796d30', 'D', 'Reassure; likely lipoma', false, 3),
  ('72a085d2-6313-5ee4-b421-7a524594e20d', '6cef8a93-e28b-5e5a-949c-e530de796d30', 'E', 'Urgent ultrasound and suspected cancer referral to a sarcoma service', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bfe9b56c-ce12-500f-a313-eaffbd87c2d2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 23 year old woman has a 2 cm painless, firm, mobile lump on the dorsum of her wrist that transilluminates and has been present for 4 months. It does not affect function. What is the SINGLE most appropriate management?', 'A ganglion is a fluid-filled cyst arising from a joint capsule or tendon sheath, most often on the dorsal wrist. It is smooth and transilluminates. Many resolve on their own, so reassurance is first-line. Aspiration or surgical excision is considered if it is painful or affects function, though recurrence is common.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
