insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('399215c3-6a1b-5531-9320-a3cf95ac2c2a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 42 year old woman with gallstones has an episode of severe RUQ pain lasting 2 hours after a fatty meal, which resolved fully. She is afebrile, with normal LFTs and WCC. Ultrasound confirms gallstones with a normal gallbladder wall. What is the SINGLE most appropriate management?', 'Biliary colic is pain from transient gallstone obstruction of the cystic duct, without inflammation (no fever or raised WCC). NICE recommends laparoscopic cholecystectomy for symptomatic gallstones to prevent recurrence and complications (cholecystitis, pancreatitis, cholangitis). Asymptomatic gallstones do not need treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
