insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9503fae7-b078-5ca4-a089-09c38c073274', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 68 year old man had an open abdominal aortic aneurysm repair 2 days ago. He has bloody diarrhoea and left-sided abdominal pain. What is the SINGLE most likely diagnosis?', 'After aortic surgery, sacrificing the inferior mesenteric artery can cause ischaemic colitis, typically left-sided with bloody diarrhoea. It is suspected early after surgery and confirmed by sigmoidoscopy. Mild cases are managed conservatively, while transmural necrosis needs a laparotomy and resection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
