insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3e1eba19-350e-58d0-9a6d-92d4743332a2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 65 year old man has a postoperative day 6 fever, tachycardia, worsening abdominal pain and peritonism after an anterior resection for rectal cancer. His CRP is rising. What is the SINGLE most likely diagnosis?', 'Anastomotic leak typically presents 5-7 days after bowel surgery with fever, tachycardia, abdominal pain and peritonism. CT with contrast confirms it. Management is resuscitation, antibiotics and often a laparotomy or percutaneous drainage. Postoperative fever by timing: day 1-2 atelectasis or inflammation, day 3-5 UTI or pneumonia, day 5-7 leak or abscess, and wound infection around day 5-10.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
