insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2a1a1cb3-f835-53fa-8464-6532e144c966', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 59 year old man has had a laparotomy for perforated diverticulitis. On day 8, after coughing, he notices a large amount of serosanguinous fluid soaking his dressing. What is the SINGLE most likely diagnosis?', 'Pink serosanguinous discharge from a laparotomy wound around days 7-10 suggests fascial dehiscence. Complete dehiscence with bowel showing is an emergency: cover the wound with saline-soaked swabs, give analgesia and return to theatre for closure. Risk factors include obesity, infection, malnutrition, steroids and raised intra-abdominal pressure (coughing).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
